// İstanbul Ulaşım — canlı otobüs/metrobüs, trafik, rota planlama, metro/tramvay/vapur sefer saatleri
// Veriler: İETT, Metro İstanbul (İBB Açık Veri), İBB trafik servisi, Şehir Hatları, Transitous.
// Tüm istekler bu telefondan yapılır; sunucu gerekmez.

const SURUM = "3.8";
const HTML = "<!DOCTYPE html>\n<html lang=\"tr\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1, viewport-fit=cover, maximum-scale=1\">\n<title>İstanbul Ulaşım</title>\n<link rel=\"stylesheet\" href=\"https://unpkg.com/leaflet@1.9.4/dist/leaflet.css\">\n<style>\n  :root { --bg:#f4f5f7; --kart:#fff; --yazi:#16191f; --soluk:#6b7280; --cizgi:#e5e7eb; --vurgu:#0f62fe; --iyi:#0a8f4f; --uyari:#b45309; --hata:#b91c1c; --sekme:56px; }\n  @media (prefers-color-scheme: dark) { :root { --bg:#0f1115; --kart:#1a1d23; --yazi:#eef0f3; --soluk:#9aa1ad; --cizgi:#2b2f37; --vurgu:#5b8cff; } }\n  * { box-sizing:border-box; -webkit-tap-highlight-color:transparent; }\n  html,body { margin:0; height:100%; background:var(--bg); color:var(--yazi); font:15px/1.4 -apple-system, system-ui, \"Segoe UI\", Roboto, sans-serif; overscroll-behavior:none; }\n  #harita { position:fixed; left:0; right:0; top:0; height:42vh; z-index:0; }\n  body.genis #harita { height:14vh; }\n  body.harita-buyuk #harita { height:72vh; }\n  #panel { position:fixed; left:0; right:0; top:calc(42vh - 14px); bottom:calc(var(--sekme) + env(safe-area-inset-bottom)); overflow-y:auto; -webkit-overflow-scrolling:touch; background:var(--bg); border-top-left-radius:16px; border-top-right-radius:16px; box-shadow:0 -4px 16px rgba(0,0,0,.12); z-index:5; transition:top .25s; }\n  body.genis #panel { top:calc(14vh - 14px); }\n  body.harita-buyuk #panel { top:calc(72vh - 14px); }\n  #tutamak { display:flex; justify-content:center; padding:10px 0 6px; cursor:grab; touch-action:none; }\n  #tutamak span { width:44px; height:5px; border-radius:3px; background:var(--soluk); opacity:.5; }\n  body.tam #harita { height:100vh; }\n  body.tam #panel { top:calc(100vh - var(--sekme) - env(safe-area-inset-bottom) - 74px); overflow:hidden; }\n  body.tam #panel #icerik { pointer-events:none; }\n  body.tam .harita-ust { top:calc(env(safe-area-inset-top) + 8px); }\n  #panel.suruk { transition:none; }\n  .arac-pop .leaflet-popup-content { margin:12px 14px; }\n  .arac-pop .leaflet-popup-content-wrapper, .arac-pop .leaflet-popup-tip { background:var(--kart); color:var(--yazi); }\n  .arac-kart { font-size:14px; line-height:1.4; padding:12px 14px; }\n  .ak-bas { display:flex; align-items:center; justify-content:space-between; gap:8px; }\n  .ak-kutu { margin:8px 0 4px; padding:8px 10px; border-radius:10px; background:var(--bg); }\n  .ak-buyuk { font-size:20px; font-weight:700; color:var(--vurgu); }\n  .ak-alt { margin-top:10px; font-weight:600; font-size:12px; text-transform:uppercase; letter-spacing:.3px; color:var(--soluk); }\n  .ak-liste { list-style:none; margin:4px 0 6px; padding:0; }\n  .ak-liste li { display:flex; justify-content:space-between; gap:8px; padding:3px 0; border-bottom:1px solid var(--cizgi); }\n  .ak-liste li:last-child { border-bottom:0; }\n  .ak-bar { height:5px; border-radius:3px; background:var(--cizgi); overflow:hidden; margin-top:4px; }\n  .ak-bar span { display:block; height:100%; }\n  .ak-saatler { display:flex; flex-wrap:wrap; gap:5px; margin:5px 0 3px; }\n  .ak-saatler span { padding:3px 7px; border-radius:7px; background:var(--bg); font-weight:600; font-variant-numeric:tabular-nums; }\n  .ak-saatler span.ilk { background:var(--vurgu); color:#fff; }\n  .ak-butonlar { display:flex; gap:8px; margin-top:10px; }\n  .ak-butonlar .btn { flex:1; }\n  .durak-etiket { background:var(--kart); color:var(--yazi); border:0; border-radius:8px; padding:3px 7px; font:600 12px/1.2 -apple-system, system-ui, sans-serif; box-shadow:0 1px 5px rgba(0,0,0,.3); }\n  .durak-etiket::before { display:none; }\n  .leaflet-tooltip.durak-etiket { white-space:nowrap; }\n  #icerik { padding:4px 14px 24px; }\n  nav#sekmeler { position:fixed; left:0; right:0; bottom:0; height:calc(var(--sekme) + env(safe-area-inset-bottom)); padding-bottom:env(safe-area-inset-bottom); display:flex; background:var(--kart); border-top:1px solid var(--cizgi); z-index:10; }\n  nav#sekmeler button { flex:1; border:0; background:none; color:var(--soluk); font:inherit; font-size:10.5px; display:flex; flex-direction:column; align-items:center; justify-content:center; gap:2px; }\n  nav#sekmeler button b { font-size:19px; font-weight:400; line-height:1; }\n  nav#sekmeler button.aktif { color:var(--vurgu); font-weight:600; }\n  .harita-ust { position:fixed; top:calc(env(safe-area-inset-top) + 8px); right:8px; z-index:6; display:flex; flex-direction:column; gap:6px; }\n  .harita-ust button { width:40px; height:40px; border-radius:10px; border:0; background:var(--kart); color:var(--yazi); font-size:19px; box-shadow:0 1px 6px rgba(0,0,0,.25); }\n  .harita-ust button.acik { background:var(--vurgu); color:#fff; }\n  #trafikBilgi { position:fixed; top:calc(env(safe-area-inset-top) + 8px); left:8px; z-index:6; background:var(--kart); border-radius:10px; padding:6px 9px; font-size:12px; box-shadow:0 1px 6px rgba(0,0,0,.25); display:none; max-width:62vw; }\n  #trafikBilgi .l { display:flex; gap:3px; margin-top:4px; align-items:center; }\n  #trafikBilgi .l i { display:inline-block; width:16px; height:5px; border-radius:2px; }\n  #secimBandi { position:fixed; top:calc(env(safe-area-inset-top) + 8px); left:8px; right:56px; z-index:7; background:#111827; color:#fff; border-radius:10px; padding:9px 12px; font-size:13px; display:none; }\n  #secimBandi button { margin-left:8px; }\n  h1 { font-size:20px; margin:4px 0 10px; display:flex; align-items:center; gap:8px; }\n  h2 { font-size:12px; letter-spacing:.05em; text-transform:uppercase; color:var(--soluk); margin:18px 0 8px; }\n  .geri { border:0; background:none; color:var(--vurgu); font:inherit; padding:0 4px 0 0; font-size:24px; line-height:1; }\n  .kart { background:var(--kart); border-radius:12px; margin-bottom:10px; overflow:hidden; border:1px solid var(--cizgi); }\n  .kart .bas { display:flex; align-items:center; gap:8px; padding:10px 12px; border-bottom:1px solid var(--cizgi); }\n  .kart .bas .ad { flex:1; font-weight:600; min-width:0; overflow:hidden; text-overflow:ellipsis; white-space:nowrap; }\n  .kart .alt { padding:8px 12px; font-size:13px; color:var(--soluk); }\n  .liste { list-style:none; margin:0; padding:0; }\n  .liste > li { display:flex; align-items:center; gap:10px; padding:10px 12px; border-top:1px solid var(--cizgi); }\n  .liste > li:first-child { border-top:0; }\n  .tik { cursor:pointer; }\n  .liste > li .ana { flex:1; min-width:0; }\n  .liste > li .ana small { display:block; color:var(--soluk); font-size:12px; white-space:nowrap; overflow:hidden; text-overflow:ellipsis; }\n  .rozet { display:inline-flex; align-items:center; gap:3px; color:#fff; font-weight:700; border-radius:7px; padding:2px 7px; font-size:13px; min-width:34px; justify-content:center; flex:none; white-space:nowrap; }\n  .sure { min-width:64px; text-align:center; font-weight:700; border-radius:9px; padding:4px 6px; background:#e8eefc; color:#1e3a8a; flex:none; font-size:14px; }\n  .sure.yakin { background:#dcfce7; color:var(--iyi); }\n  .sure.tarife { background:#f1f5f9; color:#334155; font-weight:600; }\n  @media (prefers-color-scheme: dark) { .sure { background:#1e2a4a; color:#a8c1ff; } .sure.yakin { background:#12351f; color:#7ee2a8; } .sure.tarife { background:#262b33; color:#cbd5e1; } }\n  .btn { border:1px solid var(--cizgi); background:var(--kart); color:var(--yazi); border-radius:10px; padding:9px 14px; font:inherit; }\n  .btn.ana { background:var(--vurgu); border-color:var(--vurgu); color:#fff; font-weight:600; }\n  .btn.kucuk { padding:5px 10px; font-size:13px; border-radius:8px; }\n  .btn.tam { width:100%; padding:12px; font-size:16px; }\n  .not { color:var(--soluk); font-size:12px; }\n  .hata { color:var(--hata); font-size:13px; }\n  .bos { color:var(--soluk); font-size:13px; padding:10px 12px; }\n  input.ara { width:100%; padding:11px 12px; border-radius:10px; border:1px solid var(--cizgi); background:var(--kart); color:var(--yazi); font:inherit; font-size:16px; }\n  .segment { display:flex; background:var(--cizgi); border-radius:10px; padding:2px; gap:2px; margin:8px 0; }\n  .segment button { flex:1; border:0; background:none; color:var(--yazi); font:inherit; font-size:13px; padding:7px 6px; border-radius:8px; white-space:nowrap; overflow:hidden; text-overflow:ellipsis; }\n  .segment button.aktif { background:var(--kart); font-weight:600; box-shadow:0 1px 2px rgba(0,0,0,.15); }\n  .saatler { display:flex; flex-wrap:wrap; gap:6px; padding:10px 12px; }\n  .saatler span { font-variant-numeric:tabular-nums; padding:3px 7px; border-radius:7px; background:var(--bg); font-size:13px; }\n  .saatler span.gecti { opacity:.35; }\n  .saatler span.sonraki { background:var(--vurgu); color:#fff; font-weight:700; }\n  .yildiz { border:0; background:none; font-size:22px; color:#f59e0b; padding:0 2px; }\n  ol.duraklar { list-style:none; margin:0; padding:6px 12px 10px; }\n  ol.duraklar li { position:relative; padding:7px 0 7px 26px; font-size:14px; cursor:pointer; }\n  ol.duraklar li::before { content:\"\"; position:absolute; left:8px; top:0; bottom:0; width:3px; background:var(--hr,#888); }\n  ol.duraklar li:first-child::before { top:50%; } ol.duraklar li:last-child::before { bottom:50%; }\n  ol.duraklar li::after { content:\"\"; position:absolute; left:3px; top:50%; margin-top:-6.5px; width:13px; height:13px; border-radius:50%; background:var(--kart); border:2.5px solid var(--hr,#888); box-sizing:border-box; }\n  ol.duraklar li.arac-satir { cursor:pointer; padding:5px 0 5px 26px; }\n  ol.duraklar li.arac-satir::after { display:none; }\n  .arac-cip { display:inline-block; color:#fff; font-weight:700; font-size:12.5px; padding:2px 8px; border-radius:8px; margin-left:6px; cursor:pointer; white-space:nowrap; }\n  ol.duraklar li.arac-satir .arac-cip { margin-left:-22px; box-shadow:0 0 0 3px var(--kart); }\n  ol.duraklar li.dolu::after { background:var(--hr); box-shadow:0 0 0 3px color-mix(in srgb, var(--hr) 35%, transparent); }\n  ol.duraklar li.benim { font-weight:700; } ol.duraklar li.benim::after { background:var(--hr); }\n  .etiket { font-size:11px; border-radius:6px; padding:1px 6px; margin-left:6px; background:#fef3c7; color:var(--uyari); white-space:nowrap; }\n  .duyuru { background:#fff7ed; color:#9a3412; border:1px solid #fed7aa; border-radius:10px; padding:8px 10px; font-size:13px; margin-bottom:8px; }\n  @media (prefers-color-scheme: dark) { .duyuru { background:#2d1a0c; color:#fdba74; border-color:#5b3415; } .etiket { background:#3a2a0a; } }\n  table.tarife { width:100%; border-collapse:collapse; font-size:13px; font-variant-numeric:tabular-nums; }\n  table.tarife th, table.tarife td { padding:5px 6px; text-align:center; border-top:1px solid var(--cizgi); }\n  table.tarife th { color:var(--soluk); font-weight:600; font-size:12px; }\n  table.tarife tr.gecti td { opacity:.35; }\n  table.tarife tr.yok td { opacity:.35; text-decoration:line-through; }\n  table.tarife tr.sonraki td { background:var(--vurgu); color:#fff; font-weight:700; }\n  .yukleniyor { color:var(--soluk); font-size:13px; padding:12px; }\n  /* Rota */\n  .yer-giris { display:flex; align-items:center; gap:8px; background:var(--kart); border:1px solid var(--cizgi); border-radius:12px; padding:4px 8px; margin-bottom:6px; }\n  .yer-giris .ikon { width:22px; text-align:center; font-size:15px; }\n  .yer-giris input { flex:1; border:0; background:none; color:var(--yazi); font:inherit; font-size:16px; padding:8px 2px; min-width:0; outline:none; }\n  .yer-giris button { border:0; background:none; color:var(--soluk); font-size:18px; padding:4px; }\n  .rota-ust { display:flex; gap:8px; align-items:stretch; }\n  .rota-ust .girisler { flex:1; min-width:0; }\n  .rota-ust .degis { border:1px solid var(--cizgi); background:var(--kart); border-radius:12px; width:40px; font-size:18px; color:var(--yazi); margin-bottom:6px; }\n  .oneriler { background:var(--kart); border:1px solid var(--cizgi); border-radius:12px; overflow:hidden; margin-bottom:10px; }\n  .zincir { display:flex; flex-wrap:wrap; align-items:center; gap:4px; }\n  .zincir .ok { color:var(--soluk); font-size:11px; }\n  .zincir .yuru { font-size:12px; color:var(--soluk); }\n  .bacak { display:flex; gap:10px; padding:10px 12px; border-top:1px solid var(--cizgi); }\n  .bacak:first-child { border-top:0; }\n  .bacak .zaman { width:44px; flex:none; font-variant-numeric:tabular-nums; font-weight:600; font-size:13px; padding-top:2px; }\n  .bacak .cizgi { width:4px; border-radius:2px; flex:none; }\n  .bacak .icerik { flex:1; min-width:0; font-size:14px; }\n  .bacak .icerik small { display:block; color:var(--soluk); font-size:12px; margin-top:2px; }\n  .canli { display:inline-block; font-size:11px; font-weight:700; color:var(--iyi); background:#dcfce7; border-radius:6px; padding:1px 6px; margin-left:4px; }\n  @media (prefers-color-scheme: dark) { .canli { background:#12351f; color:#7ee2a8; } }\n  .canli::before { content:\"● \"; animation:nabiz 1.4s infinite; }\n  @keyframes nabiz { 50% { opacity:.3; } }\n  /* Harita simgeleri */\n  .arac { transition: transform 1s linear; }\n  .leaflet-zoom-anim .arac, .leaflet-dragging .arac { transition:none; }\n  .arac .halka { position:absolute; left:0; top:0; width:38px; height:38px; }\n  .arac .govde { position:absolute; left:7px; top:7px; width:24px; height:24px; border-radius:50%; border:2px solid #fff; display:flex; align-items:center; justify-content:center; box-shadow:0 1px 4px rgba(0,0,0,.35); }\n  .arac.tahmini .govde { border-style:dashed; opacity:.9; }\n  .arac .govde svg { width:15px; height:15px; }\n  .arac .yazi { position:absolute; left:50%; top:33px; transform:translateX(-50%); background:rgba(17,24,39,.85); color:#fff; font:700 9.5px/1 -apple-system, system-ui, sans-serif; border-radius:4px; padding:2px 4px; white-space:nowrap; pointer-events:none; }\n  .ben-ikon { width:16px; height:16px; border-radius:50%; background:#0f62fe; border:3px solid #fff; box-shadow:0 0 0 2px #0f62fe, 0 0 12px rgba(15,98,254,.6); }\n  .uc-ikon { width:22px; height:22px; border-radius:50% 50% 50% 0; transform:rotate(-45deg); border:3px solid #fff; box-shadow:0 1px 5px rgba(0,0,0,.4); }\n  .leaflet-container { background:#e9ecef; }\n  @media (prefers-color-scheme: dark) { .leaflet-container { background:#1f2124; } }\n  .uzak .arac .yazi { display:none; }\n  .uzak .arac .govde { transform:scale(.8); }\n</style>\n</head>\n<body>\n<div id=\"harita\"></div>\n<div class=\"harita-ust\">\n  <button id=\"trafikBtn\" title=\"Trafik\">🚦</button>\n  <button id=\"konumBtn\" title=\"Konumum\">📍</button>\n</div>\n<div id=\"trafikBilgi\"></div>\n<div id=\"secimBandi\">Haritada bir noktaya dokunun<button class=\"btn kucuk\" id=\"secimIptal\">Vazgeç</button></div>\n<div id=\"panel\">\n  <div id=\"tutamak\" title=\"Aşağı kaydır: tam ekran harita\"><span></span></div>\n  <div id=\"icerik\"></div>\n</div>\n<nav id=\"sekmeler\">\n  <button data-sekme=\"yakin\" class=\"aktif\"><b>📍</b>Yakınımda</button>\n  <button data-sekme=\"rota\"><b>🧭</b>Rota</button>\n  <button data-sekme=\"otobus\"><b>🚌</b>Otobüs</button>\n  <button data-sekme=\"rayli\"><b>🚇</b>Raylı</button>\n  <button data-sekme=\"vapur\"><b>⛴</b>Vapur</button>\n</nav>\n\n<script src=\"https://unpkg.com/leaflet@1.9.4/dist/leaflet.js\"></script>\n<script>\n// ---- Yerel köprü: Scriptable içinde istekleri telefon yapar, tarayıcıda fetch kullanılır ----\nconst Native = (() => {\n  let seq = 0;\n  const pending = new Map();\n  let queue = [];\n  // Scriptable tarafı bunları sırayla çağırır\n  window.__bridgeTake = () => JSON.stringify(queue.splice(0));\n  window.__bridgeDeliver = (items) => {\n    for (const it of items) {\n      const p = pending.get(it.id);\n      if (!p) continue;\n      pending.delete(it.id);\n      it.ok ? p.res(it.data) : p.rej(new Error(it.data));\n    }\n  };\n  async function tarayici(kind, a) {\n    if (kind === \"http\") {\n      const r = await fetch(a.url, { method: a.method || \"GET\", headers: a.headers, body: a.body });\n      return { status: r.status, text: await r.text() };\n    }\n    if (kind === \"kvget\") { try { const v = localStorage.getItem(\"ulasim.\" + a.key); return v ? JSON.parse(v) : null; } catch { return null; } }\n    if (kind === \"kvset\") { try { localStorage.setItem(\"ulasim.\" + a.key, JSON.stringify(a.value)); } catch {} return true; }\n    if (kind === \"location\") {\n      return new Promise((res, rej) => navigator.geolocation.getCurrentPosition(\n        (p) => res({ lat: p.coords.latitude, lon: p.coords.longitude, acc: p.coords.accuracy }),\n        (e) => rej(new Error(e.message)), { enableHighAccuracy: true, timeout: 15000, maximumAge: 15000 }));\n    }\n    if (kind === \"open\") { window.open(a.url, \"_blank\"); return true; }\n    throw new Error(\"Bilinmeyen istek: \" + kind);\n  }\n  function call(kind, args = {}) {\n    if (window.__testNative) return window.__testNative(kind, args);\n    if (!window.__SCRIPTABLE__) return tarayici(kind, args);\n    return new Promise((res, rej) => {\n      const id = ++seq;\n      pending.set(id, { res, rej });\n      queue.push({ id, kind, args });\n    });\n  }\n  return { call };\n})();\n\n// ---- Kalıcı küçük depo (önbellek) ----\nconst KV = {\n  async get(key, maxAgeMs) {\n    try {\n      const v = await Native.call(\"kvget\", { key });\n      if (!v) return null;\n      if (maxAgeMs && Date.now() - v.t > maxAgeMs) return null;\n      return v.d;\n    } catch { return null; }\n  },\n  set(key, d) { return Native.call(\"kvset\", { key, value: { t: Date.now(), d } }).catch(() => {}); },\n};\n\n// ---- Veri kaynakları ----\nconst API = (() => {\n  const IETT = \"https://api.ibb.gov.tr/iett\";\n  const METRO = \"https://api.ibb.gov.tr/MetroIstanbul/api/MetroMobile/V2/\";\n  const VAPUR = \"https://sehirhatlari.istanbul\";\n  const GUN = 864e5;\n  const mem = new Map();\n\n  async function http(url, opt = {}) {\n    const r = await Native.call(\"http\", { url, ...opt });\n    if (!r || r.status >= 400 && r.status !== 500) throw new Error(`Sunucu hatası (${r && r.status})`);\n    return r.text;\n  }\n\n  // İETT SOAP çağrısı -> <Metot>Result elemanının içeriği\n  async function soap(path, method, params) {\n    const inner = Object.entries(params).map(([k, v]) => `<${k}>${String(v).replace(/[<>&]/g, \"\")}</${k}>`).join(\"\");\n    const body = '<?xml version=\"1.0\" encoding=\"utf-8\"?><soap:Envelope xmlns:soap=\"http://schemas.xmlsoap.org/soap/envelope/\">' +\n      `<soap:Body><${method} xmlns=\"http://tempuri.org/\">${inner}</${method}></soap:Body></soap:Envelope>`;\n    const text = await http(IETT + path, { method: \"POST\", headers: { \"Content-Type\": \"text/xml; charset=utf-8\", SOAPAction: `\"http://tempuri.org/${method}\"` }, body });\n    const doc = new DOMParser().parseFromString(text, \"text/xml\");\n    const node = doc.getElementsByTagName(method + \"Result\")[0];\n    if (!node) {\n      const f = doc.getElementsByTagName(\"faultstring\")[0];\n      throw new Error(\"İETT: \" + (f ? f.textContent : \"beklenmeyen cevap\"));\n    }\n    return node;\n  }\n\n  // Önbellekli getirici: önce bellek, sonra telefon deposu, sonra ağ\n  async function cached(key, maxAge, fn) {\n    const m = mem.get(key);\n    if (m && Date.now() - m.t < maxAge) return m.d;\n    let d = await KV.get(key, maxAge);\n    if (d == null) { d = await fn(); KV.set(key, d); }\n    mem.set(key, { t: Date.now(), d });\n    return d;\n  }\n\n  const iett = {\n    // Tüm İETT hatları (otobüs + metrobüs), günde bir yenilenir\n    hatlar: () => cached(\"iett.hatlar\", GUN, async () => {\n      const n = await soap(\"/UlasimAnaVeri/HatDurakGuzergah.asmx\", \"GetHat_json\", { HatKodu: \"\" });\n      return JSON.parse(n.textContent || \"[]\").map((h) => ({ kod: h.SHATKODU, ad: h.SHATADI, tarife: h.TARIFE, km: h.HAT_UZUNLUGU, dk: h.SEFER_SURESI }));\n    }),\n    async hat(kod) { return (await iett.hatlar()).find((h) => h.kod === kod) || null; },\n    konum: async (kod) => {\n      const n = await soap(\"/FiloDurum/SeferGerceklesme.asmx\", \"GetHatOtoKonum_json\", { HatKodu: kod });\n      return JSON.parse(n.textContent || \"[]\").map((b) => ({\n        kapino: b.kapino, lat: +b.enlem, lon: +b.boylam, yon: (b.guzergahkodu || \"\").split(\"_\")[1] || \"\",\n        yonAdi: b.yon, zaman: b.son_konum_zamani, yakinDurak: b.yakinDurakKodu,\n      })).filter((b) => isFinite(b.lat) && isFinite(b.lon));\n    },\n    duraklar: (kod) => cached(\"iett.durak.\" + kod, 7 * GUN, async () => {\n      const n = await soap(\"/ibb/ibb.asmx\", \"DurakDetay_GYY\", { hat_kodu: kod });\n      const yon = {};\n      for (const t of n.getElementsByTagName(\"Table\")) {\n        const g = (x) => (t.getElementsByTagName(x)[0]?.textContent || \"\").trim();\n        const d = { sira: +g(\"SIRANO\"), kod: g(\"DURAKKODU\"), ad: g(\"DURAKADI\"), lat: +g(\"YKOORDINATI\"), lon: +g(\"XKOORDINATI\") };\n        if (!isFinite(d.lat) || !isFinite(d.lon)) continue;\n        (yon[g(\"YON\")] ||= []).push(d);\n      }\n      Object.values(yon).forEach((l) => l.sort((a, b) => a.sira - b.sira));\n      return yon;\n    }),\n    // Planlanan kalkış saatleri: {D:{I:[..],C:[..],P:[..]}, G:{...}}\n    seferler: (kod) => cached(\"iett.sefer.\" + kod, GUN, async () => {\n      const n = await soap(\"/UlasimAnaVeri/PlanlananSeferSaati.asmx\", \"GetPlanlananSeferSaati_json\", { HatKodu: kod });\n      const out = {};\n      for (const s of JSON.parse(n.textContent || \"[]\")) {\n        const y = s.SYON, g = s.SGUNTIPI;\n        if (!y || !g || !s.DT) continue;\n        ((out[y] ||= {})[g] ||= []).push(s.DT);\n      }\n      for (const y of Object.values(out)) for (const g of Object.keys(y)) y[g] = [...new Set(y[g])].sort(Zaman.siraKarsilastir);\n      return out;\n    }),\n  };\n\n  async function metroGet(p) {\n    const j = JSON.parse(await http(METRO + p));\n    if (!j.Success) throw new Error(\"Metro İstanbul: \" + (j.Error?.Message || \"hata\"));\n    return j.Data;\n  }\n  const metro = {\n    hatlar: () => cached(\"metro.hatlar\", GUN, async () => (await metroGet(\"GetLines\")).filter((l) => l.IsActive !== false).map((l) => ({\n      id: l.Id, ad: l.Name, uzun: (l.LongDescription || l.ShortDescription || \"\").trim(), sira: l.Order,\n      renk: l.Color ? `rgb(${l.Color.Color_R},${l.Color.Color_G},${l.Color.Color_B})` : \"#666\", ilk: l.FirstTime, son: l.LastTime,\n    })).sort((a, b) => a.sira - b.sira)),\n    istasyonlar: () => cached(\"metro.istasyonlar.2\", GUN, async () => (await metroGet(\"GetStations\")).map((s) => {\n      // Metro İstanbul verisinde koordinatı boş gelen yeni istasyonlar (yaklaşık konum)\n      const EK = { 253: [40.9792, 29.2445], 254: [40.9727, 29.2566], 255: [40.9655, 29.2690] };\n      let lat = +(s.DetailInfo?.Latitude), lon = +(s.DetailInfo?.Longitude);\n      if ((!lat || !lon) && EK[s.Id]) [lat, lon] = EK[s.Id];\n      return { id: s.Id, ad: s.Description || s.Name, hatId: s.LineId, hat: s.LineName, sira: s.Order, lat, lon };\n    }).filter((s) => isFinite(s.lat) && isFinite(s.lon) && s.lat && s.lon)),\n    yonler: (hatId) => cached(\"metro.yon.\" + hatId, GUN, async () => (await metroGet(\"GetDirectionById/\" + hatId)).map((d) => ({ id: d.DirectionId, ad: d.DirectionName }))),\n    // İstasyondan sıradaki kalkışlar\n    async saatler(istId, hatId, yonId) {\n      const j = JSON.parse(await http(METRO + \"GetTimeTable\", {\n        method: \"POST\", headers: { \"Content-Type\": \"application/json\" },\n        body: JSON.stringify({ BoardingStationId: istId, LineId: hatId, DirectionId: yonId, DateTime: Zaman.yerelISO() }),\n      }));\n      if (!j.Success) throw new Error(\"Metro İstanbul: \" + (j.Error?.Message || \"hata\"));\n      const d = (j.Data || [])[0];\n      return d ? { hedef: d.LastStation, saatler: d.TimeInfos?.Times || [] } : { hedef: \"\", saatler: [] };\n    },\n    durum: async () => {\n      try { return (await metroGet(\"GetServiceStatuses\")).filter((s) => s.IsActive).map((s) => ({ hatId: s.LineId, hat: s.LineName, metin: (s.Description || \"\").trim() })); }\n      catch { return []; }\n    },\n  };\n\n  const vapur = {\n    hatlar: () => cached(\"vapur.hatlar\", GUN, async () => {\n      const doc = new DOMParser().parseFromString(await http(VAPUR + \"/tr/seferler\"), \"text/html\");\n      const seen = new Set(), out = [];\n      for (const a of doc.querySelectorAll('a[href*=\"/seferler/ic-hatlar/\"]')) {\n        const href = a.getAttribute(\"href\");\n        const parca = href.split(\"/\").filter(Boolean);\n        if (parca.length < 5 || seen.has(href)) continue; // sadece hat sayfaları\n        seen.add(href);\n        const grup = { \"istanbul-ici-hatlar\": \"İstanbul İçi\", \"bogaz-hatlari\": \"Boğaz\", \"adalar-hatlari\": \"Adalar\" }[parca[3]] || \"Diğer\";\n        out.push({ ad: a.textContent.trim().replace(/\\s+/g, \" \"), url: VAPUR + href, grup });\n      }\n      return out;\n    }),\n    // Hat sayfasındaki tarife tabloları\n    tarife: (url) => cached(\"vapur.t.\" + url, 6 * 36e5, async () => {\n      const doc = new DOMParser().parseFromString(await http(url), \"text/html\");\n      const tablolar = [];\n      let baslik = \"\";\n      for (const el of doc.querySelectorAll(\"h2, table\")) {\n        if (el.tagName === \"H2\") { baslik = el.textContent.trim().replace(/\\s+/g, \" \"); continue; }\n        const satirlar = [...el.querySelectorAll(\"tr\")].map((tr) => [...tr.children].map((c) => c.textContent.trim().replace(/\\s+/g, \" \")));\n        if (!satirlar.length) continue;\n        const ilkVeri = satirlar.findIndex((r) => r.some((c) => /^\\d{1,2}[:.]\\d{2}/.test(c)));\n        if (ilkVeri < 0) continue;\n        const ust = satirlar.slice(0, ilkVeri);\n        const not = ust.filter((r) => r.length === 1).map((r) => r[0]).join(\" \");\n        const basliklar = ust.filter((r) => r.length > 1);\n        tablolar.push({ baslik, not, basliklar, satirlar: satirlar.slice(ilkVeri) });\n      }\n      return tablolar;\n    }),\n  };\n\n  // Tüm vapur hatlarının tarifeleri (rota planlayıcı için), aynı anda en fazla 4 istek\n  vapur.tumu = async () => {\n    const hatlar = await vapur.hatlar();\n    const out = new Array(hatlar.length); let i = 0;\n    async function isci() { while (i < hatlar.length) { const k = i++; try { out[k] = { ad: hatlar[k].ad, tablolar: await vapur.tarife(hatlar[k].url) }; } catch { out[k] = null; } } }\n    await Promise.all([isci(), isci(), isci(), isci()]);\n    return out.filter(Boolean);\n  };\n\n  // ---- İBB trafik yoğunluk verisi (uym.ibb.gov.tr haritasının kullandığı servis) ----\n  const TKM = \"https://tkmservices.ibb.gov.tr/web/api/\";\n  const trafik = {\n    // Yol parçası geometrileri: [[id, [lat,lon,lat,lon,...], minLat, minLon, maxLat, maxLon]]\n    geometri: (seviye) => cached(\"trafik.geo.\" + seviye, 7 * GUN, async () => {\n      const l = JSON.parse(await http(TKM + \"TrafficData/v3/Segments/\" + seviye));\n      return l.map((s) => {\n        let g; try { g = JSON.parse(s.G); } catch { return null; }\n        const duz = []; let a = 90, b = 180, c = -90, d = -180;\n        for (const [la, lo] of g) { duz.push(Math.round(la * 1e5) / 1e5, Math.round(lo * 1e5) / 1e5); if (la < a) a = la; if (lo < b) b = lo; if (la > c) c = la; if (lo > d) d = lo; }\n        return [s.S, duz, a, b, c, d];\n      }).filter(Boolean);\n    }),\n    // Anlık hız ve yoğunluk: Map(id -> [seviye 0-5, hız km/sa])\n    async veri() {\n      const m = mem.get(\"trafik.veri\");\n      if (m && Date.now() - m.t < 90e3) return m.d;\n      const j = JSON.parse(await http(TKM + \"TrafficData/v4/SegmentData\"));\n      const d = new Map((j.Data || []).map((x) => [x.S, [x.C, x.V]]));\n      mem.set(\"trafik.veri\", { t: Date.now(), d });\n      return d;\n    },\n    async indeks() { try { return JSON.parse(await http(TKM + \"TrafficData/v1/TrafficIndex_Sc1_Cont\")); } catch { return null; } },\n  };\n  const iskeleler = () => cached(\"iskeleler\", 30 * GUN, async () =>\n    JSON.parse(await http(TKM + \"IntensityMap/v2/Piers\")).map((p) => ({ ad: p.NM, lat: +p.LT, lon: +p.LN, op: p.OP })).filter((p) => p.lat && p.lon));\n\n  // ---- Transitous: açık kaynak toplu taşıma rota servisi (İETT otobüsleri) ----\n  const TR = \"https://api.transitous.org/api/v1/\";\n  const transitous = {\n    async plan(a, b, zamanISO) {\n      const u = `${TR}plan?fromPlace=${a.lat},${a.lon}&toPlace=${b.lat},${b.lon}&time=${encodeURIComponent(zamanISO)}&numItineraries=5&maxPreTransitTime=1200&maxPostTransitTime=1200`;\n      const j = JSON.parse(await http(u));\n      return j.itineraries || [];\n    },\n    async yerAra(metin, yakin) {\n      const u = `${TR}geocode?text=${encodeURIComponent(metin)}&language=tr` + (yakin ? `&place=${yakin.lat},${yakin.lon}` : \"&place=41.01,28.98\");\n      const l = JSON.parse(await http(u));\n      return l.filter((x) => x.lat > 40.7 && x.lat < 41.4 && x.lon > 27.9 && x.lon < 29.95).map((x) => ({\n        ad: x.name, alt: x.type === \"STOP\" ? \"Durak\" : x.type === \"ADDRESS\" ? \"Adres\" : \"Yer\", lat: x.lat, lon: x.lon, tur: x.type === \"STOP\" ? \"durak\" : \"yer\",\n      }));\n    },\n  };\n\n  // Rota ağı verisi: raylı + metrobüs + iskeleler (+ vapur tarifeleri ayrıca)\n  const ag = {\n    async temel() {\n      const [hatlar, istasyonlar, mb, isk] = await Promise.all([metro.hatlar(), metro.istasyonlar(), iett.duraklar(\"34G\").catch(() => ({})), iskeleler().catch(() => [])]);\n      return { hatlar, istasyonlar, metrobus: mb, iskeleler: isk };\n    },\n    // Tüm İETT hatlarının durak sırası (haftada bir indirilir). ilerleme(bitti, toplam)\n    async otobus(ilerleme, zorla) {\n      const ANAHTAR = \"iett.ag.v1\";\n      if (!zorla) { const c = await KV.get(ANAHTAR, 7 * GUN); if (c && c.hatlar && c.hatlar.length > 100) return c; }\n      const hatlar = await iett.hatlar();\n      const ob = { duraklar: {}, hatlar: [], zaman: Date.now() };\n      let i = 0, bitti = 0;\n      async function isci() {\n        while (i < hatlar.length) {\n          const h = hatlar[i++];\n          try {\n            const yonler = await iett.duraklar(h.kod);\n            const yon = {};\n            for (const [y, l] of Object.entries(yonler)) {\n              yon[y] = l.map((d) => { ob.duraklar[d.kod] = [Math.round(d.lat * 1e5) / 1e5, Math.round(d.lon * 1e5) / 1e5, d.ad]; return d.kod; });\n            }\n            if (Object.keys(yon).length) ob.hatlar.push({ kod: h.kod, mb: /METROBÜS/i.test(h.tarife || \"\"), yon });\n          } catch {}\n          bitti++; if (ilerleme && (bitti % 10 === 0 || bitti === hatlar.length)) ilerleme(bitti, hatlar.length, ob);\n        }\n      }\n      await Promise.all(Array.from({ length: 6 }, isci));\n      if (ob.hatlar.length > 100) KV.set(ANAHTAR, ob);\n      return ob;\n    },\n  };\n\n  return { iett, metro, vapur, trafik, iskeleler, transitous, ag, http };\n})();\n\n// Google polyline çözücü (Transitous hassasiyet 7 kullanır)\nfunction polylineCoz(s, hassasiyet = 7) {\n  const k = Math.pow(10, hassasiyet), out = []; let i = 0, la = 0, lo = 0;\n  while (i < s.length) {\n    for (const ek of [0, 1]) {\n      let b, sh = 0, r = 0;\n      do { b = s.charCodeAt(i++) - 63; r |= (b & 0x1f) << sh; sh += 5; } while (b >= 0x20);\n      const d = r & 1 ? ~(r >> 1) : r >> 1;\n      if (ek === 0) la += d; else lo += d;\n    }\n    out.push([la / k, lo / k]);\n  }\n  return out;\n}\n\n// ---- Zaman yardımcıları ----\nconst Zaman = {\n  // \"06:15 *\" -> dakika; gece yarısından sonraki saatleri (00:00-03:59) güne ekler\n  dk(s) {\n    const m = /(\\d{1,2})[:.](\\d{2})/.exec(s || \"\");\n    if (!m) return null;\n    let v = +m[1] * 60 + +m[2];\n    if (+m[1] < 4) v += 1440;\n    return v;\n  },\n  simdi() { const d = new Date(); let v = d.getHours() * 60 + d.getMinutes(); if (d.getHours() < 4) v += 1440; return v; },\n  siraKarsilastir(a, b) { return Zaman.dk(a) - Zaman.dk(b); },\n  gunTipi(d = new Date()) { const g = d.getDay(); return g === 0 ? \"P\" : g === 6 ? \"C\" : \"I\"; },\n  yerelISO() { const d = new Date(), p = (n) => String(n).padStart(2, \"0\"); return `${d.getFullYear()}-${p(d.getMonth() + 1)}-${p(d.getDate())}T${p(d.getHours())}:${p(d.getMinutes())}:00`; },\n  kalan(s) { const v = Zaman.dk(s); if (v == null) return null; let k = v - Zaman.simdi(); if (k < -720) k += 1440; return k; },\n  kalanYazi(k) { if (k == null) return \"\"; if (k <= 0) return \"şimdi\"; if (k < 60) return k + \" dk\"; return Math.floor(k / 60) + \" sa \" + (k % 60) + \" dk\"; },\n};\n\n</script>\n<script>\n// ---- Hesaplama çekirdeği (harita ve arayüzden bağımsız) ----\nconst Core = (() => {\n  const R = 6371000;\n  const rad = (d) => (d * Math.PI) / 180;\n\n  // İki nokta arası kuş uçuşu mesafe (metre)\n  function mesafe(a, b) {\n    const dLat = rad(b.lat - a.lat), dLon = rad(b.lon - a.lon);\n    const h = Math.sin(dLat / 2) ** 2 +\n      Math.cos(rad(a.lat)) * Math.cos(rad(b.lat)) * Math.sin(dLon / 2) ** 2;\n    return 2 * R * Math.asin(Math.sqrt(h));\n  }\n\n  // İki nokta arası yön açısı (derece, kuzey = 0)\n  function yonAcisi(a, b) {\n    const y = Math.sin(rad(b.lon - a.lon)) * Math.cos(rad(b.lat));\n    const x = Math.cos(rad(a.lat)) * Math.sin(rad(b.lat)) -\n      Math.sin(rad(a.lat)) * Math.cos(rad(b.lat)) * Math.cos(rad(b.lon - a.lon));\n    return ((Math.atan2(y, x) * 180) / Math.PI + 360) % 360;\n  }\n\n  // Bir noktaya en yakın durağın sırası\n  function enYakinIndex(duraklar, p) {\n    let best = -1, bd = Infinity;\n    duraklar.forEach((d, i) => { const m = mesafe(d, p); if (m < bd) { bd = m; best = i; } });\n    return { index: best, metre: bd };\n  }\n\n  // Otobüsün güzergahta sıradaki (henüz geçmediği) durağın sırası\n  function siradakiDurak(duraklar, bus) {\n    let i = duraklar.findIndex((d) => d.kod === bus.yakinDurak);\n    if (i < 0) i = enYakinIndex(duraklar, bus).index;\n    if (i < 0) return -1;\n    // Otobüs bu duraktan bir sonrakine, bu durağın kendisinden daha yakınsa durağı geçmiş demektir\n    if (i < duraklar.length - 1) {\n      const sonraki = duraklar[i + 1];\n      if (mesafe(bus, sonraki) < mesafe(duraklar[i], sonraki)) i += 1;\n    }\n    return i;\n  }\n\n  // Hattın ortalama hızı (km/sa): hat uzunluğu / sefer süresi, makul aralıkta tutulur\n  function ortalamaHiz(hat) {\n    const km = Number(hat && hat.uzunlukKm), dk = Number(hat && hat.seferSuresiDk);\n    let v = km > 0 && dk > 0 ? km / (dk / 60) : 15;\n    return Math.min(35, Math.max(8, v));\n  }\n\n  const YOL_KATSAYISI = 1.15; // duraklar arası kuş uçuşu -> yol mesafesi düzeltmesi\n\n  // Bir otobüsün hedef durağa kaç durak ve kaç dakika uzakta olduğu\n  // Geçtiyse null döner.\n  function varisTahmini(duraklar, bus, hedefIndex, hizKmSa) {\n    const s = siradakiDurak(duraklar, bus);\n    if (s < 0 || s > hedefIndex) return null;\n    let m = mesafe(bus, duraklar[s]);\n    for (let k = s; k < hedefIndex; k++) m += mesafe(duraklar[k], duraklar[k + 1]);\n    m *= YOL_KATSAYISI;\n    const dk = m / 1000 / hizKmSa * 60;\n    return { durakSayisi: hedefIndex - s, metre: Math.round(m), dakika: Math.max(0, Math.round(dk)), siradakiIndex: s };\n  }\n\n  // Bir hattın bir yönü için: hedef duraka yaklaşan otobüsler, en yakından uzağa\n  function yaklasanlar(duraklar, otobusler, yon, hedefIndex, hizKmSa) {\n    return otobusler\n      .filter((b) => b.yon === yon)\n      .map((b) => ({ bus: b, t: varisTahmini(duraklar, b, hedefIndex, hizKmSa) }))\n      .filter((x) => x.t)\n      .sort((a, b) => a.t.metre - b.t.metre);\n  }\n\n  return { mesafe, yonAcisi, enYakinIndex, siradakiDurak, ortalamaHiz, varisTahmini, yaklasanlar };\n})();\n\n</script>\n<script>\n// ---- Rota planlayıcı v4: otobüs + metrobüs + metro/tramvay/füniküler/teleferik + Marmaray + vapur ----\n// Ağ: durak düğümleri + her hattın her durağı için \"araçta\" düğümü. Dijkstra (en erken varış + aktarma cezası).\n// Zamanlar \"günün dakikası\" (gece 00-04 arası +1440).\nconst Plan = (() => {\n  const YURUME_M_DK = 80, YURUME_SAPMA = 1.25;\n  const ERISIM_M = 1200, ERISIM_GENIS_M = 2500, ERISIM_MAX_DURAK = 40;\n  const AKTARMA_RAYLI_M = 600, AKTARMA_OTOBUS_M = 350;\n  const BINIS_CEZASI = 10;     // her biniş (aktarma) için ceza: aktarmalı rota ancak çok daha hızlıysa seçilir\n  const TUR_HIZ = { metro: 34, tram: 16, fun: 12, tf: 10, vapur: 20 };\n  const TUR_ARALIK = { metro: 6, tram: 6, fun: 5, tf: 4 };\n  const TUR_ADI = { metro: \"Metro\", marmaray: \"Marmaray\", tram: \"Tramvay\", fun: \"Füniküler\", tf: \"Teleferik\", mb: \"Metrobüs\", vapur: \"Vapur\", otobus: \"Otobüs\", yuru: \"Yürüme\" };\n  const HAT_TOPLAM = { M1A: 33, M1B: 22, M2: 29, M4: 46, M5: 43, M6: 6, M7: 32, M8: 24, T1: 60, T4: 42, T5: 34, F1: 2.5, F4: 2.5 };\n  const MARMARAY = [[\"Gebze\",40.78425,29.40956,0],[\"Darıca\",40.79142,29.39184,2.8],[\"Osmangazi\",40.79927,29.38001,4.8],[\"Fatih\",40.80763,29.36393,7.3],[\"Çayırova\",40.8105,29.34751,9.4],[\"Tuzla\",40.82995,29.32236,13.9],[\"İçmeler\",40.84565,29.30006,17.6],[\"Aydıntepe\",40.85229,29.29317,19.1],[\"Güzelyalı\",40.85685,29.2835,20.7],[\"Tersane\",40.86098,29.27336,22.4],[\"Kaynarca\",40.8713,29.25603,25.1],[\"Pendik\",40.88021,29.23167,28.6],[\"Yunus\",40.8845,29.21054,31.3],[\"Kartal\",40.88861,29.19119,33.9],[\"Başak\",40.89056,29.17735,36.1],[\"Atalar\",40.89859,29.16945,37.9],[\"Cevizli\",40.91002,29.15605,40.4],[\"Maltepe\",40.92065,29.13353,43.6],[\"Süreyya Plajı\",40.92683,29.1242,45.3],[\"İdealtepe\",40.93781,29.11426,47.5],[\"Küçükyalı\",40.94626,29.10682,49.5],[\"Bostancı\",40.9538,29.09506,51.6],[\"Suadiye\",40.96048,29.08442,53.6],[\"Erenköy\",40.97141,29.07647,55.9],[\"Göztepe\",40.97916,29.06256,58.3],[\"Feneryolu\",40.9787,29.04901,60.1],[\"Söğütlüçeşme\",40.9909,29.03763,62.6],[\"Ayrılıkçeşme\",41.00014,29.03014,64.6],[\"Üsküdar\",41.02576,29.01379,70],[\"Sirkeci\",41.01355,28.97705,74.8],[\"Yenikapı\",41.00478,28.94958,78.5],[\"Kazlıçeşme\",40.99269,28.91688,83.2],[\"Zeytinburnu\",40.98587,28.90545,85.2],[\"Yenimahalle\",40.98174,28.88105,88.4],[\"Bakırköy\",40.98027,28.87232,89.7],[\"Ataköy\",40.98022,28.85623,91.7],[\"Yeşilyurt\",40.96548,28.83728,95.4],[\"Yeşilköy\",40.96266,28.82488,97.1],[\"Florya Akvaryum\",40.96777,28.79705,100.7],[\"Florya\",40.97296,28.78748,102.3],[\"Küçükçekmece\",40.98853,28.77295,105.8],[\"Mustafa Kemal\",41.00628,28.77395,109.1],[\"Halkalı\",41.01784,28.76644,111.6]];\n  const MARMARAY_RENK = \"#4a8fd4\", METROBUS_RENK = \"#c2410c\";\n\n  const yurume = (m) => (m * YURUME_SAPMA) / YURUME_M_DK;\n  // Yürüyüş pahalı: ilk 3 dk normal, sonra giderek ağırlaşır\n  const yurumeMaliyet = (w) => w <= 3 ? w * 1.2 : w <= 8 ? 3.6 + (w - 3) * 2.2 : 14.6 + (w - 8) * 3.5;\n  const norm = (s) => String(s || \"\").toLocaleLowerCase(\"tr\").replace(/\\(.*?\\)/g, \"\").replace(/iskelesi|i̇do|\\bido\\b|terminali|\\(eski\\)/g, \"\").replace(/[^a-zçğıöşü0-9]/g, \"\");\n  const ISKELE_TAKMA = { eyupsultan: \"eyüp\", ahisari: \"anadoluhisarı\", ahisarı: \"anadoluhisarı\" };\n  const EK_ISKELE = [{ ad: \"Hasköy\", lat: 41.0399, lon: 28.9493 }, { ad: \"Aşiyan\", lat: 41.0818, lon: 29.0546 }, { ad: \"Küçüksu\", lat: 41.0786, lon: 29.0661 }, { ad: \"Sedef Adası\", lat: 40.8516, lon: 29.1414 }];\n  const bas = (s) => String(s || \"\").toLocaleLowerCase(\"tr\").replace(/(^|[\\s/(.\\-])(\\S)/g, (m, a, b) => a + b.toLocaleUpperCase(\"tr\")).replace(/\\s*Hattı$/i, \"\").trim();\n\n  function turOf(hatAd) { if (/^TF/.test(hatAd)) return \"tf\"; if (/^T\\d/.test(hatAd)) return \"tram\"; if (/^F\\d/.test(hatAd)) return \"fun\"; return \"metro\"; }\n\n  // Saate göre otobüs hız profili (km/sa): şehir içi taban hız, uzun aralıklarda otoyol hızı\n  function otobusHiz(dk, gun) {\n    const s = ((dk % 1440) + 1440) % 1440 / 60, hi = gun >= 1 && gun <= 5;\n    if (s >= 23 || s < 6) return { sehir: 24, yol: 60 };\n    if (hi && ((s >= 7 && s < 10) || (s >= 17 && s < 20))) return { sehir: 15, yol: 32 };\n    if (s >= 21) return { sehir: 21, yol: 52 };\n    return { sehir: 18, yol: 42 };\n  }\n  // \"06:00\",\"00:25\" -> [360, 1465] (gece yarısından sonra biten hatlar için +1440)\n  function calismaSaatleri(ilk, son) {\n    const a = Zaman.dk(ilk), b = Zaman.dk(son);\n    if (a == null || b == null) return null;\n    const ia = a >= 1440 ? a - 1440 : a;\n    return [ia, b <= ia ? b + 1440 : b];\n  }\n  // Bir desende i. duraktan t anında binmek için bekleme (dk). Çalışma saatleri dışındaysa sabah ilk sefere kadar.\n  function bekleHesap(p, i, t, opt) {\n    const ozel = opt && opt.bekleme ? opt.bekleme(p, i, t) : undefined;\n    if (ozel !== undefined) return ozel;               // planlanan sefer saatinden (ya da null: sefer yok)\n    const ort = p.aralik / 2;\n    if (!p.saatler) return ort;\n    const [ilk, son] = p.saatler, bas = t - p.t[i];    // aracın ilk istasyondan kalkış anı\n    for (const g of [-1440, 0, 1440]) if (bas >= ilk + g && bas <= son + g) return ort;\n    let en = Infinity;\n    for (const g of [0, 1440, 2880]) { const v = ilk + g + p.t[i]; if (v >= t && v < en) en = v; }\n    return en - t;\n  }\n  // Varsayılan sefer aralığı (planlanan sefer saati yoksa)\n  function otobusAralik(dk) { const s = ((dk % 1440) + 1440) % 1440 / 60; return s >= 23 || s < 6 ? 25 : s >= 21 ? 18 : 12; }\n\n  // ---------- Vapur tablosu yardımcıları ----------\n  function bugunYapilmayanIsaretler(not, gun = new Date().getDay()) {\n    const out = new Set(); const re = /(\\*+)\\s*([^*]+)/g; let m;\n    while ((m = re.exec(not || \"\"))) { const t = m[2].toLocaleUpperCase(\"tr\"); if (!/YAPILMAZ/.test(t)) continue; if ((gun === 6 && /C\\.?TES|CUMARTES/.test(t)) || (gun === 0 && /PAZAR/.test(t))) out.add(m[1]); }\n    return out;\n  }\n  function tabloGunUygun(not, gun = new Date().getDay()) {\n    const t = (not || \"\").toLocaleUpperCase(\"tr\"); const hi = /HAFTA ?İÇİ/.test(t), ct = /CUMARTES|C\\.?TES/.test(t), pz = /PAZAR/.test(t);\n    if (/YAPILMAZ/.test(t) || (!hi && !ct && !pz) || /HER GÜN/.test(t)) return true;\n    return (gun >= 1 && gun <= 5 && hi) || (gun === 6 && ct) || (gun === 0 && pz);\n  }\n  const satirYok = (r, yok) => r.some((c) => { const m = /\\d(\\*+)\\s*$/.exec(String(c).replace(/\\s+/g, \"\")); return m && yok.has(m[1]); });\n\n  // ---------- Ağ kurulumu ----------\n  // g: {hatlar, istasyonlar, profiller?, metrobus?, iskeleler?, vapur?, otobus?: {duraklar:{kod:[lat,lon,ad]}, hatlar:[{kod, ad, mb, yon:{D:[kod..],G:[..]}, aralik?}]}, marmaray?, gun?, saat?}\n  function kur(g) {\n    const duraklar = [], idx = new Map(), desenler = [], seferler = [];\n    const ekle = (key, o) => { if (idx.has(key)) return idx.get(key); const i = duraklar.length; duraklar.push({ ...o, key }); idx.set(key, i); return i; };\n    const gun = g.gun ?? new Date().getDay();\n    const saat = g.saat ?? (new Date().getHours() * 60 + new Date().getMinutes());\n\n    // Raylı sistem\n    const hatById = new Map((g.hatlar || []).map((h) => [h.id, h]));\n    const hatIst = new Map();\n    for (const s of g.istasyonlar || []) { if (!s.lat || !s.lon) continue; (hatIst.get(s.hatId) || hatIst.set(s.hatId, []).get(s.hatId)).push(s); }\n    for (const [hatId, liste] of hatIst) {\n      const h = hatById.get(hatId); if (!h) continue;\n      liste.sort((a, b) => a.sira - b.sira);\n      const tur = turOf(h.ad);\n      const di = liste.map((s) => ekle(\"m:\" + s.id, { ad: s.ad, lat: s.lat, lon: s.lon, tur, hat: h.ad, istId: s.id, hatId }));\n      const sure = (a, b) => Math.max(tur === \"tf\" ? 4 : 1.5, (Core.mesafe(a, b) / 1000 / TUR_HIZ[tur]) * 60 + (tur === \"metro\" ? 0.5 : 0.3));\n      const yap = (sira, yon, dIdx) => {\n        let t = [0]; for (let k = 1; k < sira.length; k++) t.push(t[k - 1] + sure(sira[k - 1], sira[k]));\n        const resmi = HAT_TOPLAM[h.ad]; if (resmi && t[t.length - 1] > 0) { const k = resmi / t[t.length - 1]; t = t.map((x) => x * k); }\n        desenler.push({ id: `${h.ad}:${yon}`, hat: h.ad, hatId, renk: h.renk, tur, d: dIdx, t, aralik: TUR_ARALIK[tur], ad: sira[sira.length - 1].ad, saatler: calismaSaatleri(h.ilk, h.son) });\n      };\n      yap(liste, \"i\", di);\n      if (hatId !== 12) yap(liste.slice().reverse(), \"g\", di.slice().reverse());\n    }\n\n    // Marmaray\n    if (g.marmaray !== false && (g.hatlar || g.otobus)) {\n      const di = MARMARAY.map(([ad, lat, lon]) => ekle(\"r:\" + ad, { ad, lat, lon, tur: \"marmaray\", hat: \"Marmaray\" }));\n      const t = MARMARAY.map((x) => x[3]);\n      const yap = (b, s, aralik, ek) => {\n        const d = di.slice(b, s + 1), tt = t.slice(b, s + 1).map((x) => x - t[b]), top = tt[tt.length - 1];\n        desenler.push({ id: \"MR:i\" + ek, hat: \"Marmaray\", renk: MARMARAY_RENK, tur: \"marmaray\", d, t: tt, aralik, ad: MARMARAY[s][0], saatler: [355, 1440] });\n        desenler.push({ id: \"MR:g\" + ek, hat: \"Marmaray\", renk: MARMARAY_RENK, tur: \"marmaray\", d: d.slice().reverse(), t: tt.slice().reverse().map((x) => top - x), aralik, ad: MARMARAY[b][0], saatler: [355, 1440] });\n      };\n      yap(0, MARMARAY.length - 1, 15, \"\");\n      yap(MARMARAY.findIndex((x) => x[0] === \"Pendik\"), MARMARAY.findIndex((x) => x[0] === \"Ataköy\"), 8, \"k\");\n    }\n\n    // İETT otobüs + metrobüs hatları\n    const ob = g.otobus;\n    if (ob && ob.hatlar && ob.hatlar.length) {\n      const hiz = otobusHiz(saat, gun);\n      const durakIdx = (kod) => { const d = ob.duraklar[kod]; if (!d) return -1; return ekle(\"b:\" + kod, { ad: bas(d[2]), lat: d[0], lon: d[1], tur: \"otobus\", kod }); };\n      for (const h of ob.hatlar) {\n        const mb = !!h.mb;\n        for (const [yon, kodlar] of Object.entries(h.yon || {})) {\n          const di = kodlar.map(durakIdx).filter((x) => x >= 0);\n          if (di.length < 2) continue;\n          const t = [0];\n          for (let k = 1; k < di.length; k++) {\n            const m = Core.mesafe(duraklar[di[k - 1]], duraklar[di[k]]) * 1.15;\n            const sehir = mb ? 32 : hiz.sehir, yol = mb ? 50 : hiz.yol;\n            const dk = (Math.min(m, 900) / 1000 / sehir + Math.max(0, m - 900) / 1000 / yol) * 60 + (mb ? 0.5 : 0.35);\n            t.push(t[k - 1] + dk);\n          }\n          if (mb) di.forEach((i) => { duraklar[i].tur = \"mb\"; });\n          desenler.push({ id: `${h.kod}:${yon}`, hat: h.kod, tur: mb ? \"mb\" : \"otobus\", renk: mb ? METROBUS_RENK : null, d: di, t, aralik: h.aralik || (mb ? 3 : otobusAralik(saat)), ad: duraklar[di[di.length - 1]].ad, iett: true, yon });\n        }\n      }\n    } else if (g.metrobus) {\n      for (const [yon, l] of Object.entries(g.metrobus)) {\n        if (!l || l.length < 2) continue;\n        const di = l.map((d) => ekle(\"b:\" + d.kod, { ad: bas(d.ad), lat: d.lat, lon: d.lon, tur: \"mb\", kod: d.kod }));\n        const t = [0]; for (let k = 1; k < l.length; k++) t.push(t[k - 1] + Math.max(1.5, (Core.mesafe(l[k - 1], l[k]) / 1000 / 30) * 60 + 0.5));\n        desenler.push({ id: \"MB:\" + yon, hat: \"Metrobüs\", renk: METROBUS_RENK, tur: \"mb\", d: di, t, aralik: 3, ad: bas(l[l.length - 1].ad) });\n      }\n    }\n\n    // Vapur\n    const iskeleBul = new Map();\n    for (const p of (g.iskeleler || []).concat(EK_ISKELE)) { const n = norm(p.ad); if (!iskeleBul.has(n)) iskeleBul.set(n, p); }\n    const iskele = (ad) => {\n      let n = norm(ad); n = ISKELE_TAKMA[n] || n; if (!n) return -1;\n      const p = iskeleBul.get(n) || [...iskeleBul.entries()].find(([k]) => k.startsWith(n) || n.startsWith(k))?.[1];\n      if (!p) return -1;\n      return ekle(\"v:\" + norm(p.ad), { ad: p.ad.replace(/^İDO\\s+/, \"\").replace(/\\s*(Terminali|iskelesi)$/i, \"\"), lat: p.lat, lon: p.lon, tur: \"vapur\", hat: \"Vapur\" });\n    };\n    let sId = 0;\n    for (const vh of g.vapur || []) {\n      const uclar = String(vh.ad || \"\").split(/\\s+-\\s+|-/).map((x) => x.replace(/HATTI$/i, \"\").trim()).filter(Boolean);\n      for (const tb of vh.tablolar || []) {\n        if (!tabloGunUygun(tb.not, gun)) continue;\n        const yok = bugunYapilmayanIsaretler(tb.not, gun);\n        const sutun = (tb.basliklar || []).find((r) => r.length > 1 && !r.every((c) => /Kalkış|Varış/i.test(c)));\n        let sutunIdx;\n        if (sutun) sutunIdx = sutun.map(iskele);\n        else { const b0 = (tb.baslik || \"\").split(\"|\")[0].trim(); const diger = uclar.find((u) => norm(u) !== norm(b0)) || \"\"; sutunIdx = [iskele(b0), iskele(diger)]; }\n        if (sutunIdx.filter((x) => x >= 0).length < 2) continue;\n        for (const r of tb.satirlar || []) {\n          if (satirYok(r, yok)) continue;\n          const d = [], t = [];\n          if (!sutun) { const k = Zaman.dk(r[0]); if (k == null) continue; const a = duraklar[sutunIdx[0]], b = duraklar[sutunIdx[1]]; d.push(sutunIdx[0], sutunIdx[1]); t.push(k, k + 2 + (Core.mesafe(a, b) / 1000 / TUR_HIZ.vapur) * 60); }\n          else r.forEach((c, i) => { const k = Zaman.dk(c); if (k != null && sutunIdx[i] >= 0) { if (t.length && k < t[t.length - 1]) return; d.push(sutunIdx[i]); t.push(k); } });\n          if (d.length >= 2) seferler.push({ id: ++sId, hat: bas(vh.ad), d, t, grup: vh.ad + \"|\" + tb.baslik });\n        }\n      }\n    }\n\n    // Dizinler\n    const N = duraklar.length;\n    const desenDurak = Array.from({ length: N }, () => []);\n    const ofset = new Int32Array(desenler.length + 1);\n    desenler.forEach((p, pi) => { ofset[pi + 1] = ofset[pi] + p.d.length; p.d.forEach((s, i) => desenDurak[s].push(pi, i)); });\n    const seferDurak = Array.from({ length: N }, () => []);\n    seferler.forEach((s, si) => s.d.forEach((d, i) => seferDurak[d].push([si, i])));\n    for (const l of seferDurak) l.sort((a, b) => seferler[a[0]].t[a[1]] - seferler[b[0]].t[b[1]]);\n    // Yakın duraklar (aktarma): ızgara\n    const G = 0.006, izg = new Map(), hk = (a, b) => a + \":\" + b;\n    duraklar.forEach((d, i) => { const k = hk(Math.floor(d.lat / G), Math.floor(d.lon / G)); (izg.get(k) || izg.set(k, []).get(k)).push(i); });\n    const yakin = new Array(N);\n    for (let i = 0; i < N; i++) {\n      const d = duraklar[i], a = Math.floor(d.lat / G), b = Math.floor(d.lon / G), out = [];\n      const rayliMi = d.tur !== \"otobus\";\n      for (let x = -1; x <= 1; x++) for (let y = -1; y <= 1; y++) for (const j of izg.get(hk(a + x, b + y)) || []) {\n        if (j === i) continue;\n        const sinir = rayliMi || duraklar[j].tur !== \"otobus\" ? AKTARMA_RAYLI_M : AKTARMA_OTOBUS_M;\n        const m = Core.mesafe(d, duraklar[j]); if (m <= sinir) out.push(j, m);\n      }\n      yakin[i] = out;\n    }\n    return { duraklar, desenler, seferler, desenDurak, seferDurak, yakin, ofset, izg, G, hk, otobusHatSayisi: ob?.hatlar?.length || 0 };\n  }\n\n  // Bir noktaya yakın duraklar (ızgara ile hızlı)\n  function yakinDuraklar(ag, p, maxM, adet) {\n    const out = [], r = Math.ceil(maxM / 500) + 1, a = Math.floor(p.lat / ag.G), b = Math.floor(p.lon / ag.G);\n    for (let x = -r; x <= r; x++) for (let y = -r; y <= r; y++) for (const i of ag.izg.get(ag.hk(a + x, b + y)) || []) { const m = Core.mesafe(p, ag.duraklar[i]); if (m <= maxM) out.push([i, m]); }\n    out.sort((x, y) => x[1] - y[1]);\n    // Raylı/vapur duraklarını sınırın dışında bırakma: önce en yakınlar, sonra kalan raylılar\n    const sec = out.slice(0, adet);\n    for (const e of out.slice(adet)) if (ag.duraklar[e[0]].tur !== \"otobus\" && sec.length < adet + 10) sec.push(e);\n    return sec;\n  }\n\n  // Seçilen yer bir durak/istasyonsa: o noktadaki (aynı adlı, 150 m içindeki) tüm durakları \"tam hedef\" say\n  function durakKumesi(ag, p) {\n    if (!p || !p.durak) return null;\n    // Yönü belli tek bir otobüs durağı seçildiyse (kod), yalnızca o durak — karşı kaldırımdaki eşi değil\n    if (p.kod) { const i = ag.duraklar.findIndex((d) => d.kod === p.kod); if (i >= 0) return [[i, 0]]; }\n    const n = norm(p.ad);\n    const l = yakinDuraklar(ag, p, 250, 20).filter(([i, m]) => m <= 60 || (norm(ag.duraklar[i].ad) === n || n.includes(norm(ag.duraklar[i].ad)) || norm(ag.duraklar[i].ad).includes(n)) && m <= 250);\n    return l.length ? l : null;\n  }\n\n  // Aktarmasız (tek araç) seçenekler: başlangıca yakın duraktan binip hedef durağa/yakınına giden her hat\n  function direkler(ag, nereden, nereye, t0, opt = {}) {\n    const bas = durakKumesi(ag, nereden) || yakinDuraklar(ag, nereden, 900, 60);\n    const hedefKume = durakKumesi(ag, nereye);\n    const son = hedefKume || yakinDuraklar(ag, nereye, 900, 60);\n    const sonMap = new Map(son.map(([i, m]) => [i, hedefKume ? 0 : m]));\n    const enIyi = new Map(); // hat+yon -> sonuç\n    for (const [s, m0] of bas) {\n      const w0 = nereden.durak && m0 <= 250 ? 0 : yurume(m0);\n      const dd = ag.desenDurak[s];\n      for (let q = 0; q < dd.length; q += 2) {\n        const pi = dd[q], i = dd[q + 1], p = ag.desenler[pi];\n        if (opt.yasakHat?.has(p.hat)) continue;\n        const tb = t0 + w0;\n        const bek = bekleHesap(p, i, tb, opt);\n        if (bek == null || !isFinite(bek)) continue;\n        for (let j = i + 1; j < p.d.length; j++) {\n          if (!sonMap.has(p.d[j])) continue;\n          const m1 = sonMap.get(p.d[j]), w1 = yurume(m1);\n          const varis = tb + bek + p.t[j] - p.t[i] + w1;\n          const maliyet = varis - t0 + yurumeMaliyet(w0) - w0 + yurumeMaliyet(w1) - w1;\n          const k = p.hat + \"|\" + (p.yon || p.id);\n          const e = enIyi.get(k);\n          if (!e || maliyet < e.maliyet) enIyi.set(k, { maliyet, bacaklar: [\n            { tur: \"yuru\", m: m0, kalkis: t0, varis: tb, from: nereden, to: ag.duraklar[s] },\n            { tur: p.tur, desen: pi, hat: p.hat, renk: p.renk, yonAd: p.ad, i, j, bekleme: bek, kalkis: tb + bek, varis: tb + bek + p.t[j] - p.t[i], from: ag.duraklar[s], to: ag.duraklar[p.d[j]], iett: !!p.iett, yon: p.yon },\n            { tur: \"yuru\", m: m1, kalkis: varis - w1, varis, from: ag.duraklar[p.d[j]], to: nereye },\n          ] });\n          break; // bu binişten en yakın hedef durağı yeter\n        }\n      }\n    }\n    return [...enIyi.values()].sort((x, y) => x.maliyet - y.maliyet).slice(0, 6).map((e) => {\n      const r = duzenle({ bacaklar: e.bacaklar.filter((b) => b.tur !== \"yuru\" || b.m > 1) }, t0, ag);\n      r.direkt = true; return r;\n    });\n  }\n\n  // ---------- Öncelik kuyruğu ----------\n  class Kuyruk {\n    constructor() { this.a = []; }\n    get bos() { return !this.a.length; }\n    ekle(x) { const a = this.a; a.push(x); let i = a.length - 1; while (i > 0) { const p = (i - 1) >> 1; if (a[p].c <= a[i].c) break; [a[p], a[i]] = [a[i], a[p]]; i = p; } }\n    al() { const a = this.a, top = a[0], son = a.pop(); if (a.length) { a[0] = son; let i = 0; for (;;) { const l = 2 * i + 1, r = l + 1; let m = i; if (l < a.length && a[l].c < a[m].c) m = l; if (r < a.length && a[r].c < a[m].c) m = r; if (m === i) break; [a[m], a[i]] = [a[i], a[m]]; i = m; } } return top; }\n  }\n\n  // ---------- Arama ----------\n  function ara(ag, nereden, nereye, t0, opt = {}) {\n    const N = ag.duraklar.length, M = N + ag.ofset[ag.desenler.length];\n    const en = new Float64Array(M).fill(Infinity), zaman = new Float64Array(M);\n    const onceki = new Int32Array(N).fill(-2), bacak = new Array(N);\n    const binisBilgi = new Array(M - N); // araçta düğümü: {s0, i0, kalk, bekle}\n    const yasak = opt.yasakHat || new Set();\n    const Q = new Kuyruk();\n    const durakIt = (s, t, c, b, pr) => { if (c < en[s] - 1e-9) { en[s] = c; zaman[s] = t; bacak[s] = b; onceki[s] = pr; Q.ekle({ s, c }); } };\n    const aracIt = (k, t, c, bilgi) => { const u = N + k; if (c < en[u] - 1e-9) { en[u] = c; zaman[u] = t; binisBilgi[k] = bilgi; Q.ekle({ s: u, c }); } };\n\n    const basKume = durakKumesi(ag, nereden);\n    let erisim = basKume || yakinDuraklar(ag, nereden, ERISIM_M, ERISIM_MAX_DURAK);\n    if (!erisim.length) erisim = yakinDuraklar(ag, nereden, ERISIM_GENIS_M, ERISIM_MAX_DURAK);\n    for (const [s, m] of erisim) { const w = yurume(m); durakIt(s, t0 + w, yurumeMaliyet(w), { tur: \"yuru\", m, kalkis: t0, varis: t0 + w, from: nereden, to: ag.duraklar[s] }, -1); }\n    for (const tk of opt.tohumlar || []) durakIt(tk.durak, tk.t, tk.t - t0 + BINIS_CEZASI, { tur: \"dis\", bacaklar: tk.bacaklar, kalkis: t0, varis: tk.t }, -1);\n\n    const bitti = new Uint8Array(M);\n    while (!Q.bos) {\n      const { s: u, c } = Q.al();\n      if (bitti[u] || c > en[u] + 1e-9) continue;\n      bitti[u] = 1;\n      const t = zaman[u];\n      if (u >= N) {\n        // Araçtayız: bir sonraki durağa devam et ya da in\n        const k = u - N; let pi = 0, lo = 0, hi = ag.desenler.length;\n        while (lo < hi) { const m = (lo + hi) >> 1; if (ag.ofset[m + 1] <= k) lo = m + 1; else hi = m; }\n        pi = lo; const p = ag.desenler[pi], i = k - ag.ofset[pi], bi = binisBilgi[k];\n        if (i + 1 < p.d.length) aracIt(k + 1, t + p.t[i + 1] - p.t[i], c + p.t[i + 1] - p.t[i], bi);\n        if (i > bi.i0) {\n          const s = p.d[i];\n          durakIt(s, t, c, { tur: p.tur, desen: pi, hat: p.hat, renk: p.renk, yonAd: p.ad, i: bi.i0, j: i, bekleme: bi.bekle, kalkis: bi.kalk, varis: t, from: ag.duraklar[bi.s0], to: ag.duraklar[s], iett: !!p.iett, yon: p.yon }, bi.s0);\n        }\n        continue;\n      }\n      const s = u, gelen = bacak[s];\n      // Yürüyerek aktarma (yürüyüşten sonra tekrar yürüme yok)\n      if (gelen.tur !== \"yuru\") {\n        const y = ag.yakin[s];\n        for (let q = 0; q < y.length; q += 2) {\n          const j = y[q], m = y[q + 1], w = yurume(m) + 1;\n          durakIt(j, t + w, c + yurumeMaliyet(w), { tur: \"yuru\", m, kalkis: t, varis: t + w, from: ag.duraklar[s], to: ag.duraklar[j] }, s);\n        }\n      }\n      // Binişler\n      const dd = ag.desenDurak[s];\n      for (let q = 0; q < dd.length; q += 2) {\n        const pi = dd[q], i = dd[q + 1], p = ag.desenler[pi];\n        if (i === p.d.length - 1 || yasak.has(p.hat)) continue;\n        if (gelen.desen === pi || (gelen.hat === p.hat && gelen.tur !== \"yuru\")) continue;\n        const bekle = bekleHesap(p, i, t, opt);\n        if (bekle == null || !isFinite(bekle)) continue;\n        aracIt(ag.ofset[pi] + i, t + bekle, c + bekle + BINIS_CEZASI, { s0: s, i0: i, kalk: t + bekle, bekle });\n      }\n      // Vapur seferleri\n      const gor = new Set();\n      for (const [si, i] of ag.seferDurak[s]) {\n        const sf = ag.seferler[si];\n        if (sf.t[i] < t + 1 || i === sf.d.length - 1 || gor.has(sf.grup) || yasak.has(\"Vapur\")) continue;\n        gor.add(sf.grup);\n        for (let j = i + 1; j < sf.d.length; j++) {\n          const v = sf.t[j];\n          durakIt(sf.d[j], v, c + (v - t) + BINIS_CEZASI, { tur: \"vapur\", sefer: si, hat: sf.hat, renk: \"#0e7490\", i, j, bekleme: sf.t[i] - t, kalkis: sf.t[i], varis: v, from: ag.duraklar[s], to: ag.duraklar[sf.d[j]] }, s);\n        }\n      }\n    }\n\n    const zincir = (s) => { const l = []; while (s >= 0) { l.unshift(bacak[s]); s = onceki[s]; } return l; };\n    let enIyi = null;\n    const dm = Core.mesafe(nereden, nereye);\n    if (dm <= 3500) { const w = yurume(dm); enIyi = { c: yurumeMaliyet(w), bacaklar: [{ tur: \"yuru\", m: dm, kalkis: t0, varis: t0 + w, from: nereden, to: nereye }] }; }\n    // Hedef bir duraksa yalnızca o durakta inmeyi kabul et (ulaşılamıyorsa yakındakilere bak)\n    const hedefKume = durakKumesi(ag, nereye);\n    let cikis = (hedefKume || []).filter(([i]) => en[i] < Infinity).map(([i]) => [i, 0]);\n    if (!cikis.length) cikis = yakinDuraklar(ag, nereye, ERISIM_M, ERISIM_MAX_DURAK).filter(([i]) => en[i] < Infinity);\n    if (!cikis.length) cikis = yakinDuraklar(ag, nereye, ERISIM_GENIS_M, ERISIM_MAX_DURAK).filter(([i]) => en[i] < Infinity);\n    for (const [s, m] of cikis) {\n      if (bacak[s].tur === \"yuru\" && onceki[s] === -1) continue;\n      const w = yurume(m), c = en[s] + yurumeMaliyet(w);\n      if (!enIyi || c < enIyi.c) enIyi = { c, bacaklar: zincir(s).concat([{ tur: \"yuru\", m, kalkis: zaman[s], varis: zaman[s] + w, from: ag.duraklar[s], to: nereye }]) };\n    }\n    return { enIyi: enIyi && duzenle(enIyi, t0, ag), etiketler: { en, zaman, zincir } };\n  }\n\n  function duzenle(r, t0, ag) {\n    const l = [];\n    for (const b of r.bacaklar) {\n      if (b.tur === \"dis\") { l.push(...b.bacaklar); continue; }\n      const son = l[l.length - 1];\n      if (b.tur === \"yuru\" && son && son.tur === \"yuru\") { son.m += b.m; son.varis = b.varis; son.to = b.to; continue; }\n      l.push({ ...b });\n    }\n    for (const b of l) {\n      if (b.desen != null && ag && b.tur !== \"vapur\") { const p = ag.desenler[b.desen]; b.yol = p.d.slice(b.i, b.j + 1).map((k) => [ag.duraklar[k].lat, ag.duraklar[k].lon]); b.durakSayisi = b.j - b.i; b.durakKodlari = p.iett ? p.d.slice(b.i, b.j + 1).map((k) => ag.duraklar[k].kod) : null; }\n      else if (b.sefer != null && ag) { const s = ag.seferler[b.sefer]; b.yol = s.d.slice(b.i, b.j + 1).map((k) => [ag.duraklar[k].lat, ag.duraklar[k].lon]); b.durakSayisi = b.j - b.i; }\n      else if (!b.yol && b.from && b.to) b.yol = [[b.from.lat, b.from.lon], [b.to.lat, b.to.lon]];\n    }\n    // İlk yürüyüşü en kısaya indir: binişe \"tam zamanında\" çık\n    const varis = l.length ? l[l.length - 1].varis : t0;\n    return { bacaklar: l, kalkis: t0, varis, sure: varis - t0, yurumeM: l.filter((b) => b.tur === \"yuru\").reduce((a, b) => a + b.m, 0), aktarma: Math.max(0, l.filter((b) => b.tur !== \"yuru\").length - 1), imza: l.filter((b) => b.tur !== \"yuru\").map((b) => b.hat).join(\">\") || \"yuru\" };\n  }\n\n  // Alternatifler: en iyi rotanın hatlarını sırayla yasakla\n  // Alternatifler: tek tek hat yasaklamanın yanında, aynı aşamada (ilk biniş / son biniş) şimdiye kadar\n  // görülen TÜM hatları birlikte yasaklar. Böylece \"20K+M5\", \"20Ü+M5\" bulunduktan sonra \"14BK+M5\" de çıkar.\n  function alternatifler(ag, nereden, nereye, t0, opt = {}, adet = 4) {\n    const sonuc = [], ilk = ara(ag, nereden, nereye, t0, opt);\n    if (!ilk.enIyi) return { sonuc, etiketler: ilk.etiketler };\n    sonuc.push(ilk.enIyi);\n    const taban = [...(opt.yasakHat || [])], denenen = new Set(), kuyruk = [];\n    const ekle = (hatlar) => { const k = [...new Set(hatlar)].sort().join(\"|\"); if (!k || denenen.has(k)) return; denenen.add(k); kuyruk.push([...new Set(hatlar)]); };\n    const binisler = (r) => r.bacaklar.filter((x) => x.tur !== \"yuru\").map((x) => x.hat);\n    const asamaYasaklari = () => {\n      const ilkH = [], sonH = [];\n      for (const r of sonuc) { const h = binisler(r); if (h.length) { ilkH.push(h[0]); sonH.push(h[h.length - 1]); } }\n      ekle(ilkH); ekle(sonH);\n    };\n    const yeniRota = (r) => { for (const h of binisler(r)) ekle([h]); asamaYasaklari(); };\n    yeniRota(ilk.enIyi);\n    let arama = 0;\n    while (kuyruk.length && sonuc.length < adet && arama < 18) {\n      const yasak = kuyruk.shift(); arama++;\n      const a = ara(ag, nereden, nereye, t0, { ...opt, yasakHat: new Set([...taban, ...yasak]) }).enIyi;\n      if (a && !sonuc.some((x) => x.imza === a.imza) && a.sure <= sonuc[0].sure * 1.6 + 10) { sonuc.push(a); yeniRota(a); }\n    }\n    return { sonuc, etiketler: ilk.etiketler };\n  }\n\n  // Bir duraktan geçen hatlar ve gittikleri yön (son durak adları)\n  function durakYonu(ag, i) {\n    const dd = ag.desenDurak[i], hed = new Map(), hat = [];\n    for (let q = 0; q < dd.length; q += 2) {\n      const p = ag.desenler[dd[q]]; if (dd[q + 1] === p.d.length - 1) continue;\n      hed.set(p.ad, (hed.get(p.ad) || 0) + 1);\n      if (!hat.includes(p.hat)) hat.push(p.hat);\n    }\n    return { yon: [...hed.entries()].sort((a, b) => b[1] - a[1]).map((x) => x[0]).slice(0, 2), hat };\n  }\n  function yerAra(ag, metin, adet = 8) {\n    const q = norm(metin); if (q.length < 2) return [];\n    const gor = new Set(), out = [];\n    ag.duraklar.forEach((d, i) => {\n      const n = norm(d.ad); if (!n.includes(q)) return;\n      const otobus = d.tur === \"otobus\" || (d.tur === \"mb\" && d.kod);\n      const y = otobus ? durakYonu(ag, i) : null;\n      // Otobüs duraklarında gidiş ve geliş ayrı gösterilir (yön imzası anahtara dahil)\n      const k = n + \"|\" + d.tur + \"|\" + (y ? y.yon.join(\",\") : \"\");\n      if (gor.has(k)) return; gor.add(k);\n      const alt = otobus\n        ? `${d.tur === \"mb\" ? \"Metrobüs\" : \"Durak\"}${y.yon.length ? \" · → \" + y.yon.join(\" / \") : \"\"}${y.hat.length ? \" · \" + y.hat.slice(0, 5).join(\", \") + (y.hat.length > 5 ? \"…\" : \"\") : \"\"}`\n        : TUR_ADI[d.tur] + (d.hat && ![\"vapur\", \"mb\", \"otobus\"].includes(d.tur) ? \" \" + d.hat : \"\");\n      out.push({ ad: d.ad, alt, lat: d.lat, lon: d.lon, tur: otobus ? \"durak\" : d.tur, kod: otobus ? d.kod : undefined, durak: true, skor: (n.startsWith(q) ? 0 : 1) + (otobus ? 0.3 : 0) + (y && !y.hat.length ? 2 : 0) });\n    });\n    return out.sort((a, b) => a.skor - b.skor).slice(0, adet);\n  }\n\n  return { kur, ara, alternatifler, direkler, bekleHesap, durakYonu, durakKumesi, duzenle, yerAra, yakinDuraklar, yurume, yurumeMaliyet, turOf, norm, otobusHiz, otobusAralik, TUR_ADI, tabloGunUygun, bugunYapilmayanIsaretler, satirYok };\n})();\n\n</script>\n<script>\n(() => {\n\"use strict\";\nconst CANLI_SN = 5;              // İETT konum kontrol sıklığı\nconst RENKLER = [\"#e4572e\", \"#0f62fe\", \"#0a8f4f\", \"#8e44ad\", \"#d97706\", \"#0891b2\", \"#be185d\", \"#4d7c0f\"];\nconst GUN_ADI = { I: \"Hafta içi\", C: \"Cumartesi\", P: \"Pazar\" };\nconst TRAFIK_RENK = { 0: \"#9ca3af\", 1: \"#16a34a\", 2: \"#84cc16\", 3: \"#f59e0b\", 4: \"#dc2626\", 5: \"#7f1d1d\" };\nconst TRAFIK_AD = { 1: \"Akıcı\", 2: \"Az yoğun\", 3: \"Orta\", 4: \"Yoğun\", 5: \"Çok yoğun\" };\n\n// ---------- yardımcılar ----------\nconst $ = (s) => document.querySelector(s);\nconst esc = (s) => String(s ?? \"\").replace(/[&<>\"']/g, (c) => ({ \"&\": \"&amp;\", \"<\": \"&lt;\", \">\": \"&gt;\", '\"': \"&quot;\", \"'\": \"&#39;\" }[c]));\nconst bas = (s) => String(s || \"\").toLocaleLowerCase(\"tr\").replace(/(^|[\\s/(.\\-])(\\S)/g, (m, a, b) => a + b.toLocaleUpperCase(\"tr\")).trim();\nconst metre = (m) => m == null ? \"\" : m < 1000 ? Math.round(m / 10) * 10 + \" m\" : (m / 1000).toFixed(1) + \" km\";\nconst saat = (dk) => { dk = Math.round(dk); dk = ((dk % 1440) + 1440) % 1440; return String(Math.floor(dk / 60)).padStart(2, \"0\") + \":\" + String(dk % 60).padStart(2, \"0\"); };\nconst sureEtiket = (k) => `<span class=\"sure ${k != null && k <= 3 ? \"yakin\" : \"\"}\">${k == null ? \"–\" : k <= 1 ? \"geliyor\" : \"~\" + Zaman.kalanYazi(Math.round(k))}</span>`;\nconst renkKod = (kod) => { let h = 0; for (const c of String(kod)) h = (h * 31 + c.charCodeAt(0)) >>> 0; return RENKLER[h % RENKLER.length]; };\nconst metrobusMu = (h) => h && /METROBÜS/i.test(h.tarife || \"\");\nconst hataMesaji = (e) => {\n  const m = String(e && e.message || e);\n  if (/Sunucu hatası|network|Load failed|timed out|Could not connect|offline|Failed to fetch/i.test(m)) return \"Bağlantı kurulamadı. İnternetinizi kontrol edin.\";\n  return m;\n};\n// \"2026-11-23T15:49:00Z\" -> günün dakikası (Zaman.simdi ile aynı ölçek)\n// ISO zamanı -> planlama ölçeğinde dakika (seçilen zamana göre; yoksa şimdiye göre)\nconst isoDk = (iso) => { const d = new Date(iso); const z = typeof PLAN_ZAMAN !== \"undefined\" && PLAN_ZAMAN.tabanMs ? PLAN_ZAMAN : { tabanMs: Date.now(), tabanDk: Zaman.simdi() + new Date().getSeconds() / 60 }; return z.tabanDk + (d - z.tabanMs) / 60000; };\n// \"2026-11-23 18:32:51\" (İstanbul saati) -> ms\nconst iettZaman = (s) => { const m = /(\\d{4})-(\\d\\d)-(\\d\\d) (\\d\\d):(\\d\\d):(\\d\\d)/.exec(s || \"\"); return m ? new Date(+m[1], m[2] - 1, +m[3], +m[4], +m[5], +m[6]).getTime() : null; };\n\n// ---------- araç simgeleri ----------\nconst GLIF = {\n  otobus: '<svg viewBox=\"0 0 24 24\" fill=\"#fff\"><path d=\"M5 3h14a2 2 0 0 1 2 2v11a2 2 0 0 1-1 1.7V20a1 1 0 0 1-1 1h-1a1 1 0 0 1-1-1v-1H7v1a1 1 0 0 1-1 1H5a1 1 0 0 1-1-1v-2.3A2 2 0 0 1 3 16V5a2 2 0 0 1 2-2zm0 3v5h14V6H5zm1.5 7.5a1.5 1.5 0 1 0 0 3 1.5 1.5 0 0 0 0-3zm11 0a1.5 1.5 0 1 0 0 3 1.5 1.5 0 0 0 0-3z\"/></svg>',\n  mb: '<svg viewBox=\"0 0 24 24\" fill=\"#fff\"><path d=\"M2 6a2 2 0 0 1 2-2h7v13H3.5A1.5 1.5 0 0 1 2 15.5V6zm11-2h7a2 2 0 0 1 2 2v9.5a1.5 1.5 0 0 1-1.5 1.5H13V4zM3.5 7v4h6V7h-6zm11 0v4h6V7h-6zM5 18a1.5 1.5 0 1 1 0 3 1.5 1.5 0 0 1 0-3zm14 0a1.5 1.5 0 1 1 0 3 1.5 1.5 0 0 1 0-3z\"/></svg>',\n  metro: '<svg viewBox=\"0 0 24 24\" fill=\"#fff\"><path d=\"M12 2c4.4 0 7 .9 7 4v9.5a3.5 3.5 0 0 1-2.4 3.3L18 21h-2.2l-1.3-2h-5l-1.3 2H6l1.4-2.2A3.5 3.5 0 0 1 5 15.5V6c0-3.1 2.6-4 7-4zM7 7v4h10V7H7zm1.5 6.5a1.5 1.5 0 1 0 0 3 1.5 1.5 0 0 0 0-3zm7 0a1.5 1.5 0 1 0 0 3 1.5 1.5 0 0 0 0-3z\"/></svg>',\n  tram: '<svg viewBox=\"0 0 24 24\" fill=\"#fff\"><path d=\"M9 1h6v1.5h-2.2L14 5h1c2.8 0 4 1 4 3.5v8a3 3 0 0 1-2.2 2.9L18 21h-2l-1.2-1.5H9.2L8 21H6l1.2-1.6A3 3 0 0 1 5 16.5v-8C5 6 6.2 5 9 5h1l1.2-2.5H9V1zM7 8.5V12h10V8.5H7zM8.5 14a1.3 1.3 0 1 0 0 2.6 1.3 1.3 0 0 0 0-2.6zm7 0a1.3 1.3 0 1 0 0 2.6 1.3 1.3 0 0 0 0-2.6z\"/></svg>',\n  fun: '<svg viewBox=\"0 0 24 24\" fill=\"#fff\"><path d=\"M2 4.5l20-3v1.6L13 4.4V7h2.5A3.5 3.5 0 0 1 19 10.5v6A3.5 3.5 0 0 1 15.5 20h-7A3.5 3.5 0 0 1 5 16.5v-6A3.5 3.5 0 0 1 8.5 7H11V4.7l-9 1.4V4.5zM7 10.5V13h4V9.5H8a1 1 0 0 0-1 1zm6-1V13h4v-2.5a1 1 0 0 0-1-1h-3z\"/></svg>',\n  vapur: '<svg viewBox=\"0 0 24 24\" fill=\"#fff\"><path d=\"M9 2h6v3h3a1 1 0 0 1 1 1v4.3l2 .7-2.6 7.5A5.4 5.4 0 0 1 15 17.6a5.4 5.4 0 0 1-6 0 5.4 5.4 0 0 1-3.4 1L3 11l2-.7V6a1 1 0 0 1 1-1h3V2zm-1 5v2.7l4-1.4 4 1.4V7H8zM2 20.5c1.6 0 2.6-.6 3.5-1.2.8.6 1.9 1.2 3.5 1.2s2.6-.6 3-1c.5.4 1.5 1 3 1s2.7-.6 3.5-1.2c.9.6 1.9 1.2 3.5 1.2V22c-1.6 0-2.7-.4-3.5-.9-.8.5-1.9.9-3.5.9s-2.5-.4-3-.7c-.5.3-1.4.7-3 .7s-2.7-.4-3.5-.9c-.8.5-1.9.9-3.5.9v-1.5z\"/></svg>',\n};\nGLIF.tf = GLIF.fun; GLIF.marmaray = GLIF.metro;\nfunction aracIkon(tur, renk, aci, etiket, tahmini) {\n  const ok = aci == null ? \"\" : `<svg class=\"halka\" viewBox=\"0 0 38 38\" style=\"transform:rotate(${Math.round(aci)}deg)\"><path d=\"M19 0 L24.5 7 H13.5 Z\" fill=\"${renk}\" stroke=\"#fff\" stroke-width=\"1.5\" stroke-linejoin=\"round\"/></svg>`;\n  return L.divIcon({ className: \"arac\" + (tahmini ? \" tahmini\" : \"\"), iconSize: [38, 38], iconAnchor: [19, 19],\n    html: ok + `<div class=\"govde\" style=\"background:${renk}\">${GLIF[tur] || GLIF.otobus}</div>` + (etiket ? `<span class=\"yazi\">${esc(etiket)}</span>` : \"\") });\n}\n\n// ---------- durum ----------\nconst S = {\n  sekme: \"yakin\", yigin: [], ben: null,\n  favoriler: [\"18K\", \"14BK\"], durak: {},\n  hatVeri: {},        // hat -> {bilgi, duraklar, otobusler, seferler, hiz, renk, zaman}\n  arac: new Map(),    // \"hat/kapino\" -> {hat, yon, gor:{lat,lon}, gercek:{lat,lon,ms}, hiz, isaret, sonGuncelleme}\n  aktifHatlar: new Set(),\n  trafik: false,\n  rota: { nereden: null, nereye: null, aktif: \"nereye\", metin: \"\", oneriler: [], sonuclar: null, durum: \"\", son: [] },\n  ag: null, agVapur: false,\n};\nasync function ayarYukle() {\n  const f = await KV.get(\"favoriler\"); if (Array.isArray(f)) S.favoriler = f;\n  const d = await KV.get(\"durak\"); if (d && typeof d === \"object\") S.durak = d;\n  const s = await KV.get(\"sonYerler\"); if (Array.isArray(s)) S.rota.son = s;\n}\nconst favKaydet = () => KV.set(\"favoriler\", S.favoriler);\nconst durakKaydet = () => KV.set(\"durak\", S.durak);\n\n// ---------- harita ----------\nconst map = L.map(\"harita\", { zoomControl: false }).setView([41.03, 29.0], 11);\n// Sade altlık: açık/koyu gri zemin + yalnızca yer adları\nconst koyu = window.matchMedia && matchMedia(\"(prefers-color-scheme: dark)\").matches;\nconst ESRI = \"https://server.arcgisonline.com/ArcGIS/rest/services/Canvas/\";\nL.tileLayer(ESRI + (koyu ? \"World_Dark_Gray_Base\" : \"World_Light_Gray_Base\") + \"/MapServer/tile/{z}/{y}/{x}\", { maxZoom: 16, maxNativeZoom: 16, attribution: \"© Esri · İETT · Metro İstanbul · İBB\" }).addTo(map);\nL.tileLayer(ESRI + (koyu ? \"World_Dark_Gray_Reference\" : \"World_Light_Gray_Reference\") + \"/MapServer/tile/{z}/{y}/{x}\", { maxZoom: 16, maxNativeZoom: 16, pane: \"shadowPane\", opacity: .9 }).addTo(map);\nmap.setMaxZoom(17);\nconst trafikCizici = L.canvas({ padding: 0.3 });\nconst trafikKatmani = L.layerGroup().addTo(map);\nconst katman = L.layerGroup().addTo(map);          // sayfaya özel çizimler\nconst aracKatmani = L.layerGroup().addTo(map);     // canlı + tahmini araçlar\nconst durakKatmani = L.layerGroup();                // durak noktaları: sadece yakınlaşınca\nconst hedefKatmani = L.layerGroup().addTo(map);     // \"durağım / en yakın durak\" — her zaman görünür\nconst hedefGor = new Set();\nconst hedefAdlar = [];\nfunction durakIsaretle(hat, d, renk) {\n  if (hedefGor.has(d.kod)) return; hedefGor.add(d.kod);\n  const m = L.circleMarker([d.lat, d.lon], { radius: 8, color: \"#fff\", weight: 3, fillColor: renk, fillOpacity: 1 }).bindPopup(() => durakPopup(hat, d)).addTo(hedefKatmani);\n  // Aynı adlı karşı kaldırım durağı için ikinci etiket koyma\n  if (!hedefAdlar.some((x) => x.ad === d.ad && Core.mesafe(x, d) < 250)) {\n    hedefAdlar.push(d);\n    m.bindTooltip(\"🚏 \" + esc(bas(d.ad)), { permanent: true, direction: \"top\", offset: [0, -8], className: \"durak-etiket\" });\n  }\n}\nfunction zoomAyarla() {\n  const z = map.getZoom();\n  if (z >= 13) { if (!map.hasLayer(durakKatmani)) durakKatmani.addTo(map); } else if (map.hasLayer(durakKatmani)) map.removeLayer(durakKatmani);\n  map.getContainer().classList.toggle(\"uzak\", z < 13);\n}\nmap.on(\"zoomend\", zoomAyarla);\nlet benIsaret = null, benDaire = null;\nconst tahminiIsaret = new Map();                   // tahmini tren/vapur işaretleri\n\nfunction haritaTemizle() {\n  katman.clearLayers(); durakKatmani.clearLayers(); hedefKatmani.clearLayers(); hedefGor.clear(); hedefAdlar.length = 0;\n  for (const a of S.arac.values()) a.isaret = null;\n  aracKatmani.clearLayers(); tahminiIsaret.clear();\n}\nfunction sigdir(noktalar, zoom) { const b = L.latLngBounds(noktalar.filter(Boolean)); if (b.isValid()) map.fitBounds(b, { padding: [28, 28], maxZoom: zoom || 16 }); }\nfunction benCiz() {\n  if (!S.ben) return;\n  const ll = [S.ben.lat, S.ben.lon];\n  if (!benIsaret) {\n    benIsaret = L.marker(ll, { icon: L.divIcon({ className: \"\", html: '<div class=\"ben-ikon\"></div>', iconSize: [16, 16], iconAnchor: [8, 8] }), zIndexOffset: 2000, interactive: false }).addTo(map);\n    benDaire = L.circle(ll, { radius: S.ben.acc || 30, color: \"#0f62fe\", weight: 1, fillOpacity: .08, interactive: false }).addTo(map);\n  } else { benIsaret.setLatLng(ll); benDaire.setLatLng(ll).setRadius(S.ben.acc || 30); }\n}\nfunction ucIsaret(ll, renk) { return L.marker(ll, { icon: L.divIcon({ className: \"\", html: `<div class=\"uc-ikon\" style=\"background:${renk}\"></div>`, iconSize: [22, 22], iconAnchor: [11, 22] }), zIndexOffset: 1500 }); }\n\n// ---------- İETT canlı araçlar: veri, gözlenen hız, akıcı hareket ----------\nasync function hatHazirla(hat) {\n  let v = S.hatVeri[hat];\n  if (!v) v = S.hatVeri[hat] = { renk: renkKod(hat) };\n  if (!v.duraklar) {\n    const [bilgi, duraklar] = await Promise.all([API.iett.hat(hat).catch(() => null), API.iett.duraklar(hat)]);\n    if (!bilgi && !Object.keys(duraklar).length) throw new Error(`${hat} hattı bulunamadı`);\n    v.bilgi = bilgi; v.duraklar = duraklar;\n    v.mb = metrobusMu(bilgi);\n    if (v.mb) v.renk = \"#c2410c\";\n    v.hiz = Core.ortalamaHiz({ uzunlukKm: bilgi?.km, seferSuresiDk: bilgi?.dk });\n    if (v.mb) v.hiz = Math.max(v.hiz, 25);\n  }\n  return v;\n}\n// Yeni İETT verisini işle: gözlenen hızı güncelle; değişiklik varsa true\nfunction konumIsle(hat, liste) {\n  const v = S.hatVeri[hat]; let degisti = false;\n  const gor = new Set();\n  for (const b of liste) {\n    const k = hat + \"/\" + b.kapino; gor.add(k);\n    const ms = iettZaman(b.zaman) || Date.now();\n    let a = S.arac.get(k);\n    if (!a) { a = { hat, kapino: b.kapino, gor: { lat: b.lat, lon: b.lon }, gercek: { lat: b.lat, lon: b.lon, ms }, hiz: null }; S.arac.set(k, a); degisti = true; }\n    else if (ms > a.gercek.ms) {\n      const dt = (ms - a.gercek.ms) / 3600e3, km = Core.mesafe(a.gercek, b) / 1000 * 1.15;\n      if (dt > 0 && dt < 0.2) { const o = Math.min(70, km / dt); a.hiz = a.hiz == null ? o : a.hiz * 0.5 + o * 0.5; }\n      a.gercek = { lat: b.lat, lon: b.lon, ms }; a.gor = { lat: b.lat, lon: b.lon }; degisti = true;\n    }\n    a.b = b; a.yon = b.yon;\n  }\n  for (const [k, a] of S.arac) if (a.hat === hat && !gor.has(k)) { if (a.isaret) aracKatmani.removeLayer(a.isaret); S.arac.delete(k); degisti = true; }\n  v.otobusler = liste; v.zaman = Date.now();\n  return degisti;\n}\n// Otobüsün tahmini hızı: gözlenen (trafiği yansıtır) ile hat ortalamasının karışımı\nfunction aracHizi(hat, kapino) {\n  const v = S.hatVeri[hat], a = S.arac.get(hat + \"/\" + kapino);\n  const ort = v?.hiz || 15;\n  if (!a || a.hiz == null) return ort;\n  return Math.max(5, Math.min(45, a.hiz * 0.6 + ort * 0.4));\n}\nfunction yaklasanOtobusler(hat, yon, hedefIndex) {\n  const v = S.hatVeri[hat], liste = v?.duraklar?.[yon]; if (!liste) return [];\n  return (v.otobusler || []).filter((b) => b.yon === yon).map((b) => {\n    const a = S.arac.get(hat + \"/\" + b.kapino);\n    const p = a ? { ...b, lat: a.gor.lat, lon: a.gor.lon } : b;\n    return { bus: b, t: Core.varisTahmini(liste, p, hedefIndex, aracHizi(hat, b.kapino)), gozlenen: a?.hiz != null };\n  }).filter((x) => x.t).sort((a, b) => a.t.metre - b.t.metre);\n}\nfunction aracCiz(hat) {\n  const v = S.hatVeri[hat]; if (!v) return;\n  for (const a of S.arac.values()) {\n    if (a.hat !== hat) continue;\n    const liste = v.duraklar?.[a.yon] || [];\n    const s = liste.length ? Core.siradakiDurak(liste, a.gor) : -1;\n    const aci = s >= 0 ? Core.yonAcisi(a.gor, liste[s]) : null;\n    const ikon = aracIkon(v.mb ? \"mb\" : \"otobus\", v.renk, aci, hat);\n    if (!a.isaret) {\n      a.isaret = L.marker([a.gor.lat, a.gor.lon], { icon: ikon, zIndexOffset: 500 }).on(\"click\", () => aracAc(a.hat, a.kapino)).addTo(aracKatmani);\n      a.aci = aci;\n    }\n    else { a.isaret.setLatLng([a.gor.lat, a.gor.lon]); if (aci == null || a.aci == null || Math.abs(aci - a.aci) > 12) { a.isaret.setIcon(ikon); a.aci = aci; } }\n  }\n}\n// ---------- otobüse dokununca: araç bilgi kartı ----------\nlet takipArac = null; // haritanın takip ettiği araç anahtarı\nmap.on(\"dragstart\", () => { takipArac = null; });\nfunction aracKarti(a) {\n  if (!a) return `<div class=\"kart\"><div class=\"bos\">Bu araç şu an görünmüyor (sefer bitmiş ya da konum gelmiyor).</div></div>`;\n  const hat = a.hat, v = S.hatVeri[hat] || {}, b = v.bilgi || {};\n  const liste = v.duraklar?.[a.yon] || [], simdi = Zaman.simdi();\n  const s = liste.length ? Core.siradakiDurak(liste, a.gor) : -1;\n  const hiz = aracHizi(hat, a.kapino);\n  const tah = (i) => liste.length && s >= 0 && i >= s ? Core.varisTahmini(liste, a.gor, i, hiz) : null;\n  let h = \"\";\n  if (liste.length) h += `<div style=\"font-weight:600;font-size:16px\">→ ${esc(bas(liste[liste.length - 1].ad))} yönü</div>`;\n  if (b.ad) h += `<div class=\"not\">${esc(bas(b.ad))}</div>`;\n  // durum satırı\n  const yas = Math.max(0, Math.round((Date.now() - a.gercek.ms) / 1000));\n  const durum = [];\n  if (a.hiz != null) durum.push(a.hiz < 3 ? \"duruyor / trafikte\" : `~${Math.round(a.hiz)} km/sa`);\n  durum.push(yas < 90 ? `konum ${yas} sn önce` : `konum ${Math.round(yas / 60)} dk önce`);\n  h += `<div class=\"not\">${durum.join(\" · \")}</div>`;\n  const yer = liste.length ? aracYeri(liste, a) : null;\n  if (yer) h += `<div class=\"ak-kutu\">📍 <b>Şu an:</b> ${yer.durakta != null ? `<b>${esc(bas(liste[yer.durakta].ad))}</b> durağında` : yer.sonraki > 0 ? `<b>${esc(bas(liste[yer.sonraki - 1].ad))}</b> ile <b>${esc(bas(liste[yer.sonraki].ad))}</b> arasında · sıradakine ${metre(yer.metre)}` : `<b>${esc(bas(liste[0].ad))}</b> durağına ${metre(yer.metre)}`}</div>`;\n  // durağıma ne zaman?\n  const hd = hedefDurak(hat, a.yon);\n  if (hd && s >= 0) {\n    const t = tah(hd.i);\n    if (t) h += `<div class=\"ak-kutu\"><b>${hd.secili ? \"Durağınıza\" : \"Size en yakın durağa\"}</b> (${esc(bas(hd.d.ad))})<br><span class=\"ak-buyuk\">${t.dakika <= 1 ? \"geliyor\" : \"~\" + t.dakika + \" dk\"}</span> <span class=\"not\">${t.durakSayisi} durak · ${metre(t.metre)} · ${saat(simdi + t.dakika)}</span></div>`;\n    else h += `<div class=\"ak-kutu not\">${esc(bas(hd.d.ad))} durağını geçti</div>`;\n  }\n  // sıradaki duraklar\n  if (s >= 0) {\n    const son = liste.length - 1, satir = [];\n    for (let i = s; i <= son && satir.length < 5; i++) { const t = tah(i); if (t) satir.push(`<li><span>${esc(bas(liste[i].ad))}</span><span class=\"not\">${saat(simdi + t.dakika)}</span></li>`); }\n    if (s + 5 <= son) { const t = tah(son); satir.push(`<li class=\"ak-son\"><span>… ${son - s - 4} durak daha · <b>${esc(bas(liste[son].ad))}</b></span><span class=\"not\">${t ? saat(simdi + t.dakika) : \"\"}</span></li>`); }\n    h += `<div class=\"ak-alt\">Sıradaki duraklar <span class=\"not\">(${son - s + 1} durak kaldı)</span></div><ul class=\"ak-liste\">${satir.join(\"\")}</ul>`;\n    // yolculuğun ne kadarı tamamlandı\n    const yuzde = Math.round((s / Math.max(1, son)) * 100);\n    h += `<div class=\"ak-bar\"><span style=\"width:${yuzde}%;background:${v.renk}\"></span></div><div class=\"not\" style=\"display:flex;justify-content:space-between\"><span>${esc(bas(liste[0].ad))}</span><span>%${yuzde}</span></div>`;\n  }\n  // sefer saatleri (bu yön, bugün)\n  const gun = Zaman.gunTipi(), saatler = v.seferler?.[a.yon]?.[gun];\n  if (saatler?.length) {\n    const dk = saatler.map(Zaman.dk).filter((x) => x != null);\n    // bu araç hangi seferde? ilk duraktan buraya kadar geçen süre ile tahmin\n    let sefer = null;\n    if (s > 0) { const yol = Core.varisTahmini(liste, liste[0], s, v.hiz || 15); if (yol) { const kalk = simdi - yol.dakika; sefer = dk.filter((x) => x <= simdi).reduce((e, x) => (Math.abs(x - kalk) < Math.abs((e ?? 1e9) - kalk) ? x : e), null); if (sefer != null && Math.abs(sefer - kalk) > 25) sefer = null; } }\n    const sonraki = dk.filter((x) => x >= simdi).slice(0, 6);\n    h += `<div class=\"ak-alt\">Sefer saatleri · ${esc(bas(liste[0]?.ad || \"\"))} kalkış</div>`;\n    if (sefer != null) h += `<div class=\"not\">Bu araç büyük ihtimalle <b style=\"color:var(--yazi)\">${saat(sefer)}</b> seferi</div>`;\n    h += `<div class=\"ak-saatler\">${sonraki.length ? sonraki.map((x, k) => `<span class=\"${k === 0 ? \"ilk\" : \"\"}\">${saat(x)}</span>`).join(\"\") : `<span class=\"not\">Bugün başka sefer yok</span>`}</div>`;\n    h += `<div class=\"not\">İlk ${saat(dk[0])} · Son ${saat(dk[dk.length - 1])} · bugün ${dk.length} sefer</div>`;\n  } else if (!v.seferler) {\n    h += `<div class=\"not\" style=\"margin-top:6px\">Sefer saatleri yükleniyor…</div>`;\n  }\n  if (b.km || b.dk) h += `<div class=\"not\" style=\"margin-top:4px\">Hat ${b.km ? b.km.toFixed(1) + \" km\" : \"\"}${b.dk ? \" · tam sefer ~\" + Math.round(b.dk) + \" dk\" : \"\"} · ${(v.otobusler || []).length} araç seferde</div>`;\n  const key = hat + \"/\" + a.kapino;\n  h += `<div class=\"ak-butonlar\"><button class=\"btn kucuk\" data-ak=\"takip\">${takipArac === key ? \"✓ Takip ediliyor\" : \"📍 Haritada takip et\"}</button><button class=\"btn kucuk\" data-ak=\"hat\" data-akhat=\"${esc(hat)}\" data-akyon=\"${esc(a.yon)}\">Hat sayfası ›</button></div>`;\n  return `<div class=\"kart arac-kart\">${h}</div>`;\n}\n// Aracın güzergahtaki yeri: {durakta: i} ya da {sonraki: i, metre, oran} (önceki ile sonraki durak arası)\nfunction aracYeri(liste, a) {\n  const s = Core.siradakiDurak(liste, a.gor); if (s < 0) return null;\n  const mS = Core.mesafe(a.gor, liste[s]);\n  if (mS < 60) return { durakta: s, sonraki: s, metre: mS };\n  if (s > 0) { const mO = Core.mesafe(a.gor, liste[s - 1]); if (mO < 40) return { durakta: s - 1, sonraki: s, metre: mS };\n    return { sonraki: s, metre: mS, oran: mO / (mO + mS) }; }\n  return { sonraki: s, metre: mS, oran: 0 };\n}\n// Otobüse dokununca panelde araç sayfası aç (zaten araç sayfasındaysa yerine koy)\nfunction aracAc(hat, kapino) {\n  if (panelKonum() === \"tam\") panelAyarla(\"normal\");\n  const yeni = { tur: \"arac\", hat, kapino };\n  if (sayfa().tur === \"arac\") S.yigin[S.yigin.length - 1] = yeni; else S.yigin.push(yeni);\n  takipArac = hat + \"/\" + kapino;\n  ciz(true);\n}\nasync function aracSayfa(p, ilk, no) {\n  const key = p.hat + \"/\" + p.kapino;\n  if (ilk) { aktifHatlarAyarla([p.hat]); onYukle(esc(p.hat) + \" · \" + esc(p.kapino), true); }\n  const v = await hatHazirla(p.hat);\n  if (!v.otobusler || ilk) konumIsle(p.hat, await API.iett.konum(p.hat));\n  if (no !== cizimNo) return null;\n  const a = S.arac.get(key);\n  if (ilk || p.cizilenYon !== a?.yon) { katman.clearLayers(); if (a) { guzergahCiz(p.hat, a.yon); p.cizilenYon = a.yon; } if (a && ilk) map.setView([a.gor.lat, a.gor.lon], Math.max(map.getZoom(), 15)); }\n  aracCiz(p.hat);\n  if (a) { hedefKatmani.clearLayers(); hedefGor.clear(); hedefAdlar.length = 0; const hd = hedefDurak(p.hat, a.yon); if (hd) durakIsaretle(p.hat, hd.d, v.renk); }\n  if (!v.seferler) API.iett.seferler(p.hat).then((x) => { v.seferler = x || {}; if (sayfa() === p) panelYenile(); }).catch(() => { v.seferler = {}; });\n  return baslikHTML(`<span class=\"rozet\" style=\"background:${v.renk}\">${v.mb ? \"🚍\" : \"🚌\"} ${esc(p.hat)}</span> <span style=\"font-size:15px\">Araç ${esc(p.kapino)}</span>`, true) + aracKarti(a);\n}\ndocument.addEventListener(\"click\", (e) => {\n  const ar = e.target.closest(\"[data-arac]\");\n  if (ar && sayfa().tur === \"hat\") { e.stopImmediatePropagation(); return aracAc(sayfa().hat, ar.dataset.arac); }\n  const b = e.target.closest(\"[data-ak]\"); if (!b) return;\n  const p = sayfa();\n  if (b.dataset.ak === \"takip\" && p.tur === \"arac\") {\n    const key = p.hat + \"/\" + p.kapino; takipArac = takipArac === key ? null : key;\n    const a = S.arac.get(key); if (takipArac && a) map.setView([a.gor.lat, a.gor.lon], Math.max(map.getZoom(), 15));\n    ciz();\n  } else if (b.dataset.ak === \"hat\") git({ tur: \"hat\", hat: b.dataset.akhat, yon: b.dataset.akyon });\n});\n// Her saniye: son gerçek konumdan bu yana güzergah boyunca ilerlet (en fazla 2 dk)\nfunction oluHesap() {\n  for (const a of S.arac.values()) {\n    if (!a.isaret) continue;\n    const v = S.hatVeri[a.hat], liste = v?.duraklar?.[a.yon]; if (!liste?.length) continue;\n    const gecen = (Date.now() - a.gercek.ms) / 1000;\n    if (gecen > 150 || (a.hiz != null && a.hiz < 3)) continue;\n    let kalan = (aracHizi(a.hat, a.kapino) * 0.85 / 3.6) * 1; // 1 saniyede metre\n    let p = { ...a.gor }, i = Core.siradakiDurak(liste, p);\n    // gerçek konumdan en fazla 1.5 km uzaklaş\n    if (Core.mesafe(p, a.gercek) > 1500) continue;\n    while (kalan > 0 && i >= 0 && i < liste.length) {\n      const h = liste[i], m = Core.mesafe(p, h);\n      if (m > kalan) { const f = kalan / m; p = { lat: p.lat + (h.lat - p.lat) * f, lon: p.lon + (h.lon - p.lon) * f }; kalan = 0; }\n      else { p = { lat: h.lat, lon: h.lon }; kalan -= m; i++; }\n    }\n    a.gor = p; a.isaret.setLatLng([p.lat, p.lon]);\n  }\n  if (takipArac) { const t = S.arac.get(takipArac); if (t?.isaret) map.panTo([t.gor.lat, t.gor.lon], { animate: true, duration: 0.8 }); else takipArac = null; }\n}\nlet canliCalisiyor = false;\nasync function canliTur() {\n  if (canliCalisiyor || document.hidden || !S.aktifHatlar.size) return;\n  canliCalisiyor = true;\n  let degisti = false;\n  try {\n    await Promise.all([...S.aktifHatlar].map(async (hat) => {\n      try { await hatHazirla(hat); const l = await API.iett.konum(hat); if (S.aktifHatlar.has(hat) && konumIsle(hat, l)) { degisti = true; aracCiz(hat); } } catch {}\n    }));\n  } finally { canliCalisiyor = false; }\n  if (degisti) { const p = sayfa(); if ([\"yakin\", \"hat\", \"rdetay\", \"arac\"].includes(p.tur)) panelYenile(); }\n}\nfunction aktifHatlarAyarla(hatlar) {\n  const yeni = new Set(hatlar);\n  for (const [k, a] of S.arac) if (!yeni.has(a.hat)) { if (a.isaret) aracKatmani.removeLayer(a.isaret); a.isaret = null; }\n  S.aktifHatlar = yeni;\n}\n\n// ---------- tahmini tren ve vapur konumları ----------\nlet tahminiKaynak = null; // {tur:'rayli'|'vapur', ...} — her saniye konumlar yeniden hesaplanır\nfunction tahminiCiz() {\n  if (!tahminiKaynak) return;\n  const simdi = Zaman.simdi() + new Date().getSeconds() / 60;\n  const gor = new Set();\n  const koy = (key, ll, tur, renk, aci, etiket, ipucu) => {\n    gor.add(key);\n    let m = tahminiIsaret.get(key);\n    if (!m) { m = L.marker(ll, { icon: aracIkon(tur, renk, aci, etiket, true), zIndexOffset: 400 }).bindPopup(ipucu).addTo(aracKatmani); m._aci = aci; tahminiIsaret.set(key, m); }\n    else { m.setLatLng(ll); if (Math.abs((m._aci ?? 0) - (aci ?? 0)) > 15) { m.setIcon(aracIkon(tur, renk, aci, etiket, true)); m._aci = aci; } m.setPopupContent(ipucu); }\n  };\n  for (const tr of tahminiKaynak.seferler || []) {\n    const { d, t } = tr; // d: [{lat,lon,ad}], t: [dk]\n    if (simdi < t[0] || simdi > t[t.length - 1]) continue;\n    let k = 0; while (k < t.length - 2 && simdi > t[k + 1]) k++;\n    const f = t[k + 1] > t[k] ? (simdi - t[k]) / (t[k + 1] - t[k]) : 0;\n    const a = d[k], b = d[k + 1];\n    const ll = [a.lat + (b.lat - a.lat) * f, a.lon + (b.lon - a.lon) * f];\n    const ip = `<b>${esc(tr.hat)}</b> → ${esc(tr.hedef)}<br>Sıradaki: ${esc(b.ad)} · ${saat(t[k + 1])}<br><span class=\"not\">Tarifeye göre tahmini konum</span>`;\n    koy(tr.key, ll, tr.tur, tr.renk, Core.yonAcisi(a, b), tr.hat, ip);\n  }\n  for (const [k, m] of tahminiIsaret) if (!gor.has(k)) { aracKatmani.removeLayer(m); tahminiIsaret.delete(k); }\n}\n// Raylı hat için: ilk istasyondan kalkışlar + istasyonlar arası süreler -> seferler\nasync function rayliTahminiHazirla(hat, istasyonlar) {\n  const ag = Plan.kur({ hatlar: [hat], istasyonlar, marmaray: false });\n  const yonler = await API.metro.yonler(hat.id).catch(() => []);\n  const seferler = [];\n  for (const p of ag.desenler) {\n    const d = p.d.map((i) => ag.duraklar[i]);\n    const toplam = p.t[p.t.length - 1];\n    const hedef = Plan.norm(d[d.length - 1].ad), bas0 = Plan.norm(d[0].ad);\n    const y = yonler.find((x) => { const [a, b] = x.ad.split(\"->\").map(Plan.norm); return (b && (b.startsWith(hedef.slice(0, 5)) || hedef.startsWith(b.slice(0, 5)))) || (a && (a.startsWith(bas0.slice(0, 5)))); });\n    let kalkislar = [];\n    if (y) {\n      try {\n        const geri = new Date(Date.now() - (toplam + 3) * 60000);\n        const p2 = (n) => String(n).padStart(2, \"0\");\n        const iso = `${geri.getFullYear()}-${p2(geri.getMonth() + 1)}-${p2(geri.getDate())}T${p2(geri.getHours())}:${p2(geri.getMinutes())}:00`;\n        const j = JSON.parse(await API.http(\"https://api.ibb.gov.tr/MetroIstanbul/api/MetroMobile/V2/GetTimeTable\", { method: \"POST\", headers: { \"Content-Type\": \"application/json\" }, body: JSON.stringify({ BoardingStationId: d[0].istId, LineId: hat.id, DirectionId: y.id, DateTime: iso }) }));\n        kalkislar = (j.Data?.[0]?.TimeInfos?.Times || []).map(Zaman.dk).filter((x) => x != null);\n      } catch {}\n    }\n    if (!kalkislar.length) { const s = Zaman.simdi(); for (let k = s - toplam - p.aralik; k <= s + 30; k += p.aralik) kalkislar.push(Math.round(k)); }\n    for (const k of kalkislar) seferler.push({ key: p.id + \"@\" + k, hat: hat.ad, renk: hat.renk, tur: p.tur, hedef: d[d.length - 1].ad, d, t: p.t.map((x) => k + x) });\n  }\n  return seferler;\n}\n\n// ---------- trafik katmanı ----------\nconst Trafik = { geo: null, ana: null, veri: null, indeks: null, zaman: 0, yukleniyor: false };\nasync function trafikYukle(zorla) {\n  if (Trafik.yukleniyor) return;\n  Trafik.yukleniyor = true; trafikBilgiYaz(\"Trafik verisi yükleniyor…\");\n  try {\n    if (!Trafik.geo) {\n      const [g0, g4] = await Promise.all([API.trafik.geometri(0), API.trafik.geometri(4).catch(() => [])]);\n      Trafik.geo = g0; Trafik.ana = new Set(g4.map((x) => x[0]));\n    }\n    if (zorla || Date.now() - Trafik.zaman > 110e3) {\n      [Trafik.veri, Trafik.indeks] = await Promise.all([API.trafik.veri(), API.trafik.indeks()]);\n      Trafik.zaman = Date.now();\n    }\n    trafikCiz(); trafikBilgiYaz();\n  } catch (e) { trafikBilgiYaz(\"Trafik verisi alınamadı: \" + hataMesaji(e)); }\n  finally { Trafik.yukleniyor = false; }\n}\nfunction trafikCiz() {\n  trafikKatmani.clearLayers();\n  if (!S.trafik || !Trafik.geo || !Trafik.veri) return;\n  const z = map.getZoom(), b = map.getBounds().pad(0.15);\n  const s = b.getSouth(), w = b.getWest(), n = b.getNorth(), e = b.getEast();\n  const sadeceAna = z < 13, adim = z < 12 ? 6 : z < 14 ? 2 : 1;\n  const kalin = z < 12 ? 2.5 : z < 15 ? 4 : 6;\n  let sayi = 0;\n  for (const [id, duz, a, bb, c, d] of Trafik.geo) {\n    if (c < s || a > n || d < w || bb > e) continue;\n    if (sadeceAna && !Trafik.ana.has(id)) continue;\n    const v = Trafik.veri.get(id); if (!v) continue;\n    const ll = []; for (let i = 0; i < duz.length; i += 2 * adim) ll.push([duz[i], duz[i + 1]]);\n    if (duz.length >= 2) ll.push([duz[duz.length - 2], duz[duz.length - 1]]);\n    L.polyline(ll, { renderer: trafikCizici, color: TRAFIK_RENK[v[0]] || \"#999\", weight: kalin, opacity: .85, interactive: false }).addTo(trafikKatmani);\n    if (++sayi > 6000) break;\n  }\n}\nfunction trafikBilgiYaz(mesaj) {\n  const el = $(\"#trafikBilgi\");\n  if (!S.trafik) { el.style.display = \"none\"; return; }\n  el.style.display = \"block\";\n  if (mesaj) { el.textContent = mesaj; return; }\n  const i = Trafik.indeks;\n  el.innerHTML = `<b>Trafik</b>${i ? ` · İstanbul %${i.TI} · Anadolu %${i.TI_An} · Avrupa %${i.TI_Av}` : \"\"}<div class=\"l\">${[1, 2, 3, 4, 5].map((k) => `<i style=\"background:${TRAFIK_RENK[k]}\"></i>`).join(\"\")}<span class=\"not\" style=\"margin-left:4px\">akıcı → çok yoğun · ${new Date(Trafik.zaman).toLocaleTimeString(\"tr-TR\", { hour: \"2-digit\", minute: \"2-digit\" })}</span></div>`;\n}\n$(\"#trafikBtn\").addEventListener(\"click\", () => {\n  S.trafik = !S.trafik; $(\"#trafikBtn\").classList.toggle(\"acik\", S.trafik); KV.set(\"trafik\", S.trafik);\n  if (S.trafik) trafikYukle(); else { trafikKatmani.clearLayers(); trafikBilgiYaz(); }\n});\nmap.on(\"moveend zoomend\", () => { if (S.trafik) trafikCiz(); });\n\n// ---------- konum ----------\nasync function benimKonum(sessiz) {\n  try { const p = await Native.call(\"location\"); if (p && isFinite(p.lat)) { S.ben = p; benCiz(); return p; } }\n  catch (e) { if (!sessiz) throw e; }\n  return null;\n}\n$(\"#konumBtn\").addEventListener(\"click\", async () => {\n  S.konumHata = null;\n  try { await benimKonum(false); if (S.ben) map.setView([S.ben.lat, S.ben.lon], 15); }\n  catch (err) { S.konumHata = \"Konum alınamadı: \" + hataMesaji(err) + \". Ayarlar › Scriptable › Konum iznini kontrol edin.\"; }\n  panelYenile();\n});\n\n// Bir hat/yön için hedef durak: seçili durak, yoksa konuma en yakın durak\nfunction hedefDurak(hat, yon) {\n  const liste = S.hatVeri[hat]?.duraklar?.[yon]; if (!liste?.length) return null;\n  const secili = S.durak[hat] ? liste.findIndex((d) => d.kod === S.durak[hat]) : -1;\n  if (secili >= 0) return { i: secili, d: liste[secili], secili: true };\n  if (S.durak[hat]) {\n    const tum = Object.values(S.hatVeri[hat].duraklar).flat().find((d) => d.kod === S.durak[hat]);\n    if (tum) { const r = Core.enYakinIndex(liste, tum); if (r.metre < 400) return { i: r.index, d: liste[r.index], secili: true }; }\n  }\n  if (S.ben) { const r = Core.enYakinIndex(liste, S.ben); return { i: r.index, d: liste[r.index], metre: r.metre }; }\n  return null;\n}\nfunction guzergahCiz(hat, sadeceYon) {\n  const v = S.hatVeri[hat]; if (!v?.duraklar) return [];\n  const pts = [];\n  for (const [yon, liste] of Object.entries(v.duraklar)) {\n    if (sadeceYon && yon !== sadeceYon) continue;\n    const ll = liste.map((d) => [d.lat, d.lon]); pts.push(...ll);\n    L.polyline(ll, { color: v.renk, weight: 3, opacity: .75, interactive: false }).addTo(katman);\n    for (const d of liste) {\n      const sec = S.durak[hat] === d.kod;\n      L.circleMarker([d.lat, d.lon], { radius: sec ? 6 : 4, color: v.renk, weight: 2, fillColor: sec ? v.renk : \"#fff\", fillOpacity: 1 }).bindPopup(() => durakPopup(hat, d)).addTo(sec ? katman : durakKatmani);\n    }\n    zoomAyarla();\n  }\n  return pts;\n}\nfunction durakPopup(hat, d) {\n  const el = document.createElement(\"div\"), sec = S.durak[hat] === d.kod;\n  let yonY = \"\";\n  const v = S.hatVeri[hat]; if (v?.duraklar) for (const [y, l] of Object.entries(v.duraklar)) if (l.some((x) => x.kod === d.kod)) yonY = \"→ \" + bas(l[l.length - 1].ad) + \" yönü\";\n  el.innerHTML = `<b>${esc(bas(d.ad))}</b><br><span class=\"not\">${esc(yonY)}${yonY ? \" · \" : \"\"}Durak ${esc(d.kod)} · ${esc(hat)}</span><br>`;\n  const b = document.createElement(\"button\");\n  b.className = \"btn kucuk\"; b.style.marginTop = \"6px\";\n  b.textContent = sec ? \"Durağım ✓ (kaldır)\" : \"Durağım yap\";\n  b.onclick = () => { if (sec) delete S.durak[hat]; else S.durak[hat] = d.kod; durakKaydet(); map.closePopup(); ciz(); };\n  el.appendChild(b);\n  return el;\n}\n\n// ---------- sayfa yönetimi ----------\nlet cizimNo = 0;\nfunction sayfa() { return S.yigin.length ? S.yigin[S.yigin.length - 1] : { tur: S.sekme }; }\nfunction git(s) { S.yigin.push(s); ciz(true); }\nfunction geri() { S.yigin.pop(); ciz(true); }\nfunction baslikHTML(metin, geriVar, ek = \"\") { return `<h1>${geriVar ? '<button class=\"geri\" data-geri>‹</button>' : \"\"}<span style=\"flex:1;min-width:0\">${metin}</span>${ek}</h1>`; }\nconst yukleniyor = (m = \"Yükleniyor…\") => `<div class=\"yukleniyor\">${m}</div>`;\nfunction onYukle(b, g) { $(\"#icerik\").innerHTML = baslikHTML(b, g) + yukleniyor(); }\nlet panelZamanlayici = null;\nfunction panelYenile() { clearTimeout(panelZamanlayici); panelZamanlayici = setTimeout(() => ciz(), 120); }\n\nasync function ciz(sayfaDegisti) {\n  const no = ++cizimNo, p = sayfa();\n  if (sayfaDegisti) { if (p.tur !== \"arac\") takipArac = null; haritaTemizle(); tahminiKaynak = null; $(\"#panel\").scrollTop = 0; map.off(\"click\", haritaSecimTik); secimBitir(); }\n  const ic = $(\"#icerik\");\n  try {\n    const html = await ({ yakin: yakinSayfa, rota: rotaSayfa, rdetay: rotaDetaySayfa, otobus: otobusSayfa, hat: hatSayfa, rayli: rayliSayfa, rhat: rayliHatSayfa, ist: istasyonSayfa, vapur: vapurSayfa, vhat: vapurHatSayfa, arac: aracSayfa })[p.tur](p, sayfaDegisti, no);\n    if (no !== cizimNo) return;\n    if (html != null) {\n      const aktif = document.activeElement, id = aktif && aktif.id, pos = aktif && aktif.selectionStart;\n      ic.innerHTML = html;\n      if (id) { const el = document.getElementById(id); if (el && el.tagName === \"INPUT\") { el.focus(); try { el.setSelectionRange(pos, pos); } catch {} } }\n    }\n  } catch (e) {\n    if (no !== cizimNo) return;\n    ic.innerHTML = baslikHTML(\"Hata\", S.yigin.length > 0) + `<div class=\"kart\"><div class=\"bos hata\">${esc(hataMesaji(e))}</div></div><button class=\"btn\" data-yenile>Tekrar dene</button>`;\n  }\n}\n\n// ---------- 1) YAKINIMDA ----------\nasync function yakinSayfa(p, ilk, no) {\n  if (ilk) { onYukle(\"Yakınımda\", false); aktifHatlarAyarla(S.favoriler); }\n  if (ilk || !S.ben) await benimKonum(true);\n  const favs = S.favoriler.slice();\n  const hatalar = (await Promise.all(favs.map(async (h) => {\n    try { await hatHazirla(h); if (!S.hatVeri[h].otobusler) { konumIsle(h, await API.iett.konum(h)); } aracCiz(h); return null; }\n    catch (e) { return `${h}: ${hataMesaji(e)}`; }\n  }))).filter(Boolean);\n  if (no !== cizimNo) return null;\n  if (ilk) {\n    katman.clearLayers(); durakKatmani.clearLayers();\n    // Favori hatların durakları (yakınlaşınca görünür)\n    const gor = new Set();\n    for (const h of favs) for (const l of Object.values(S.hatVeri[h]?.duraklar || {})) for (const d of l) {\n      if (gor.has(d.kod)) continue; gor.add(d.kod);\n      L.circleMarker([d.lat, d.lon], { radius: 4.5, color: S.hatVeri[h].renk, weight: 2, fillColor: \"#fff\", fillOpacity: 1 }).bindPopup(() => durakPopup(h, d)).addTo(durakKatmani);\n    }\n    zoomAyarla();\n  }\n  hedefKatmani.clearLayers(); hedefGor.clear(); hedefAdlar.length = 0;\n  const noktalar = S.ben ? [[S.ben.lat, S.ben.lon]] : [];\n\n  let ust = baslikHTML(\"Yakınımda\", false);\n  ust += S.ben ? `<div class=\"not\">Konumunuz ±${Math.round(S.ben.acc || 0)} m · otobüsler canlı izleniyor <span class=\"canli\">CANLI</span></div>`\n               : `<div class=\"not\">Konum alınamadı. Haritadaki 📍 düğmesine basın ya da bir durak seçin.</div>`;\n  if (S.konumHata) ust += `<div class=\"hata\" style=\"margin-top:6px\">${esc(S.konumHata)}</div>`;\n  if (hatalar.length) ust += `<div class=\"hata\" style=\"margin-top:6px\">${hatalar.map(esc).join(\"<br>\")}</div>`;\n\n  let fav = `<h2>Favori hatlarım</h2>`;\n  if (!favs.length) fav += `<div class=\"kart\"><div class=\"bos\">Henüz favori hat yok. Otobüs sekmesinden hat arayıp ☆ ile ekleyin.</div></div>`;\n  for (const hat of favs) {\n    const v = S.hatVeri[hat];\n    if (!v?.duraklar || !Object.keys(v.duraklar).length) { fav += `<div class=\"kart\"><div class=\"bas tik\" data-hat=\"${esc(hat)}\"><span class=\"rozet\" style=\"background:${renkKod(hat)}\">${esc(hat)}</span><span class=\"ad not\">Hat verisi alınamadı</span><span class=\"not\">›</span></div></div>`; continue; }\n    for (const yon of Object.keys(v.duraklar).sort()) {\n      const liste = v.duraklar[yon], h = hedefDurak(hat, yon);\n      let govde;\n      if (!h) govde = `<div class=\"bos\">Konum ya da seçili durak yok.</div>`;\n      else {\n        noktalar.push([h.d.lat, h.d.lon]);\n        durakIsaretle(hat, h.d, v.renk);\n        const gel = yaklasanOtobusler(hat, yon, h.i).slice(0, 3);\n        if (gel[0]) { const a = S.arac.get(hat + \"/\" + gel[0].bus.kapino); if (a) noktalar.push([a.gor.lat, a.gor.lon]); }\n        govde = `<div class=\"alt\">${h.secili ? \"Durağım\" : \"En yakın durak\"}: <b style=\"color:var(--yazi)\">${esc(bas(h.d.ad))}</b>${h.metre != null ? \" · \" + metre(h.metre) : \"\"}</div>`;\n        govde += `<ul class=\"liste\">` + (gel.length ? gel.map((x) => otobusSatiri(hat, x)).join(\"\") : `<li><div class=\"ana\"><span class=\"not\">Bu yönde yaklaşan otobüs yok</span></div></li>`) + `</ul>`;\n      }\n      fav += `<div class=\"kart\"><div class=\"bas tik\" data-hat=\"${esc(hat)}\"><span class=\"rozet\" style=\"background:${v.renk}\">${esc(hat)}</span><span class=\"ad\">→ ${esc(bas(liste[liste.length - 1].ad))}</span><span class=\"not\">›</span></div>${govde}</div>`;\n    }\n  }\n\n  let rayli = \"\";\n  if (S.ben) {\n    try {\n      const [ist, hatlar] = await Promise.all([API.metro.istasyonlar(), API.metro.hatlar()]);\n      const yakin = ist.map((s) => ({ s, m: Core.mesafe(S.ben, s) })).filter((x) => x.m < 2000).sort((a, b) => a.m - b.m);\n      const secilen = []; const hg = new Set();\n      for (const x of yakin) { if (hg.has(x.s.hatId)) continue; hg.add(x.s.hatId); secilen.push(x); if (secilen.length >= 2) break; }\n      if (secilen.length) {\n        rayli = `<h2>Yakındaki raylı sistem</h2>` + (await Promise.all(secilen.map(async ({ s, m }) => {\n          const hat = hatlar.find((h) => h.id === s.hatId);\n          noktalar.push([s.lat, s.lon]);\n          if (ilk) L.circleMarker([s.lat, s.lon], { radius: 7, color: hat?.renk || \"#333\", weight: 3, fillColor: \"#fff\", fillOpacity: 1 }).bindPopup(esc(s.ad) + \" · \" + esc(s.hat)).addTo(katman);\n          let satirlar = \"\";\n          try {\n            const yonler = await API.metro.yonler(s.hatId);\n            const ss = await Promise.all(yonler.map((y) => API.metro.saatler(s.id, s.hatId, y.id).then((t) => ({ y, t })).catch(() => null)));\n            satirlar = ss.filter(Boolean).map(({ y, t }) => { const sonra = t.saatler.slice(0, 3); return `<li>${sureEtiket(sonra.length ? Zaman.kalan(sonra[0]) : null)}<div class=\"ana\"><b>→ ${esc(t.hedef || y.ad.split(\"->\").pop())}</b><small>${sonra.map(esc).join(\" · \") || \"Sefer yok\"}</small></div></li>`; }).join(\"\");\n          } catch (e) { satirlar = `<li><span class=\"hata\">${esc(hataMesaji(e))}</span></li>`; }\n          return `<div class=\"kart\"><div class=\"bas tik\" data-ist=\"${s.id}\"><span class=\"rozet\" style=\"background:${hat?.renk || \"#333\"}\">${esc(s.hat)}</span><span class=\"ad\">${esc(s.ad)}</span><span class=\"not\">${metre(m)} ›</span></div><ul class=\"liste\">${satirlar}</ul></div>`;\n        }))).join(\"\");\n      }\n    } catch (e) { rayli = `<h2>Yakındaki raylı sistem</h2><div class=\"kart\"><div class=\"bos hata\">${esc(hataMesaji(e))}</div></div>`; }\n  }\n  if (no !== cizimNo) return null;\n  if (ilk) sigdir(noktalar.length > 1 ? noktalar : noktalar.concat(favs.flatMap((h) => Object.values(S.hatVeri[h]?.duraklar || {}).flat().map((d) => [d.lat, d.lon]))), 16);\n  return ust + fav + rayli + `<p class=\"not\">Otobüs süreleri, her otobüsün son dakikalarda ölçülen hızına (trafik) ve güzergah mesafesine göre tahmindir. İETT konumları yaklaşık dakikada bir yenilenir; aradaki hareket tahminidir.</p>`;\n}\nfunction otobusSatiri(hat, x) {\n  return `<li class=\"tik\" data-odakla=\"${esc(hat)}/${esc(x.bus.kapino)}\">${sureEtiket(x.t.dakika)}<div class=\"ana\"><b>${x.t.durakSayisi === 0 ? \"Sıradaki durak\" : x.t.durakSayisi + \" durak\"}</b><small>${metre(x.t.metre)} uzakta · ${esc(x.bus.kapino)}${x.gozlenen ? \" · trafik hesaba katıldı\" : \"\"}</small></div></li>`;\n}\n\n// ---------- 2) ROTA ----------\nfunction yerAdi(y) { return !y ? \"\" : y.benim ? \"📍 Konumum\" : y.ad; }\nasync function rotaSayfa(p, ilk) {\n  const R = S.rota;\n  if (ilk) { aktifHatlarAyarla([]); if (!R.nereden) R.nereden = { benim: true, ad: \"Konumum\" }; agHazirla().catch(() => {}); }\n  if (ilk && R.nereden?.lat) ucIsaret([R.nereden.lat, R.nereden.lon], \"#16a34a\").addTo(katman);\n  if (ilk && R.nereye?.lat) ucIsaret([R.nereye.lat, R.nereye.lon], \"#dc2626\").addTo(katman);\n  let html = baslikHTML(\"Nereden → Nereye\", false);\n  const giris = (alan, ikon, ph) => {\n    const y = R[alan], duzenle = R.aktif === alan;\n    const yonNotu = y && !duzenle && y.kod && y.alt ? `<div class=\"not\" style=\"margin:-4px 0 6px 38px\">${esc(y.alt)}</div>` : \"\";\n    return `<div class=\"yer-giris\"><span class=\"ikon\">${ikon}</span><input id=\"yer_${alan}\" data-alan=\"${alan}\" placeholder=\"${ph}\" value=\"${esc(duzenle ? R.metin : yerAdi(y))}\" autocomplete=\"off\">${y && !duzenle ? `<button data-temizle=\"${alan}\">×</button>` : \"\"}</div>${yonNotu}`;\n  };\n  html += `<div class=\"rota-ust\"><div class=\"girisler\">${giris(\"nereden\", \"🟢\", \"Nereden?\")}${giris(\"nereye\", \"🔴\", \"Nereye? (yer, durak, istasyon)\")}</div><button class=\"degis\" data-degistir title=\"Yer değiştir\">⇅</button></div>`;\n  const zv = R.zaman || \"\";\n  html += `<div class=\"segment\" style=\"margin-top:2px\"><button data-zaman=\"simdi\" class=\"${R.zaman ? \"\" : \"aktif\"}\">Şimdi</button><button data-zaman=\"sec\" class=\"${R.zaman ? \"aktif\" : \"\"}\">📅 Tarih ve saat seç</button></div>`;\n  if (R.zaman) html += `<input type=\"datetime-local\" id=\"zamanSec\" class=\"ara\" value=\"${esc(zv)}\" style=\"margin-bottom:8px\">`;\n  if (R.aktif) {\n    // öneriler\n    const satir = (o, i) => `<li class=\"tik\" data-oneri=\"${i}\"><span style=\"font-size:18px\">${{ metro: \"🚇\", marmaray: \"🚆\", tram: \"🚋\", fun: \"🚠\", tf: \"🚠\", mb: \"🚍\", vapur: \"⛴\", durak: \"🚏\", benim: \"📍\", harita: \"🗺\", son: \"🕘\" }[o.tur] || \"📌\"}</span><div class=\"ana\">${esc(o.ad)}<small>${esc(o.alt || \"\")}</small></div></li>`;\n    const ozel = [];\n    if (R.aktif === \"nereden\") ozel.push({ tur: \"benim\", ad: \"Konumum\", alt: \"Bulunduğunuz yer\", benim: true });\n    ozel.push({ tur: \"harita\", ad: \"Haritadan seç\", alt: \"Haritada bir noktaya dokunun\", harita: true });\n    const liste = R.metin.trim().length >= 2 ? ozel.filter((x) => x.harita).concat(R.oneriler) : ozel.concat(R.son.map((x) => ({ ...x, tur: \"son\", alt: x.alt || \"Son aranan\" })));\n    R.gosterilen = liste;\n    html += `<div class=\"oneriler\"><ul class=\"liste\">${liste.map(satir).join(\"\") || '<li><span class=\"not\">Aranıyor…</span></li>'}</ul></div>`;\n  }\n  const agDurum = AG.otobus ? `Ağ hazır: ${AG.otobus.hatlar.length} otobüs/metrobüs hattı · metro · tramvay · Marmaray${S.agVapur ? \" · vapur\" : \"\"}`\n    : AG.indirme?.hata ? \"Otobüs ağı indirilemedi; otobüs önerileri Transitous'tan geliyor.\"\n    : AG.indirme ? `Otobüs ağı indiriliyor: ${AG.indirme.bitti}/${AG.indirme.toplam || \"…\"} hat (ilk seferde 1-2 dk, sonra haftada bir)` : \"\";\n  if (agDurum) html += `<div class=\"not\" style=\"margin:2px 2px 8px\">${esc(agDurum)}${AG.indirme && AG.indirme.toplam ? `<div style=\"height:4px;background:var(--cizgi);border-radius:2px;margin-top:4px\"><div style=\"height:4px;width:${Math.round(100 * AG.indirme.bitti / AG.indirme.toplam)}%;background:var(--vurgu);border-radius:2px\"></div></div>` : \"\"}</div>`;\n  if (R.nereden && R.nereye && !R.aktif) {\n    html += `<button class=\"btn ana tam\" data-rotabul>Rota bul</button>`;\n    if (R.durum) html += `<div class=\"not\" style=\"margin:8px 2px\">${esc(R.durum)}</div>`;\n    if (R.sonuclar) {\n      if (!R.sonuclar.length) html += `<div class=\"kart\"><div class=\"bos\">Uygun rota bulunamadı.</div></div>`;\n      const zEtiket = R.zaman ? new Date(R.zaman).toLocaleString(\"tr-TR\", { weekday: \"short\", day: \"numeric\", month: \"short\", hour: \"2-digit\", minute: \"2-digit\" }) : \"\";\n      html += `<h2>Rotalar · ${R.zaman ? esc(zEtiket) + \" için\" : \"şimdi çıkarsanız\"}</h2>`;\n      R.sonuclar.forEach((r, i) => { html += rotaKart(r, i); });\n      html += `<p class=\"not\">Rotalar uygulamanın kendi ağında (İETT, Metro İstanbul, Marmaray, Şehir Hatları) hesaplanır; Transitous ikinci görüş olarak eklenir. Otobüs binişleri canlı araç konumuna, yoksa İETT'nin planlanan sefer saatine göre zamanlanır.</p>`;\n    }\n  } else if (!R.aktif) html += `<div class=\"not\">Gitmek istediğiniz yeri yazın ya da haritadan seçin.</div>`;\n  return html;\n}\nfunction bacakRozet(b) {\n  const ikon = { metro: \"🚇\", marmaray: \"🚆\", tram: \"🚋\", fun: \"🚠\", tf: \"🚠\", mb: \"🚍\", vapur: \"⛴\", otobus: \"🚌\" }[b.tur] || \"🚌\";\n  return `<span class=\"rozet\" style=\"background:${b.renk || \"#444\"}\">${ikon} ${esc(b.tur === \"vapur\" ? \"Vapur\" : [b.hat, ...(b.ekHat || [])].join(\" / \"))}</span>`;\n}\nfunction zincirHTML(r) {\n  const p = [];\n  r.bacaklar.forEach((b, i) => {\n    if (i) p.push('<span class=\"ok\">›</span>');\n    p.push(b.tur === \"yuru\" ? `<span class=\"yuru\">🚶${Math.max(1, Math.round(b.varis - b.kalkis))}</span>` : bacakRozet(b));\n  });\n  return `<div class=\"zincir\">${p.join(\"\")}</div>`;\n}\nfunction rotaKart(r, i) {\n  if (r.gecersiz) return `<div class=\"kart\" style=\"opacity:.55\"><div class=\"bas\"><span class=\"sure tarife\" style=\"min-width:70px\">⛔</span><div class=\"ana\" style=\"flex:1;min-width:0\">${zincirHTML(r)}</div></div><div class=\"alt\">O saatte kullanılamaz: ${esc(r.gecersiz)}. Başka bir saat seçerek bakabilirsiniz.</div></div>`;\n  const ilkBinis = r.bacaklar.find((b) => b.tur !== \"yuru\");\n  const ilkYuru = r.bacaklar[0]?.tur === \"yuru\" ? r.bacaklar[0].varis - r.bacaklar[0].kalkis : 0;\n  const cikis = ilkBinis ? ilkBinis.kalkis - ilkYuru : r.kalkis;         // evden çıkış anı\n  const gece = ilkBinis && cikis - r.kalkis > 40;                       // şu an çalışan sefer yok\n  const yolculuk = r.varis - (gece ? cikis : r.kalkis);\n  const ilkB = r.bacaklar.find((x) => x.tur !== \"yuru\");\n  const canli = r.canli ? `<div class=\"alt\" style=\"padding-top:0\">${ilkB?.kaynak === \"canlı\" ? '<span class=\"canli\">CANLI</span> ' : \"🕘 \"}${esc(r.canli)}</div>` : \"\";\n  return `<div class=\"kart tik\" data-rota=\"${i}\"><div class=\"bas\"><span class=\"sure ${i === 0 && !gece ? \"yakin\" : \"\"}\" style=\"min-width:70px\">${gece ? \"🌙 \" + saat(cikis) : Math.round(r.sure) + \" dk\"}</span><div class=\"ana\" style=\"flex:1;min-width:0\">${zincirHTML(r)}</div></div>\n    <div class=\"alt\">${gece ? `${S.rota.zaman ? \"Seçilen saatte\" : \"Şu an\"} sefer yok · <b style=\"color:var(--yazi)\">${saat(cikis)}</b>'de yola çıkın · yolculuk ${Math.round(yolculuk)} dk · ` : `${saat(r.kalkis)} → `}<b style=\"color:var(--yazi)\">${saat(r.varis)}</b> varış · ${metre(r.yurumeM)} yürüme · ${r.aktarma ? `${r.aktarma} aktarma` : \"<b style=\\\"color:var(--iyi)\\\">aktarmasız</b>\"}${ilkBinis ? ` · ilk biniş ${saat(ilkBinis.kalkis)}, ${esc(ilkBinis.from.ad)}` : \"\"}</div>${canli}</div>`;\n}\nasync function rotaDetaySayfa(p, ilk) {\n  const r = S.rota.sonuclar?.[p.i]; if (!r) { S.yigin.pop(); return ciz(true); }\n  const otobusHatlari = [...new Set(r.bacaklar.filter((b) => (b.tur === \"otobus\" || b.iett) && b.hat && b.hat !== \"Metrobüs\").map((b) => b.hat))];\n  if (ilk) {\n    aktifHatlarAyarla(otobusHatlari);\n    const pts = [];\n    for (const b of r.bacaklar) {\n      const yol = b.yol || [[b.from.lat, b.from.lon], [b.to.lat, b.to.lon]]; pts.push(...yol);\n      if (b.tur === \"yuru\") L.polyline(yol, { color: \"#6b7280\", weight: 4, dashArray: \"2 8\", lineCap: \"round\", interactive: false }).addTo(katman);\n      else {\n        L.polyline(yol, { color: \"#fff\", weight: 7, opacity: .9, interactive: false }).addTo(katman);\n        L.polyline(yol, { color: b.renk || \"#444\", weight: 4, interactive: false }).addTo(katman);\n        L.circleMarker(yol[0], { radius: 5, color: b.renk, weight: 3, fillColor: \"#fff\", fillOpacity: 1 }).bindTooltip(esc(b.from.ad)).addTo(katman);\n      }\n    }\n    ucIsaret(pts[0], \"#16a34a\").addTo(katman); ucIsaret(pts[pts.length - 1], \"#dc2626\").addTo(katman);\n    sigdir(pts);\n    for (const h of otobusHatlari) hatHazirla(h).then(() => aracCiz(h)).catch(() => {});\n    canliTur();\n  }\n  let html = baslikHTML(`${Math.round(r.sure)} dk · ${saat(r.varis)} varış`, true);\n  html += `<div style=\"margin-bottom:8px\">${zincirHTML(r)}</div>`;\n  html += `<div class=\"kart\">` + r.bacaklar.map((b, i) => {\n    if (b.tur === \"yuru\") return `<div class=\"bacak\"><div class=\"zaman\">${saat(b.kalkis)}</div><div class=\"cizgi\" style=\"background:repeating-linear-gradient(#9ca3af 0 4px, transparent 4px 8px)\"></div><div class=\"icerik\">${(b.m || 0) < 40 && i > 0 && i < r.bacaklar.length - 1 ? `🔁 Aynı durakta aktarma` : `🚶 ${Math.max(1, Math.round(b.varis - b.kalkis))} dk yürü <span class=\"not\">(${metre(b.m)})</span>`}<small>→ ${i === r.bacaklar.length - 1 ? \"varış noktası\" : esc(b.to.ad) + (b.from?.ad && Plan.norm(b.from.ad) === Plan.norm(b.to.ad) ? \" (karşı taraftaki durak)\" : \"\")}</small></div></div>`;\n    const canli = b.canli ? (b.kaynak === \"canlı\" ? ` <span class=\"canli\">${esc(b.canli)}</span>` : ` <span class=\"not\">(${esc(b.canli)})</span>`) : \"\";\n    const tur = Plan.TUR_ADI[b.tur] || \"\";\n    return `<div class=\"bacak\"><div class=\"zaman\">${saat(b.kalkis)}</div><div class=\"cizgi\" style=\"background:${b.renk || \"#444\"}\"></div><div class=\"icerik\">${bacakRozet(b)} <b>${esc(b.from.ad)}</b>${canli}\n      <small>${tur}${b.yonAd ? \" · \" + esc(bas(b.yonAd)) + \" yönü\" : \"\"}${b.headsign ? \" · \" + esc(bas(b.headsign)) + \" yönü\" : \"\"}${b.bekleme ? ` · ~${Math.round(b.bekleme)} dk bekleme` : \"\"}</small>\n      <small>${b.durakSayisi ? b.durakSayisi + \" durak · \" : \"\"}${Math.max(1, Math.round(b.varis - b.kalkis))} dk yolculuk → <b style=\"color:var(--yazi)\">${esc(b.to.ad)}</b> ${saat(b.varis)}</small></div></div>`;\n  }).join(\"\") + `<div class=\"bacak\"><div class=\"zaman\">${saat(r.varis)}</div><div class=\"cizgi\" style=\"background:#dc2626\"></div><div class=\"icerik\"><b>Varış</b><small>${esc(yerAdi(S.rota.nereye))}</small></div></div></div>`;\n  if (otobusHatlari.length) html += `<p class=\"not\">Otobüs bacaklarındaki hatların araçları haritada canlı gösterilir.</p>`;\n  return html;\n}\n\n// ---------- Rota ağı: otobüs (tüm İETT) + raylı + Marmaray + vapur ----------\n// Ağ verileri ayrı yüklenir; hepsi gelene kadar eldekiyle hesap yapılır.\nconst AG = { temel: null, otobus: null, vapur: null, kurulma: 0, saatDilimi: null, indirme: null };\nfunction agKur() {\n  const s = new Date(), dilim = Math.floor((s.getHours() * 60 + s.getMinutes()) / 30);\n  S.ag = Plan.kur({ ...(AG.temel || {}), otobus: AG.otobus, vapur: AG.vapur || [] });\n  AG.kurulma = Date.now(); AG.saatDilimi = dilim;\n  return S.ag;\n}\nlet agYukleniyor = null;\nfunction agHazirla() {\n  if (agYukleniyor) return agYukleniyor.then(() => {\n    // Saat dilimi değiştiyse (gece/yoğun saat hızları, sefer aralıkları) ağı yeniden kur\n    const s = new Date(); if (Math.floor((s.getHours() * 60 + s.getMinutes()) / 30) !== AG.saatDilimi) agKur();\n    return S.ag;\n  });\n  agYukleniyor = (async () => {\n    AG.temel = await API.ag.temel();\n    agKur();\n    API.vapur.tumu().then((v) => { AG.vapur = v; S.agVapur = true; agKur(); if (S.rota.sonuclar && sayfa().tur === \"rota\") rotaBul(true); }).catch(() => {});\n    AG.indirme = { bitti: 0, toplam: 0 };\n    API.ag.otobus((bitti, toplam) => { AG.indirme = { bitti, toplam }; if (sayfa().tur === \"rota\") panelYenile(); })\n      .then((ob) => { AG.otobus = ob; AG.indirme = null; agKur(); if (sayfa().tur === \"rota\") { if (S.rota.sonuclar) rotaBul(true); else panelYenile(); } })\n      .catch(() => { AG.indirme = { hata: true }; });\n    return S.ag;\n  })().catch((e) => { agYukleniyor = null; throw e; });\n  return agYukleniyor;\n}\n// Transitous sonucu -> ortak biçim\nfunction trDonustur(it) {\n  const tur = { BUS: \"otobus\", TRAM: \"tram\", SUBWAY: \"metro\", METRO: \"metro\", FERRY: \"vapur\", WALK: \"yuru\", COACH: \"otobus\" };\n  const bacaklar = it.legs.map((l) => {\n    const t = tur[l.mode] || \"otobus\";\n    let yol = null; try { yol = l.legGeometry ? polylineCoz(l.legGeometry.points, l.legGeometry.precision || 7) : null; } catch {}\n    if (!yol || yol.length < 2) yol = [[l.from.lat, l.from.lon], [l.to.lat, l.to.lon]];\n    const m = l.distance || yol.reduce((a, p, i) => i ? a + Core.mesafe({ lat: yol[i - 1][0], lon: yol[i - 1][1] }, { lat: p[0], lon: p[1] }) : 0, 0);\n    const mb = t === \"otobus\" && /^34[A-Z]{0,2}$/.test(l.routeShortName || \"\");\n    return { tur: mb ? \"mb\" : t, hat: l.routeShortName || \"\", renk: mb ? \"#c2410c\" : t === \"otobus\" ? renkKod(l.routeShortName || \"\") : \"#444\", headsign: l.headsign, from: { ad: bas(l.from.name), lat: l.from.lat, lon: l.from.lon }, to: { ad: bas(l.to.name), lat: l.to.lat, lon: l.to.lon },\n      kalkis: isoDk(l.startTime), varis: isoDk(l.endTime), durakSayisi: t === \"yuru\" ? 0 : (l.intermediateStops || []).length + 1, yol, m, kaynak: \"transitous\" };\n  });\n  bacaklar.forEach((b) => { if (b.from.ad === \"Start\" || b.from.ad === \"START\") b.from.ad = \"Başlangıç\"; if (/^end$/i.test(b.to.ad)) b.to.ad = \"Varış\"; });\n  const r = Plan.duzenle({ bacaklar }, bacaklar[0]?.kalkis ?? Zaman.simdi(), null);\n  r.kalkis = Math.min(r.kalkis, bacaklar[0]?.kalkis ?? r.kalkis); r.sure = r.varis - Zaman.simdi();\n  return r;\n}\nlet rotaNo = 0;\nasync function rotaBul(sessiz) {\n  const R = S.rota, no = ++rotaNo;\n  if (!sessiz) { R.sonuclar = null; R.durum = \"Rotalar hesaplanıyor…\"; ciz(); }\n  try {\n    let a = R.nereden, b = R.nereye;\n    if (a.benim) { const k = S.ben || await benimKonum(false); if (!k) throw new Error(\"Konum alınamadı\"); a = { ...k, ad: \"Konumum\" }; }\n    if (b.benim) { const k = S.ben || await benimKonum(false); b = { ...k, ad: \"Konumum\" }; }\n    // Planlama zamanı: şimdi ya da seçilen tarih/saat\n    const taban = R.zaman ? new Date(R.zaman) : new Date();\n    const ileri = !!R.zaman && Math.abs(taban - Date.now()) > 20 * 60e3;\n    const tabanDk = taban.getHours() * 60 + taban.getMinutes() + (taban.getHours() < 4 ? 1440 : 0);\n    PLAN_ZAMAN.gunTipi = Zaman.gunTipi(taban); PLAN_ZAMAN.canli = !ileri;\n    PLAN_ZAMAN.tabanMs = ileri ? taban.getTime() : Date.now();\n    PLAN_ZAMAN.tabanDk = ileri ? tabanDk : Zaman.simdi() + new Date().getSeconds() / 60;\n    let ag = await agHazirla();\n    if (ileri) { ag = Plan.kur({ ...(AG.temel || {}), otobus: AG.otobus, vapur: AG.vapur || [], saat: tabanDk, gun: taban.getDay() }); S.ag = ag; AG.saatDilimi = null; }\n    const simdi = () => ileri ? tabanDk : Zaman.simdi() + new Date().getSeconds() / 60;\n    const t0 = simdi();\n    const nowISO = taban.toISOString();\n    // 1) Transitous (bağımsız ikinci görüş)\n    const trDirekt = API.transitous.plan(a, b, nowISO).then((l) => l.map(trDonustur)).catch(() => []);\n    // 2) Kendi ağımız: alternatifler. Kullanılan hatların planlanan seferleri indirilir,\n    //    seferi bitmiş hatlar elenir, bekleme gerçek kalkışlardan hesaplanır; değişiklik kalmayana kadar tekrarla.\n    let sonuc = [], etiketler = null;\n    for (let tur = 0; tur < 4; tur++) {\n      ({ sonuc, etiketler } = Plan.alternatifler(ag, a, b, t0, { bekleme: seferBekleme }, 7));\n      // Aktarmasız seçenekler: başlangıçtan hedef durağa tek araçla giden hatlar\n      sonuc = Plan.direkler(ag, a, b, t0, { bekleme: seferBekleme }).concat(sonuc);\n      const yeni = [...new Set(sonuc.flatMap((r) => r.bacaklar.filter((x) => x.iett).map((x) => x.hat)))].filter((h) => !SEFER.has(gunTipiPlan() + \"|\" + h));\n      if (!yeni.length) break;\n      R.durum = `Sefer saatleri kontrol ediliyor: ${yeni.join(\", \")}…`; if (!sessiz) ciz();\n      await Promise.all(yeni.map(seferHazirla));\n      if (no !== rotaNo) return;\n    }\n    let adaylar = sonuc.slice();\n    // Otobüs ağı henüz inmediyse: uzak uçlar için Transitous ile istasyona erişim\n    if (!AG.otobus) {\n      const yakinDurak = (p) => Plan.yakinDuraklar(ag, p, 8000, 60);\n      const uzak = (p) => Plan.yurume(yakinDurak(p)[0]?.[1] ?? 1e9) > 10;\n      const adaylar3 = (p, f = () => true) => { const g = new Set(), o = []; for (const [i, m] of yakinDurak(p)) { if (!f(i)) continue; const k = Plan.norm(ag.duraklar[i].ad); if (g.has(k)) continue; g.add(k); o.push([i, m]); if (o.length >= 3) break; } return o; };\n      if (uzak(a)) {\n        const tohumlar = (await Promise.all(adaylar3(a).map(async ([i]) => { try { const en = (await API.transitous.plan(a, ag.duraklar[i], nowISO)).map(trDonustur).sort((x, y) => x.varis - y.varis)[0]; return en ? { durak: i, t: en.varis + 1, bacaklar: en.bacaklar } : null; } catch { return null; } }))).filter(Boolean);\n        if (tohumlar.length) adaylar.push(...Plan.alternatifler(ag, a, b, t0, { tohumlar }, 3).sonuc);\n      }\n      if (uzak(b)) {\n        const ekler = await Promise.all(adaylar3(b, (i) => etiketler.en[i] < Infinity).map(async ([i]) => {\n          try { const zISO = new Date(Date.now() + (etiketler.zaman[i] - t0) * 60000).toISOString(); const en = (await API.transitous.plan(ag.duraklar[i], b, zISO)).map(trDonustur).sort((x, y) => x.varis - y.varis)[0]; return en ? Plan.duzenle({ bacaklar: etiketler.zincir(i).concat(en.bacaklar) }, t0, ag) : null; } catch { return null; }\n        }));\n        adaylar.push(...ekler.filter(Boolean));\n      }\n    }\n    adaylar.push(...await trDirekt);\n    if (no !== rotaNo) return;\n    // 3) Gerçek veriyle yeniden zamanla: canlı otobüs konumu, planlanan sefer saati, vapur tarifesi\n    adaylar = adaylar.filter((r) => r && r.bacaklar.length);\n    const tekil0 = []; const im0 = new Set();\n    // Aday havuzu: aktarmasızlar her zaman, sonra varışa göre\n    for (const r of adaylar.sort((x, y) => (x.aktarma - y.aktarma) * 15 + x.varis - y.varis)) { if (im0.has(r.imza)) continue; im0.add(r.imza); tekil0.push(r); if (tekil0.length >= 12) break; }\n    R.durum = \"Canlı otobüs konumları ve sefer saatleri kontrol ediliyor…\"; if (!sessiz) ciz();\n    await Promise.all(tekil0.map((r) => rotaInceltme(r, simdi()).catch(() => {})));\n    if (no !== rotaNo) return;\n    // Puan: varış + her aktarma 10 dk + uzun yürüyüş cezası (yürüme ve aktarma olabildiğince az)\n    const yuruDk = (r) => Plan.yurume(r.yurumeM);\n    // Evden çıkış: ilk binişten önceki yürüyüşün başı. Aynı varışta daha geç çıkan (kapıdan kapıya kısa) öne geçer\n    const cikis = (r) => { const iA = r.bacaklar.findIndex((x) => x.tur !== \"yuru\"); return iA > 0 ? r.bacaklar[0].kalkis : iA === 0 ? r.bacaklar[0].kalkis : r.kalkis; };\n    const puan = (r) => r.varis + r.aktarma * 12 + (Plan.yurumeMaliyet(yuruDk(r)) - yuruDk(r)) + (r.varis - cikis(r)) * 0.05;\n    let gecerli = tekil0.filter((r) => !r.gecersiz).sort((x, y) => puan(x) - puan(y));\n    // Aynı duraklar arasında aynı şekilde giden farklı hatları birleştir (ör. 18K / 18D)\n    const birlesik = new Map();\n    for (const r of gecerli) {\n      const k = r.bacaklar.filter((b) => b.tur !== \"yuru\").map((b) => `${b.tur}:${b.from?.ad}>${b.to?.ad}`).join(\"|\");\n      const e = birlesik.get(k);\n      if (!e) { birlesik.set(k, r); continue; }\n      r.bacaklar.filter((b) => b.tur !== \"yuru\").forEach((b, i) => { const eb = e.bacaklar.filter((x) => x.tur !== \"yuru\")[i]; if (eb && eb.hat !== b.hat) { eb.ekHat = eb.ekHat || []; if (!eb.ekHat.includes(b.hat)) eb.ekHat.push(b.hat); } });\n    }\n    gecerli = [...birlesik.values()];\n    // Tüm makul seçenekler: en az aktarmalıdan en fazla 2 fazla aktarmalı, sıralı\n    const enAzAktarma = Math.min(...gecerli.map((r) => r.aktarma));\n    gecerli = gecerli.filter((r) => r.aktarma <= enAzAktarma + 2);\n    const tekil = [];\n    for (const r of gecerli) { if (tekil.length && puan(r) > puan(tekil[0]) + 90) continue; tekil.push(r); if (tekil.length >= 8) break; }\n    // O saatte seferi olmayan rotalar da listenin sonunda (gri) gösterilir\n    const gecersizler = tekil0.filter((r) => r.gecersiz).slice(0, 5);\n    R.sonuclar = tekil.concat(gecersizler);\n    const geceMi = !ileri && tekil.length && tekil.every((r) => { const ib = r.bacaklar.find((x) => x.tur !== \"yuru\"); return ib && ib.kalkis - r.kalkis > 45; });\n    R.durum = [geceMi ? \"Şu an bu yolculuk için çalışan sefer yok; aşağıdakiler sabahın ilk seferleriyle.\" : \"\", ileri ? \"Seçilen zaman için planlanan sefer saatleri kullanıldı (canlı konum yok).\" : \"\", !AG.otobus ? \"Otobüs ağı indiriliyor; bitince öneriler otomatik güncellenecek.\" : \"\", !S.agVapur ? \"Vapur tarifeleri yükleniyor.\" : \"\"].filter(Boolean).join(\" \");\n    if ([\"rota\", \"rdetay\"].includes(sayfa().tur)) ciz();\n  } catch (e) { R.durum = \"Rota hesaplanamadı: \" + hataMesaji(e); R.sonuclar = []; ciz(); }\n}\n\n// Planlama zamanı (Rota sekmesindeki \"Ne zaman?\" seçimi)\nvar PLAN_ZAMAN = { gunTipi: null, canli: true, tabanMs: 0, tabanDk: 0 };\nconst gunTipiPlan = () => PLAN_ZAMAN.gunTipi || Zaman.gunTipi();\n// Planlanan seferler: \"gün tipi|hat\" -> {D:[dk], G:[dk]} ilk duraktan kalkış\nconst SEFER = new Map();\nconst seferAl = (hat) => SEFER.get(gunTipiPlan() + \"|\" + hat);\nasync function seferHazirla(hat) {\n  const g = gunTipiPlan(), key = g + \"|\" + hat;\n  if (SEFER.has(key)) return;\n  try {\n    const s = await API.iett.seferler(hat), o = {};\n    for (const y of Object.keys(s || {})) o[y] = (s[y][g] || []).map(Zaman.dk).filter((x) => x != null).sort((x, z) => x - z);\n    SEFER.set(key, o);\n  } catch { SEFER.set(key, undefined); }\n}\n// Dijkstra için: bu desende i. durağa t'den sonraki ilk geliş (dk cinsinden bekleme). null = bugün artık yok\nfunction seferBekleme(p, i, t) {\n  if (!p.iett) return undefined;\n  const key = gunTipiPlan() + \"|\" + p.hat; if (!SEFER.has(key)) return undefined;\n  const o = SEFER.get(key); if (!o) return undefined;\n  const l = o[p.yon]; if (!l || !l.length) return null;\n  let en = null;\n  for (const k of l) { let v = k + p.t[i]; if (v < t - 720) v += 1440; if (v >= t && (en == null || v < en)) en = v; }\n  return en == null ? null : en - t;\n}\n// Bir otobüs hattında, durağa (kod) t anından sonra gelecek ilk araç: önce canlı, sonra planlanan sefer\nasync function otobusGelis(hat, yon, durakKod, t, desenOfset, now) {\n  const adaylar = [];\n  let tarifeVar = false;\n  if (PLAN_ZAMAN.canli) try {\n    const v = await hatHazirla(hat);\n    if (!v.zaman || Date.now() - v.zaman > 25e3) konumIsle(hat, await API.iett.konum(hat));\n    const liste = v.duraklar?.[yon] || [];\n    const i = liste.findIndex((d) => d.kod === durakKod);\n    if (i >= 0) for (const b of v.otobusler || []) {\n      if (b.yon !== yon) continue;\n      const a = S.arac.get(hat + \"/\" + b.kapino);\n      const p = a ? { ...b, lat: a.gor.lat, lon: a.gor.lon } : b;\n      const e = Core.varisTahmini(liste, p, i, aracHizi(hat, b.kapino));\n      if (e) adaylar.push({ dk: now + e.dakika, kaynak: \"canlı\", kapino: b.kapino, durak: e.durakSayisi });\n    }\n  } catch {}\n  try {\n    const sf = await API.iett.seferler(hat);\n    const l = sf?.[yon]?.[gunTipiPlan()] || [];\n    if (l.length) tarifeVar = true;\n    for (const s of l) {\n      const k = Zaman.dk(s); if (k == null) continue;\n      // Henüz ilk duraktan kalkmamış seferler (kalkmış olanlar zaten canlı listede)\n      let kk = k; if (kk + desenOfset < now - 720) kk += 1440;   // gece yarısından sonra: sabah seferleri\n      if (kk < now - 1 && adaylar.some((x) => x.kaynak === \"canlı\")) continue;\n      adaylar.push({ dk: kk + desenOfset, kaynak: \"tarife\", ilk: s });\n    }\n  } catch {}\n  const uygun = adaylar.filter((x) => x.dk >= t - 0.5).sort((x, y) => x.dk - y.dk);\n  if (uygun.length) return uygun[0];\n  if (tarifeVar || adaylar.length) return null;         // bu hat bugün artık gelmiyor\n  return { dk: t + Plan.otobusAralik(t) / 2, kaynak: \"tahmini\" };\n}\n// Varış aynı kalacaksa en geç çık: ilk aracı, aktarmaya yetişen en geç sefere kaydır (aktarmada bekleme olmasın)\nfunction geriKaydir(r) {\n  const l = r.bacaklar, iA = l.findIndex((x) => x.tur !== \"yuru\"); if (iA < 0) return;\n  const b0 = l[iA], iB = l.findIndex((x, k) => k > iA && x.tur !== \"yuru\"); if (iB < 0) return;\n  const b1 = l[iB];\n  const aradaYuru = l.slice(iA + 1, iB).reduce((t, x) => t + (x.varis - x.kalkis), 0);\n  const bosluk = b1.kalkis - (b0.varis + aradaYuru);\n  if (bosluk < 8 || !b0.iett) return;\n  const o = seferAl(b0.hat), p = S.ag?.desenler?.[b0.desen]; if (!o || !p) return;\n  const sure = b0.varis - b0.kalkis;\n  let en = null;\n  for (const k of o[b0.yon] || []) {\n    let v = k + p.t[b0.i]; if (v < b0.kalkis - 720) v += 1440;\n    if (v >= b0.kalkis && v + sure + aradaYuru <= b1.kalkis - 1 && (en == null || v > en)) en = v;\n  }\n  if (en == null || en - b0.kalkis < 3) return;\n  const fark = en - b0.kalkis;\n  b0.kalkis = en; b0.varis += fark; b0.kaynak = \"tarife\"; b0.canli = \"tarife \" + saat(en);\n  for (let k = 0; k < iA; k++) { l[k].kalkis += fark; l[k].varis += fark; }      // evden daha geç çık\n  for (let k = iA + 1; k < iB; k++) { l[k].kalkis += fark; l[k].varis += fark; }\n  b1.bekleme = Math.max(0, b1.kalkis - (b0.varis + aradaYuru));\n  b0.bekleme = 0;\n  const ilk = l.find((x) => x.tur !== \"yuru\");\n  r.canli = `${ilk.hat} · ${ilk.canli}`;\n}\nasync function rotaInceltme(r, now) {\n  // Başta/sonda 40 m'den kısa yürüme anlamsız (durağın kendisi seçilmiş): kaldır\n  r.bacaklar = r.bacaklar.filter((b, i, l) => !(b.tur === \"yuru\" && (b.m || 0) < 40 && (i === 0 || i === l.length - 1) && l.length > 1));\n  let t = now;\n  for (const b of r.bacaklar) if ((b.tur === \"otobus\" || b.tur === \"mb\") && !b.renk) b.renk = b.tur === \"mb\" ? \"#c2410c\" : renkKod(b.hat);\n  r.kalkis = now;\n  for (const b of r.bacaklar) {\n    const sure = b.varis - b.kalkis; // kalkis = biniş anı (bekleme hariç)\n    if (b.tur === \"yuru\") { b.kalkis = t; t += sure; b.varis = t; continue; }\n    if (b.iett && b.durakKodlari) {\n      const p = S.ag.desenler[b.desen];\n      const g = await otobusGelis(b.hat, b.yon, b.durakKodlari[0], t, p.t[b.i], now);\n      if (!g) { r.gecersiz = `${b.hat} bugün artık sefer yapmıyor`; return r; }\n      b.bekleme = Math.max(0, g.dk - t); b.kalkis = g.dk; b.varis = g.dk + sure; t = b.varis;\n      b.kaynak = g.kaynak;\n      b.canli = g.kaynak === \"canlı\" ? `${g.kapino} ~${Math.max(0, Math.round(g.dk - now))} dk` : g.kaynak === \"tarife\" ? `tarife ${saat(g.dk)}` : \"tahmini\";\n      continue;\n    }\n    if (b.kaynak === \"transitous\") {\n      // Transitous tarifeli bacak: yetişilemiyorsa ele\n      if (b.kalkis < t - 1) { r.gecersiz = \"aktarmaya yetişilemiyor\"; return r; }\n      b.bekleme = b.kalkis - t; t = b.varis; continue;\n    }\n    if (b.tur === \"vapur\") { if (b.kalkis < t - 0.5) { r.gecersiz = \"vapura yetişilemiyor\"; return r; } b.bekleme = b.kalkis - t; t = b.varis; continue; }\n    // Raylı: ilk raylı binişte gerçek tarife, diğerlerinde ortalama bekleme\n    let bekle = b.bekleme ?? 3;\n    if (b.from?.istId && !r._rayliBakildi && PLAN_ZAMAN.canli) {\n      r._rayliBakildi = true;\n      try {\n        const yonler = await API.metro.yonler(b.from.hatId), hedef = Plan.norm(b.yonAd || \"\");\n        const y = yonler.find((x) => { const s = Plan.norm(x.ad.split(\"->\").pop()); return s.startsWith(hedef.slice(0, 5)) || hedef.startsWith(s.slice(0, 5)); });\n        if (y) { const tt = await API.metro.saatler(b.from.istId, b.from.hatId, y.id); const u = tt.saatler.map(Zaman.dk).find((x) => x != null && x >= t); if (u != null) { bekle = u - t; b.canli = \"tarife \" + saat(u); b.kaynak = \"tarife\"; } }\n      } catch {}\n    }\n    b.bekleme = bekle; b.kalkis = t + bekle; b.varis = b.kalkis + sure; t = b.varis;\n  }\n  r.varis = t; r.sure = t - now;\n  geriKaydir(r);\n  const ilk = r.bacaklar.find((x) => x.tur !== \"yuru\");\n  r.canli = ilk?.canli ? (ilk.kaynak === \"canlı\" ? `${ilk.hat} (${ilk.canli.split(\" \")[0]}) durağa ${ilk.canli.split(\" \").slice(1).join(\" \")} sonra gelecek` : `${ilk.hat} · ${ilk.canli}`) : \"\";\n  return r;\n}\nlet yerAramaNo = 0, yerAramaZaman;\nfunction yerAramaYap() {\n  const R = S.rota, q = R.metin.trim(), no = ++yerAramaNo;\n  clearTimeout(yerAramaZaman);\n  if (q.length < 2) { R.oneriler = []; return ciz(); }\n  yerAramaZaman = setTimeout(async () => {\n    const yerel = S.ag ? Plan.yerAra(S.ag, q, 8) : [];\n    R.oneriler = yerel; ciz();\n    try {\n      const uzak = await API.transitous.yerAra(q, S.ben);\n      if (no !== yerAramaNo) return;\n      const gor = new Set(yerel.map((x) => Plan.norm(x.ad)));\n      R.oneriler = yerel.concat(uzak.filter((x) => !gor.has(Plan.norm(x.ad))).slice(0, 8)); ciz();\n    } catch {}\n  }, 300);\n}\nfunction yerSec(y) {\n  const R = S.rota, alan = R.aktif;\n  if (y.harita) { secimBaslat(alan); return; }\n  const durak = [\"durak\", \"metro\", \"marmaray\", \"tram\", \"fun\", \"tf\", \"mb\", \"vapur\"].includes(y.tur) || !!y.durak;\n  R[alan] = y.benim ? { benim: true, ad: \"Konumum\" } : { ad: y.ad, alt: y.alt, lat: y.lat, lon: y.lon, tur: y.tur, durak, kod: y.kod };\n  if (!y.benim && alan === \"nereye\") { R.son = [{ ad: y.ad, alt: y.alt, lat: y.lat, lon: y.lon, tur: y.tur, durak, kod: y.kod }].concat(R.son.filter((x) => !(x.ad === y.ad && x.kod === y.kod))).slice(0, 6); KV.set(\"sonYerler\", R.son); }\n  R.metin = \"\"; R.oneriler = [];\n  R.aktif = !R.nereden ? \"nereden\" : !R.nereye ? \"nereye\" : null;\n  document.activeElement?.blur?.();\n  ciz(true);\n  if (R.nereden && R.nereye) rotaBul();\n}\nlet secimAlani = null;\nfunction haritaSecimTik(e) {\n  const alan = secimAlani; secimBitir();\n  S.rota.aktif = alan;\n  yerSec({ ad: `Seçilen nokta (${e.latlng.lat.toFixed(4)}, ${e.latlng.lng.toFixed(4)})`, alt: \"Haritadan\", lat: e.latlng.lat, lon: e.latlng.lng, tur: \"harita\" });\n}\nfunction secimBaslat(alan) {\n  secimAlani = alan; document.body.classList.add(\"harita-buyuk\"); setTimeout(() => map.invalidateSize(), 300);\n  $(\"#secimBandi\").style.display = \"block\";\n  setTimeout(() => map.once(\"click\", haritaSecimTik), 50);\n}\nfunction secimBitir() {\n  if (!secimAlani && $(\"#secimBandi\").style.display !== \"block\") return;\n  secimAlani = null; $(\"#secimBandi\").style.display = \"none\"; document.body.classList.remove(\"harita-buyuk\"); setTimeout(() => map.invalidateSize(), 300);\n}\n$(\"#secimIptal\").addEventListener(\"click\", (e) => { e.stopPropagation(); map.off(\"click\", haritaSecimTik); secimBitir(); });\n\n// ---------- 3) OTOBÜS ----------\nasync function otobusSayfa(p, ilk) {\n  if (ilk) { onYukle(\"Otobüs ve Metrobüs\", false); aktifHatlarAyarla([]); }\n  const hatlar = await API.iett.hatlar();\n  const q = (S.arama || \"\").trim().toLocaleUpperCase(\"tr\");\n  let html = baslikHTML(\"Otobüs ve Metrobüs\", false);\n  html += `<input class=\"ara\" id=\"ara\" placeholder=\"Hat kodu ya da adı: 500T, 34BZ, Kadıköy…\" value=\"${esc(S.arama || \"\")}\" autocomplete=\"off\" autocapitalize=\"characters\">`;\n  const satir = (h) => {\n    const fav = S.favoriler.includes(h.kod), mb = metrobusMu(h);\n    return `<li class=\"tik\" data-hat=\"${esc(h.kod)}\"><span class=\"rozet\" style=\"background:${mb ? \"#c2410c\" : renkKod(h.kod)}\">${mb ? \"🚍\" : \"🚌\"} ${esc(h.kod)}</span><div class=\"ana\">${esc(bas(h.ad))}<small>${mb ? \"Metrobüs · \" : \"\"}${h.km ? h.km.toFixed(1) + \" km · \" : \"\"}${h.dk ? Math.round(h.dk) + \" dk\" : \"\"}</small></div><button class=\"yildiz\" data-fav=\"${esc(h.kod)}\">${fav ? \"★\" : \"☆\"}</button></li>`;\n  };\n  if (q) {\n    const bulunan = hatlar.filter((h) => h.kod.startsWith(q)).concat(hatlar.filter((h) => !h.kod.startsWith(q) && (h.kod.includes(q) || h.ad.toLocaleUpperCase(\"tr\").includes(q)))).slice(0, 40);\n    html += `<h2>Sonuçlar</h2><div class=\"kart\"><ul class=\"liste\">${bulunan.map(satir).join(\"\") || '<li><span class=\"not\">Eşleşen hat yok</span></li>'}</ul></div>`;\n  } else {\n    const favs = S.favoriler.map((k) => hatlar.find((h) => h.kod === k) || { kod: k, ad: \"\" });\n    html += `<h2>Favoriler</h2><div class=\"kart\"><ul class=\"liste\">${favs.map(satir).join(\"\") || '<li><span class=\"not\">Hat arayıp ☆ ile ekleyin</span></li>'}</ul></div>`;\n    const mb = hatlar.filter(metrobusMu).sort((a, b) => a.kod.localeCompare(b.kod, \"tr\"));\n    html += `<h2>Metrobüs hatları</h2><div class=\"kart\"><ul class=\"liste\">${mb.map(satir).join(\"\")}</ul></div><p class=\"not\">${hatlar.length} İETT hattı arasında arayabilirsiniz.</p>`;\n  }\n  return html;\n}\nasync function hatSayfa(p, ilk, no) {\n  const hat = p.hat;\n  if (ilk) { onYukle(esc(hat), true); aktifHatlarAyarla([hat]); }\n  const v = await hatHazirla(hat);\n  if (!v.otobusler || ilk) konumIsle(hat, await API.iett.konum(hat));\n  if (no !== cizimNo) return null;\n  if (!v.seferler) { try { v.seferler = await API.iett.seferler(hat); } catch { v.seferler = {}; } }\n  const yonler = Object.keys(v.duraklar).sort();\n  if (!yonler.includes(p.yon)) p.yon = yonler[0];\n  if (!p.gun) p.gun = Zaman.gunTipi();\n  const liste = v.duraklar[p.yon] || [], b = v.bilgi || {}, fav = S.favoriler.includes(hat);\n  if (ilk || p.cizilenYon !== p.yon) { katman.clearLayers(); const pts = guzergahCiz(hat, p.yon); if (ilk) sigdir(S.ben ? pts.concat([[S.ben.lat, S.ben.lon]]) : pts); p.cizilenYon = p.yon; }\n  aracCiz(hat);\n  let html = baslikHTML(`<span class=\"rozet\" style=\"background:${v.renk}\">${v.mb ? \"🚍\" : \"🚌\"} ${esc(hat)}</span> <span style=\"font-size:15px\">${esc(bas(b.ad || \"\"))}</span>`, true, `<button class=\"yildiz\" data-fav=\"${esc(hat)}\">${fav ? \"★\" : \"☆\"}</button>`);\n  html += `<div class=\"not\">${[b.km ? b.km.toFixed(1) + \" km\" : \"\", b.dk ? \"sefer \" + Math.round(b.dk) + \" dk\" : \"\", b.tarife ? bas(b.tarife) : \"\", (v.otobusler || []).length + \" araç seferde\"].filter(Boolean).join(\" · \")} <span class=\"canli\">CANLI</span></div>`;\n  html += `<div class=\"segment\">${yonler.map((y) => { const l = v.duraklar[y]; return `<button data-yon=\"${y}\" class=\"${y === p.yon ? \"aktif\" : \"\"}\">→ ${esc(bas(l[l.length - 1].ad))}</button>`; }).join(\"\")}</div>`;\n  const h = hedefDurak(hat, p.yon);\n  hedefKatmani.clearLayers(); hedefGor.clear(); hedefAdlar.length = 0;\n  if (h) durakIsaretle(hat, h.d, v.renk);\n  if (h) {\n    const gel = yaklasanOtobusler(hat, p.yon, h.i).slice(0, 4);\n    html += `<div class=\"kart\"><div class=\"alt\">${h.secili ? \"Durağım\" : \"Size en yakın durak\"}: <b style=\"color:var(--yazi)\">${esc(bas(h.d.ad))}</b>${h.metre != null ? \" · \" + metre(h.metre) : \"\"}</div><ul class=\"liste\">` +\n      (gel.length ? gel.map((x) => otobusSatiri(hat, x)).join(\"\") : `<li><span class=\"not\">Bu yönde yaklaşan otobüs yok</span></li>`) + `</ul></div>`;\n  } else html += `<div class=\"not\" style=\"margin-bottom:8px\">Durağınızı seçmek için listeden ya da haritadan bir durağa dokunun.</div>`;\n  const gunler = v.seferler?.[p.yon] || {}, saatler = gunler[p.gun] || [], bugun = p.gun === Zaman.gunTipi(), simdi = Zaman.simdi();\n  const sonraki = bugun ? saatler.find((s) => Zaman.dk(s) >= simdi) : null;\n  html += `<h2>Sefer saatleri · ${esc(bas(liste[0]?.ad || \"\"))} kalkış</h2>`;\n  html += `<div class=\"segment\">${[\"I\", \"C\", \"P\"].map((g) => `<button data-gun=\"${g}\" class=\"${g === p.gun ? \"aktif\" : \"\"}\">${GUN_ADI[g]}${g === Zaman.gunTipi() ? \" •\" : \"\"}</button>`).join(\"\")}</div>`;\n  html += `<div class=\"kart\">` + (saatler.length ? (sonraki ? `<div class=\"alt\">Sıradaki kalkış <b style=\"color:var(--yazi)\">${esc(sonraki)}</b> · ${Zaman.kalanYazi(Zaman.kalan(sonraki))} sonra</div>` : \"\") +\n      `<div class=\"saatler\">${saatler.map((s) => `<span class=\"${bugun && Zaman.dk(s) < simdi ? \"gecti\" : \"\"} ${s === sonraki ? \"sonraki\" : \"\"}\">${esc(s)}</span>`).join(\"\")}</div>` : `<div class=\"bos\">Bu gün için planlanmış sefer bilgisi yok.</div>`) + `</div>`;\n  // Her aracın tam yeri: bir durakta mı, yoksa iki durak arasında mı?\n  const durakta = {}, arada = {}, hiz0 = v.hiz || 15;\n  for (const a of S.arac.values()) {\n    if (a.hat !== hat || a.yon !== p.yon) continue;\n    const yer = aracYeri(liste, a); if (!yer) continue;\n    const t = h && h.i >= yer.sonraki ? Core.varisTahmini(liste, a.gor, h.i, aracHizi(hat, a.kapino) || hiz0) : null;\n    const kayit = { a, yer, t };\n    (yer.durakta != null ? (durakta[yer.durakta] ||= []) : (arada[yer.sonraki] ||= [])).push(kayit);\n  }\n  const ikon = v.mb ? \"🚍\" : \"🚌\";\n  const kalan = (k) => k.t ? ` · <b>${k.t.dakika <= 1 ? \"geliyor\" : \"durağınıza ~\" + k.t.dakika + \" dk\"}</b>` : \"\";\n  let lis = \"\";\n  liste.forEach((d, i) => {\n    for (const k of (arada[i] || []).sort((x, y) => y.yer.oran - x.yer.oran))\n      lis += `<li class=\"arac-satir\" data-arac=\"${esc(k.a.kapino)}\"><span class=\"arac-cip\" style=\"background:${v.renk}\">${ikon} ${esc(k.a.kapino)}</span> <span class=\"not\">${esc(bas(d.ad))} durağına ${metre(k.yer.metre)}${kalan(k)}</span></li>`;\n    const bu = durakta[i] || [];\n    lis += `<li data-durak=\"${i}\" class=\"${h && h.i === i ? \"benim\" : \"\"}${bu.length ? \" dolu\" : \"\"}\">${esc(bas(d.ad))}${h && h.i === i ? \" 📍\" : \"\"}` +\n      bu.map((k) => `<span class=\"arac-cip\" data-arac=\"${esc(k.a.kapino)}\" style=\"background:${v.renk}\">${ikon} ${esc(k.a.kapino)} durakta</span>`).join(\"\") +\n      (bu.length && bu[0].t ? `<div class=\"not\">${kalan(bu[0]).replace(\" · \", \"\")}</div>` : \"\") + `</li>`;\n  });\n  const toplam = Object.values(durakta).flat().length + Object.values(arada).flat().length;\n  html += `<h2>Duraklar (${liste.length}) · ${toplam} araç bu yönde</h2><div class=\"kart\"><ol class=\"duraklar\" style=\"--hr:${v.renk}\">${lis}</ol></div>`;\n  return html + `<p class=\"not\">Otobüsler bulundukları yerde, durakların arasında gösterilir. Otobüse dokununca bilgileri açılır; durağa dokunup “Durağım yap” diyebilirsiniz.</p>`;\n}\n\n// ---------- 4) RAYLI ----------\nasync function rayliSayfa(p, ilk) {\n  if (ilk) { onYukle(\"Raylı sistem\", false); aktifHatlarAyarla([]); }\n  const [hatlar, durum] = await Promise.all([API.metro.hatlar(), API.metro.durum()]);\n  const grup = (h) => ({ tram: \"Tramvay\", tf: \"Teleferik\", fun: \"Füniküler\", metro: \"Metro\" })[Plan.turOf(h.ad)];\n  let html = baslikHTML(\"Metro · Tramvay · Füniküler\", false);\n  if (durum.length) html += durum.map((d) => `<div class=\"duyuru\"><b>${esc(d.hat)}</b> · ${esc(d.metin)}</div>`).join(\"\");\n  for (const g of [\"Metro\", \"Tramvay\", \"Füniküler\", \"Teleferik\"]) {\n    const l = hatlar.filter((h) => grup(h) === g); if (!l.length) continue;\n    html += `<h2>${g}</h2><div class=\"kart\"><ul class=\"liste\">${l.map((h) => `<li class=\"tik\" data-rhat=\"${h.id}\"><span class=\"rozet\" style=\"background:${h.renk}\">${esc(h.ad)}</span><div class=\"ana\">${esc(h.uzun.replace(/\\s*(Metro|Tramvay|Füniküler|Teleferik)?\\s*Hattı$/i, \"\"))}<small>${h.ilk && h.son ? `İlk ${esc(h.ilk)} · son ${esc(h.son)}` : \"\"}${durum.some((d) => d.hatId === h.id) ? \" · ⚠️ duyuru var\" : \"\"}</small></div><span class=\"not\">›</span></li>`).join(\"\")}</ul></div>`;\n  }\n  return html + `<p class=\"not\">Hat sayfasında trenlerin tarifeye göre tahmini konumları haritada gösterilir. Marmaray TCDD tarafından işletildiği için burada yok.</p>`;\n}\nasync function rayliHatSayfa(p, ilk) {\n  const hatlar = await API.metro.hatlar(), hat = hatlar.find((h) => h.id === p.id);\n  if (ilk) { onYukle(esc(hat?.ad || \"\"), true); aktifHatlarAyarla([]); }\n  const ist = (await API.metro.istasyonlar()).filter((s) => s.hatId === p.id).sort((a, b) => a.sira - b.sira);\n  const durum = (await API.metro.durum()).filter((d) => d.hatId === p.id);\n  if (ilk) {\n    const ll = ist.map((s) => [s.lat, s.lon]);\n    L.polyline(ll, { color: hat.renk, weight: 4, opacity: .85, interactive: false }).addTo(katman);\n    ist.forEach((s) => L.circleMarker([s.lat, s.lon], { radius: 4, color: hat.renk, weight: 2, fillColor: \"#fff\", fillOpacity: 1 }).bindTooltip(esc(s.ad)).on(\"click\", () => git({ tur: \"ist\", id: s.id })).addTo(ist.length > 12 ? durakKatmani : katman));\n    zoomAyarla();\n    sigdir(ll);\n    rayliTahminiHazirla(hat, ist).then((sf) => { if (sayfa() === p) { tahminiKaynak = { seferler: sf }; p.trenSayisi = sf.filter((x) => { const s = Zaman.simdi(); return s >= x.t[0] && s <= x.t[x.t.length - 1]; }).length; tahminiCiz(); panelYenile(); } }).catch(() => {});\n  }\n  let yakinId = null;\n  if (S.ben && ist.length) yakinId = ist[Core.enYakinIndex(ist, S.ben).index].id;\n  let html = baslikHTML(`<span class=\"rozet\" style=\"background:${hat.renk}\">${esc(hat.ad)}</span> <span style=\"font-size:15px\">${esc(hat.uzun)}</span>`, true);\n  html += durum.map((d) => `<div class=\"duyuru\">${esc(d.metin)}</div>`).join(\"\");\n  html += `<div class=\"not\">İlk sefer ${esc(hat.ilk || \"–\")} · son sefer ${esc(hat.son || \"–\")}${p.trenSayisi != null ? ` · haritada ${p.trenSayisi} tren (tahmini konum)` : \"\"}</div>`;\n  html += `<h2>İstasyonlar (${ist.length}) · dokunun, sıradaki seferleri görün</h2><div class=\"kart\"><ol class=\"duraklar\" style=\"--hr:${hat.renk}\">${ist.map((s) => `<li data-ist=\"${s.id}\" class=\"${s.id === yakinId ? \"benim\" : \"\"}\">${esc(s.ad)}${s.id === yakinId ? ` <span class=\"etiket\">size en yakın · ${metre(Core.mesafe(S.ben, s))}</span>` : \"\"}</li>`).join(\"\")}</ol></div>`;\n  return html;\n}\nasync function istasyonSayfa(p, ilk, no) {\n  const [hatlar, tum] = await Promise.all([API.metro.hatlar(), API.metro.istasyonlar()]);\n  const s = tum.find((x) => x.id === p.id), hat = hatlar.find((h) => h.id === s.hatId);\n  if (ilk) {\n    onYukle(esc(s.ad), true); aktifHatlarAyarla([]); map.setView([s.lat, s.lon], 15);\n    L.circleMarker([s.lat, s.lon], { radius: 9, color: hat.renk, weight: 3, fillColor: hat.renk, fillOpacity: .9 }).addTo(katman);\n    const ist = tum.filter((x) => x.hatId === s.hatId).sort((a, b) => a.sira - b.sira);\n    L.polyline(ist.map((x) => [x.lat, x.lon]), { color: hat.renk, weight: 4, opacity: .6, interactive: false }).addTo(katman);\n    rayliTahminiHazirla(hat, ist).then((sf) => { if (sayfa() === p) { tahminiKaynak = { seferler: sf }; tahminiCiz(); } }).catch(() => {});\n  }\n  const yonler = await API.metro.yonler(s.hatId);\n  const ss = await Promise.all(yonler.map((y) => API.metro.saatler(s.id, s.hatId, y.id).then((t) => ({ y, t }), (e) => ({ y, e }))));\n  if (no !== cizimNo) return null;\n  const aktarma = tum.filter((x) => x.hatId !== s.hatId && Core.mesafe(x, s) < 250);\n  let html = baslikHTML(`<span class=\"rozet\" style=\"background:${hat.renk}\">${esc(hat.ad)}</span> ${esc(s.ad)}`, true);\n  if (S.ben) html += `<div class=\"not\">Size ${metre(Core.mesafe(S.ben, s))} uzakta</div>`;\n  for (const { y, t, e } of ss) {\n    html += `<h2>→ ${esc(t?.hedef || y.ad.split(\"->\").pop())}</h2><div class=\"kart\">`;\n    if (e) html += `<div class=\"bos hata\">${esc(hataMesaji(e))}</div>`;\n    else if (!t.saatler.length) html += `<div class=\"bos\">Bu yönde yakın zamanda sefer yok (hat başı/sonu ya da servis dışı).</div>`;\n    else html += `<div class=\"alt\">Sıradaki tren <b style=\"color:var(--yazi)\">${esc(t.saatler[0])}</b> · ${Zaman.kalanYazi(Zaman.kalan(t.saatler[0]))} sonra</div><div class=\"saatler\">${t.saatler.map((x, i) => `<span class=\"${i === 0 ? \"sonraki\" : \"\"}\">${esc(x)}</span>`).join(\"\")}</div>`;\n    html += `</div>`;\n  }\n  if (aktarma.length) html += `<h2>Aktarma</h2><div class=\"kart\"><ul class=\"liste\">${aktarma.map((x) => { const h = hatlar.find((q) => q.id === x.hatId); return `<li class=\"tik\" data-ist=\"${x.id}\"><span class=\"rozet\" style=\"background:${h?.renk || \"#333\"}\">${esc(x.hat)}</span><div class=\"ana\">${esc(x.ad)}</div><span class=\"not\">›</span></li>`; }).join(\"\")}</ul></div>`;\n  return html + `<p class=\"not\">Saatler Metro İstanbul tarifesindendir. Haritadaki trenler tarifeye göre tahmini konumdur.</p>`;\n}\n\n// ---------- 5) VAPUR ----------\nasync function vapurSayfa(p, ilk) {\n  if (ilk) { onYukle(\"Vapur\", false); aktifHatlarAyarla([]); }\n  const hatlar = await API.vapur.hatlar();\n  let html = baslikHTML(\"Vapur · Şehir Hatları\", false);\n  for (const g of [\"İstanbul İçi\", \"Boğaz\", \"Adalar\", \"Diğer\"]) {\n    const l = hatlar.filter((h) => h.grup === g); if (!l.length) continue;\n    html += `<h2>${g}</h2><div class=\"kart\"><ul class=\"liste\">${l.map((h) => `<li class=\"tik\" data-vhat=\"${esc(h.url)}\"><span style=\"font-size:20px\">⛴</span><div class=\"ana\">${esc(bas(h.ad))}</div><span class=\"not\">›</span></li>`).join(\"\")}</ul></div>`;\n  }\n  return html + `<p class=\"not\">Tarifeler sehirhatlari.istanbul sitesinden okunur. Hat sayfasında vapurların tarifeye göre tahmini konumu gösterilir.</p>`;\n}\nasync function vapurHatSayfa(p, ilk) {\n  const hatlar = await API.vapur.hatlar(), h = hatlar.find((x) => x.url === p.url) || { ad: \"\", url: p.url };\n  if (ilk) { onYukle(esc(bas(h.ad)), true); aktifHatlarAyarla([]); }\n  const tablolar = await API.vapur.tarife(p.url), simdi = Zaman.simdi();\n  if (ilk) {\n    API.iskeleler().then((isk) => {\n      if (sayfa() !== p) return;\n      const ag = Plan.kur({ iskeleler: isk, vapur: [{ ad: h.ad, tablolar }], marmaray: false });\n      const pts = ag.duraklar.map((d) => [d.lat, d.lon]);\n      ag.duraklar.forEach((d) => L.circleMarker([d.lat, d.lon], { radius: 6, color: \"#0e7490\", weight: 3, fillColor: \"#fff\", fillOpacity: 1 }).bindTooltip(esc(d.ad)).addTo(katman));\n      if (pts.length) sigdir(pts, 14);\n      tahminiKaynak = { seferler: ag.seferler.map((s) => ({ key: \"v\" + s.id, hat: \"Vapur\", renk: \"#0e7490\", tur: \"vapur\", hedef: ag.duraklar[s.d[s.d.length - 1]].ad, d: s.d.map((i) => ag.duraklar[i]), t: s.t })) };\n      tahminiCiz();\n    }).catch(() => {});\n  }\n  let html = baslikHTML(`⛴ <span style=\"font-size:16px\">${esc(bas(h.ad))}</span>`, true, `<button class=\"btn kucuk\" data-ac=\"${esc(p.url)}\">Resmi sayfa</button>`);\n  if (!tablolar.length) html += `<div class=\"kart\"><div class=\"bos\">Bu hat için tarife tablosu bulunamadı.</div></div>`;\n  const sirali = tablolar.map((t, i) => ({ t, i, uygun: Plan.tabloGunUygun(t.not) })).sort((a, b) => (b.uygun - a.uygun) || (a.i - b.i));\n  for (const { t, uygun } of sirali) {\n    const yok = Plan.bugunYapilmayanIsaretler(t.not);\n    const satirZaman = (r) => { for (const c of r) { const v = Zaman.dk(c); if (v != null) return v; } return null; };\n    let sonrakiBulundu = false, gizli = 0;\n    const govde = t.satirlar.map((r) => {\n      const z = satirZaman(r), iptal = Plan.satirYok(r, yok);\n      let cls = \"\";\n      if (uygun && z != null && z < simdi) cls = \"gecti\"; else if (iptal) cls = \"yok\"; else if (uygun && !sonrakiBulundu && z != null) { cls = \"sonraki\"; sonrakiBulundu = true; }\n      if (cls === \"gecti\" && !p.tumu) { gizli++; return \"\"; }\n      return `<tr class=\"${cls}\">${r.map((c) => `<td>${esc(c)}</td>`).join(\"\")}</tr>`;\n    }).join(\"\");\n    const ilkSonraki = uygun ? t.satirlar.find((r) => !Plan.satirYok(r, yok) && (satirZaman(r) ?? -1) >= simdi) : null;\n    html += `<h2>${esc(t.baslik)}${uygun ? \"\" : \" · bugün değil\"}</h2><div class=\"kart\">`;\n    if (t.not) html += `<div class=\"alt\">${esc(t.not)}</div>`;\n    if (ilkSonraki) { const z = ilkSonraki.find((c) => Zaman.dk(c) != null); html += `<div class=\"alt\">Sıradaki sefer <b style=\"color:var(--yazi)\">${esc(z)}</b> · ${Zaman.kalanYazi(Zaman.dk(z) - simdi)} sonra</div>`; }\n    if (uygun && !sonrakiBulundu && !gizli) html += `<div class=\"alt\">Bugün için kalan sefer yok.</div>`;\n    html += `<div style=\"overflow-x:auto\"><table class=\"tarife\">${t.basliklar.map((r) => `<tr>${r.map((c) => `<th>${esc(c)}</th>`).join(\"\")}</tr>`).join(\"\")}${govde}</table></div>`;\n    if (gizli) html += `<div class=\"alt\"><button class=\"btn kucuk\" data-tumu>Geçmiş ${gizli} seferi göster</button></div>`;\n    else if (p.tumu && uygun) html += `<div class=\"alt\"><button class=\"btn kucuk\" data-tumu>Geçmiş seferleri gizle</button></div>`;\n    html += `</div>`;\n  }\n  return html + `<p class=\"not\">Resmi tatillerde tarife değişebilir. Üstü çizili seferler bugün yapılmıyor. Haritadaki vapurlar tarifeye göre tahmini konumdur.</p>`;\n}\n\n// ---------- olaylar ----------\ndocument.addEventListener(\"click\", async (e) => {\n  const t = e.target.closest(\"[data-sekme],[data-geri],[data-hat],[data-fav],[data-yon],[data-gun],[data-durak],[data-odakla],[data-rhat],[data-ist],[data-vhat],[data-ac],[data-yenile],[data-tumu],[data-oneri],[data-temizle],[data-degistir],[data-rotabul],[data-rota],[data-zaman],[data-boy]\");\n  if (!t) return;\n  const d = t.dataset;\n  if (d.sekme) { S.sekme = d.sekme; S.yigin = []; document.querySelectorAll(\"#sekmeler button\").forEach((b) => b.classList.toggle(\"aktif\", b === t)); return ciz(true); }\n  if (\"geri\" in d) return geri();\n  if (\"yenile\" in d) return ciz(true);\n  if (d.fav) { e.stopPropagation(); const i = S.favoriler.indexOf(d.fav); if (i >= 0) S.favoriler.splice(i, 1); else S.favoriler.push(d.fav); favKaydet(); t.textContent = i >= 0 ? \"☆\" : \"★\"; return; }\n  if (d.hat) return git({ tur: \"hat\", hat: d.hat });\n  if (d.yon) { sayfa().yon = d.yon; return ciz(); }\n  if (d.gun) { sayfa().gun = d.gun; return ciz(); }\n  if (d.durak) { const p = sayfa(), dd = S.hatVeri[p.hat]?.duraklar?.[p.yon]?.[+d.durak]; if (!dd) return; map.setView([dd.lat, dd.lon], 16); L.popup().setLatLng([dd.lat, dd.lon]).setContent(durakPopup(p.hat, dd)).openOn(map); return; }\n  if (d.odakla) { const a = S.arac.get(d.odakla); if (a?.isaret) { map.setView(a.isaret.getLatLng(), Math.max(map.getZoom(), 15)); a.isaret.openPopup(); } return; }\n  if (d.rhat) return git({ tur: \"rhat\", id: +d.rhat });\n  if (d.ist) return git({ tur: \"ist\", id: +d.ist });\n  if (d.vhat) return git({ tur: \"vhat\", url: d.vhat });\n  if (d.ac) { Native.call(\"open\", { url: d.ac }).catch(() => {}); return; }\n  if (\"tumu\" in d) { const p = sayfa(); p.tumu = !p.tumu; return ciz(); }\n  if (d.oneri != null) { const y = S.rota.gosterilen?.[+d.oneri]; if (y) yerSec(y); return; }\n  if (d.temizle) { S.rota[d.temizle] = null; S.rota.aktif = d.temizle; S.rota.metin = \"\"; S.rota.sonuclar = null; return ciz(); }\n  if (\"degistir\" in d) { const R = S.rota; [R.nereden, R.nereye] = [R.nereye, R.nereden]; R.aktif = !R.nereden ? \"nereden\" : !R.nereye ? \"nereye\" : null; R.sonuclar = null; ciz(true); if (R.nereden && R.nereye) rotaBul(); return; }\n  if (\"rotabul\" in d) return rotaBul();\n  if (d.zaman) {\n    const R = S.rota;\n    if (d.zaman === \"simdi\") { R.zaman = null; ciz(); if (R.nereden && R.nereye) rotaBul(); return; }\n    if (!R.zaman) { const z = new Date(Date.now() + 60 * 60e3); z.setMinutes(Math.ceil(z.getMinutes() / 15) * 15, 0, 0); const p2 = (n) => String(n).padStart(2, \"0\"); R.zaman = `${z.getFullYear()}-${p2(z.getMonth() + 1)}-${p2(z.getDate())}T${p2(z.getHours())}:${p2(z.getMinutes())}`; }\n    await ciz(); const el = $(\"#zamanSec\"); if (el) { el.focus(); try { el.showPicker?.(); } catch {} }\n    return;\n  }\n  if (d.rota != null) return git({ tur: \"rdetay\", i: +d.rota });\n});\ndocument.addEventListener(\"change\", (e) => {\n  if (e.target.id !== \"zamanSec\") return;\n  const R = S.rota; R.zaman = e.target.value || null;\n  if (R.nereden && R.nereye) rotaBul(); else ciz();\n});\ndocument.addEventListener(\"focusin\", (e) => {\n  const alan = e.target.dataset?.alan; if (!alan) return;\n  const R = S.rota; if (R.aktif === alan) return;\n  R.aktif = alan; R.metin = \"\"; R.oneriler = []; ciz();\n});\nlet aramaZaman;\ndocument.addEventListener(\"input\", (e) => {\n  if (e.target.dataset?.alan) { S.rota.metin = e.target.value; yerAramaYap(); return; }\n  if (e.target.id !== \"ara\") return;\n  S.arama = e.target.value; clearTimeout(aramaZaman); aramaZaman = setTimeout(() => ciz(), 250);\n});\n// ---------- panel: 3 konum (tam harita / normal / geniş liste), her sayfada sürüklenebilir ----------\nconst panel = $(\"#panel\");\nfunction panelKonum() { const b = document.body.classList; return b.contains(\"tam\") ? \"tam\" : b.contains(\"genis\") ? \"genis\" : \"normal\"; }\nfunction panelAyarla(k) {\n  document.body.classList.toggle(\"tam\", k === \"tam\");\n  document.body.classList.toggle(\"genis\", k === \"genis\");\n  if (k === \"tam\") panel.scrollTop = 0;\n  setTimeout(() => map.invalidateSize({ pan: false }), 320);\n}\nfunction tamEkran(ac) { panelAyarla(ac ? \"tam\" : \"normal\"); }\n(() => {\n  let y0 = null, x0 = 0, dy = 0, bastan = false, surukle = false, iptal = false, k0 = \"normal\", ust0 = true;\n  panel.addEventListener(\"touchstart\", (e) => {\n    const t = e.touches[0]; y0 = t.clientY; x0 = t.clientX; dy = 0; surukle = false; iptal = false; k0 = panelKonum(); ust0 = panel.scrollTop <= 0;\n    // Tutamak / başlık şeridi (panelin ilk ~56px'i) her yöne sürükler; yazı kutularında sürükleme yok\n    const ust = t.clientY - panel.getBoundingClientRect().top < 56;\n    bastan = !!e.target.closest(\"#tutamak\") || k0 === \"tam\" || (ust && !e.target.closest(\"input,select,textarea,button\"));\n  }, { passive: true });\n  panel.addEventListener(\"touchmove\", (e) => {\n    if (y0 == null || iptal) return;\n    const t = e.touches[0]; dy = t.clientY - y0;\n    if (!surukle && Math.abs(t.clientX - x0) > Math.abs(dy) + 6) { iptal = true; return; } // yatay kaydırma (çipler vb.)\n    const enUst = ust0; // dokunuş başladığında liste en üstteyse\n    // İçerik en üstteyken aşağı çekmek de paneli sürükler; listedeyken yukarı çekmek normal kaydırmadır\n    const izin = surukle || bastan || (dy > 0 && enUst);\n    if (!izin || Math.abs(dy) < 6) return;\n    if (k0 === \"genis\" && dy < 0 && !bastan) return; // en üstte, yukarı: liste kaydırması\n    if (k0 === \"tam\" && dy > 0) return;              // zaten en altta\n    surukle = true; e.preventDefault();\n    panel.classList.add(\"suruk\");\n    const sin = k0 === \"tam\" ? [-window.innerHeight * 0.8, 0] : k0 === \"genis\" ? [0, window.innerHeight * 0.8] : [-window.innerHeight * 0.3, window.innerHeight * 0.5];\n    panel.style.transform = `translateY(${Math.max(sin[0], Math.min(sin[1], dy))}px)`;\n  }, { passive: false });\n  const bitir = () => {\n    panel.classList.remove(\"suruk\"); panel.style.transform = \"\";\n    if (surukle) {\n      const H = window.innerHeight; let k = k0;\n      if (k0 === \"normal\") k = dy > 70 ? \"tam\" : dy < -60 ? \"genis\" : \"normal\";\n      else if (k0 === \"genis\") k = dy > H * 0.45 ? \"tam\" : dy > 60 ? \"normal\" : \"genis\";\n      else if (k0 === \"tam\") k = dy < -H * 0.5 ? \"genis\" : dy < -40 ? \"normal\" : \"tam\";\n      if (k !== k0) panelAyarla(k);\n    }\n    y0 = null; surukle = false;\n  };\n  panel.addEventListener(\"touchend\", bitir);\n  panel.addEventListener(\"touchcancel\", bitir);\n  // Dokunma: tam ekranda panel şeridine dokun -> normal; tutamağa dokun -> normal ↔ geniş\n  panel.addEventListener(\"click\", (e) => {\n    const k = panelKonum();\n    if (k === \"tam\") { e.stopPropagation(); e.preventDefault(); panelAyarla(\"normal\"); return; }\n    if (e.target.closest(\"#tutamak\")) panelAyarla(k === \"genis\" ? \"normal\" : \"genis\");\n  }, true);\n})();\n\n// ---------- döngüler ----------\nsetInterval(canliTur, CANLI_SN * 1000);\nsetInterval(() => { if (!document.hidden) { oluHesap(); tahminiCiz(); } }, 1000);\nsetInterval(() => { if (S.trafik && !document.hidden) trafikYukle(true); }, 120e3);\nsetInterval(() => { const p = sayfa(); if (!document.hidden && (p.tur === \"ist\" || p.tur === \"yakin\")) ciz(); }, 60e3);\n\nayarYukle().finally(async () => {\n  S.trafik = !!(await KV.get(\"trafik\")); $(\"#trafikBtn\").classList.toggle(\"acik\", S.trafik); if (S.trafik) trafikYukle();\n  ciz(true);\n});\n})();\n</script>\n</body>\n</html>\n";

// ---- Kalıcı kayıt: her anahtar ayrı dosya (trafik geometrisi gibi büyük veriler için) ----
const fm = FileManager.local();
const klasor = fm.joinPath(fm.documentsDirectory(), "istanbul-ulasim");
if (!fm.fileExists(klasor)) fm.createDirectory(klasor, true);
function dosyaAdi(key) {
  let h = 0; for (let i = 0; i < key.length; i++) h = (h * 31 + key.charCodeAt(i)) >>> 0;
  return key.replace(/[^a-zA-Z0-9._-]/g, "_").slice(0, 60) + "-" + h.toString(36) + ".json";
}
function kvOku(key) {
  const yol = fm.joinPath(klasor, dosyaAdi(key));
  try { return fm.fileExists(yol) ? JSON.parse(fm.readString(yol)) : null; } catch (e) { return null; }
}
function kvYaz(key, value) {
  try { fm.writeString(fm.joinPath(klasor, dosyaAdi(key)), JSON.stringify(value)); } catch (e) { console.error(e); }
}

// ---- Sayfadan gelen istekleri karşıla ----
async function karsila(kind, a) {
  switch (kind) {
    case "http": {
      const r = new Request(a.url);
      r.method = a.method || "GET";
      r.timeoutInterval = 25;
      r.headers = Object.assign({ "User-Agent": "Mozilla/5.0 (iPhone; CPU iPhone OS 17_0 like Mac OS X) IstanbulUlasim/" + SURUM }, a.headers || {});
      if (a.body != null) r.body = a.body;
      const text = await r.loadString();
      const status = (r.response && r.response.statusCode) || 0;
      return { status, text };
    }
    case "kvget": return kvOku(a.key);
    case "kvset": kvYaz(a.key, a.value); return true;
    case "location": {
      Location.setAccuracyToBest();
      const l = await Location.current();
      return { lat: l.latitude, lon: l.longitude, acc: l.horizontalAccuracy };
    }
    case "open": Safari.open(a.url); return true;
    default: throw new Error("Bilinmeyen istek: " + kind);
  }
}

const bekle = (ms) => new Promise((res) => Timer.schedule(ms, false, res));

const wv = new WebView();
await wv.loadHTML(HTML.replace("<head>", "<head><script>window.__SCRIPTABLE__=true;</script>"), "https://istanbul-ulasim.app/");

let kapandi = false;
const sunum = wv.present(true).then(() => { kapandi = true; });

// Basit ve güvenli köprü: sayfadaki kuyruğu 120 ms'de bir boşalt, cevapları toplu teslim et.
// Tüm evaluateJavaScript çağrıları bu döngüde sırayla yapılır, aynı anda iki çağrı olmaz.
const giden = [];
let bosTur = 0;
while (!kapandi) {
  let istekler = [];
  try {
    const s = await wv.evaluateJavaScript("typeof __bridgeTake==='function' ? __bridgeTake() : '[]'", false);
    istekler = JSON.parse(s || "[]");
  } catch (e) { istekler = []; }

  for (const q of istekler) {
    karsila(q.kind, q.args || {}).then(
      (data) => giden.push({ id: q.id, ok: true, data }),
      (err) => giden.push({ id: q.id, ok: false, data: String((err && err.message) || err) })
    );
  }

  if (giden.length) {
    const paket = giden.splice(0);
    try { await wv.evaluateJavaScript("__bridgeDeliver(" + JSON.stringify(paket) + ");0", false); } catch (e) { console.error(e); }
  }

  bosTur = istekler.length || giden.length ? 0 : bosTur + 1;
  await bekle(bosTur > 50 ? 300 : 120);
}

await sunum;
Script.complete();
